ISTANBUL_TZ = ZoneInfo("Europe/Istanbul")


def _now_istanbul() -> datetime:
    return datetime.now(ISTANBUL_TZ)


def _now_istanbul_naive() -> datetime:
    return _now_istanbul().replace(tzinfo=None)


def _safe_zoneinfo(name: str | None) -> ZoneInfo:
    raw = str(name or "").strip() or "Europe/Istanbul"
    try:
        return ZoneInfo(raw)
    except Exception:
        return ISTANBUL_TZ


def _tenant_timezone_name(db: Session, tenant_id: int | None) -> str:
    if not tenant_id:
        return "Europe/Istanbul"
    tenant = db.query(Tenant).filter(Tenant.id == int(tenant_id)).first()
    raw = str(getattr(tenant, "timezone", "") or "").strip() if tenant else ""
    return raw or "Europe/Istanbul"


def _now_for_tenant(db: Session, tenant_id: int | None) -> datetime:
    return datetime.now(_safe_zoneinfo(_tenant_timezone_name(db, tenant_id)))


def _validate_timezone_name(raw: str | None) -> str:
    name = str(raw or "").strip() or "Europe/Istanbul"
    try:
        ZoneInfo(name)
    except Exception:
        raise HTTPException(status_code=400, detail="invalid timezone")
    return name


def _excel_px_to_width(px: int) -> float:
    p = max(12, int(px or 12))
    return max(1.0, (p - 5) / 7.0)


def _excel_min_char_from_px(px: int) -> int:
    return max(1, int(round(_excel_px_to_width(px))))


def _cell_text_len(v) -> int:
    if v is None:
        return 0
    s = str(v)
    if not s:
        return 0
    parts = s.splitlines() or [s]
    return max(len(p) for p in parts)


def _autosize_excel_columns(ws, min_px: int = EXCEL_MIN_COL_PX, max_char: int = 120):
    if ws is None:
        return
    min_char = _excel_min_char_from_px(min_px)
    max_col = int(ws.max_column or 0)
    max_row = int(ws.max_row or 0)
    if max_col <= 0 or max_row <= 0:
        return
    for col_idx in range(1, max_col + 1):
        best = min_char
        for row_idx in range(1, max_row + 1):
            v = ws.cell(row=row_idx, column=col_idx).value
            l = _cell_text_len(v)
            if l > best:
                best = l
        # Keep a tiny visual padding.
        best = min(max_char, best + 2)
        ws.column_dimensions[get_column_letter(col_idx)].width = float(best)


def _load_unicode_emoji_catalog() -> dict:
    global _UNICODE_EMOJI_CATALOG_CACHE
    if isinstance(_UNICODE_EMOJI_CATALOG_CACHE, dict):
        return _UNICODE_EMOJI_CATALOG_CACHE
    base = {
        "all": [],
        "smileys": [],
        "people": [],
        "travel": [],
        "objects": [],
        "symbols": [],
        "flags": [],
    }
    keywords: dict[str, str] = {}
    slug_map = {
        "smileys_emotion": "smileys",
        "people_body": "people",
        "travel_places": "travel",
        "objects": "objects",
        "symbols": "symbols",
        "flags": "flags",
        "animals_nature": "objects",
        "food_drink": "objects",
        "activities": "objects",
        "component": "people",
    }
    seen_all: set[str] = set()
    seen_cat: dict[str, set[str]] = {k: set() for k in base.keys()}
    try:
        raw = json.loads(UNICODE_EMOJI_DATA_PATH.read_text(encoding="utf-8"))
        groups = raw if isinstance(raw, list) else []
        for grp in groups:
            slug = str((grp or {}).get("slug") or "").strip().lower()
            cat = slug_map.get(slug)
            emojis = (grp or {}).get("emojis") or []
            if not isinstance(emojis, list):
                continue
            for item in emojis:
                if not isinstance(item, dict):
                    continue
                e = str(item.get("emoji") or "").strip()
                if not e:
                    continue
                if e not in seen_all:
                    seen_all.add(e)
                    base["all"].append(e)
                if cat and e not in seen_cat[cat]:
                    seen_cat[cat].add(e)
                    base[cat].append(e)
                nm = str(item.get("name") or "").strip().lower()
                if nm:
                    keywords[e] = nm
    except Exception:
        pass
    _UNICODE_EMOJI_CATALOG_CACHE = {"categories": base, "keywords": keywords}
    return _UNICODE_EMOJI_CATALOG_CACHE
