        + '.head #globalFinanceRightLink, .head .admin-menu > .admin-btn { border:1.5px solid rgba(159,216,255,0.78) !important; border-radius:8px !important; background:rgba(7,19,46,0.28) !important; color:#9FD8FF !important; font-weight:600 !important; box-shadow:none !important; }'
