def _kayit_display_id_from_data(data_obj: dict | None) -> str:
    d = data_obj if isinstance(data_obj, dict) else {}
    raw = str(
        d.get("f_project_person_code")
        or d.get("project_person_code")
        or d.get("f_organizasyon_kimligi")
        or d.get("organizasyon_kimligi")
        or d.get("organization_id")
        or ""
    ).strip().upper()
    if re.fullmatch(r"[A-Z0-9]{6}", raw):
        return raw
    m = re.search(r"([A-Z0-9]{6})$", raw)
    return m.group(1) if m else ""


