def _resolve_kayit_rows_for_export(
    db: Session,
    current_user: User,
    export_type: str,
    project_id: int | None = None,
    row_ids: list[int] | None = None,
) -> tuple[int | None, list[ModuleData]]:
    _require_module_access(db, current_user, "kayit")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    query = db.query(ModuleData).filter(ModuleData.module_name == "kayit")
    query = query.filter(
        or_(
            ModuleData.entity_type.is_(None),
            ~ModuleData.entity_type.in_(["sponsor_firma", "company", "firma"]),
        )
    )
    if not is_superadmin(current_user):
        query = query.filter(ModuleData.tenant_id == current_user.tenant_id)
    if not management_scope:
        query = query.filter(ModuleData.project_id == scoped_project_id)
    elif scoped_project_id is not None:
        query = query.filter(ModuleData.project_id == scoped_project_id)

    if export_type == "companies":
        query = query.filter(ModuleData.entity_type.in_(["sponsor_firma", "company", "firma"]))
    else:
        query = query.filter(or_(ModuleData.entity_type.is_(None), ~ModuleData.entity_type.in_(["sponsor_firma", "company", "firma"])))

    if row_ids:
        safe_ids = [int(x) for x in row_ids if int(x or 0) > 0]
        if safe_ids:
            query = query.filter(ModuleData.id.in_(safe_ids))
    rows = query.order_by(ModuleData.created_at.desc()).all()
    return scoped_project_id, rows


def _build_xlsx_stream(
    columns: list[tuple[str, str, int]],
    rows: list[dict],
    sheet_name: str,
    *,
    blank_rows: int = 0,
    validations: dict[str, list[str]] | None = None,
    guide_lines: list[str] | None = None,
    sample_row: dict | None = None,
    autofit_exclude_labels: set[str] | None = None,
) -> io.BytesIO:
    wb = Workbook()
    ws = wb.active
    ws.title = sheet_name[:31]
    ws.freeze_panes = "A2"
    header_font = Font(bold=True)
    outer_side = Side(style="thin", color="0A1024")
    inner_side = Side(style="hair", color="0A1024")

    def table_border_for(row_index: int, col_index: int, max_row: int, max_col: int) -> Border:
        return Border(
            left=outer_side if col_index == 1 else inner_side,
            right=outer_side if col_index == max_col else inner_side,
            top=outer_side if row_index == 1 else inner_side,
            bottom=outer_side if row_index == max_row else inner_side,
        )
    header_fill = PatternFill("solid", fgColor="F0F5FF")
    even_fill = PatternFill("solid", fgColor="F8FBFF")
    for col_index, (_, label, width) in enumerate(columns, start=1):
        cell = ws.cell(row=1, column=col_index, value=label)
        cell.font = header_font
        cell.alignment = Alignment(horizontal="center", vertical="center")
        cell.fill = header_fill
        ws.column_dimensions[get_column_letter(col_index)].width = width
    effective_rows = list(rows or [])
    if sample_row:
        effective_rows = [dict(sample_row)] + effective_rows
    for row_index, item in enumerate(effective_rows, start=2):
        for col_index, (key, _, _) in enumerate(columns, start=1):
            value = item.get(key, "")
            cell = ws.cell(row=row_index, column=col_index, value=value)
            cell.alignment = Alignment(vertical="top", wrap_text=True)
            if row_index % 2 == 0:
                cell.fill = even_fill
    data_start_row = 2
    data_end_row = max(data_start_row, len(effective_rows) + 1 + max(0, int(blank_rows or 0)))
    for row_index in range(len(effective_rows) + 2, data_end_row + 1):
        for col_index in range(1, len(columns) + 1):
            cell = ws.cell(row=row_index, column=col_index)
            cell.alignment = Alignment(vertical="top", wrap_text=True)
            if row_index % 2 == 0:
                cell.fill = even_fill

    max_col = len(columns)
    for row_index in range(1, data_end_row + 1):
        for col_index in range(1, max_col + 1):
            ws.cell(row=row_index, column=col_index).border = table_border_for(row_index, col_index, data_end_row, max_col)

    last_col = get_column_letter(len(columns))
    ws.auto_filter.ref = f"A1:{last_col}{data_end_row}"

    if validations:
        label_to_col = {label: idx for idx, (_, label, _) in enumerate(columns, start=1)}
        for label, options in validations.items():
            col_index = label_to_col.get(label)
            if not col_index or not options:
                continue
            formula = '"' + ",".join(str(opt).replace('"', "") for opt in options) + '"'
            dv = DataValidation(type="list", formula1=formula, allow_blank=True)
            ws.add_data_validation(dv)
            dv.add(f"{get_column_letter(col_index)}2:{get_column_letter(col_index)}{data_end_row}")

    if guide_lines:
        guide_ws = wb.create_sheet("Kılavuz")
        guide_ws.column_dimensions["A"].width = 120
        guide_ws["A1"] = f"{sheet_name} Kullanım Kılavuzu"
        guide_ws["A1"].font = Font(bold=True)
        guide_ws["A1"].alignment = Alignment(vertical="top", wrap_text=True)
        for idx, line in enumerate(guide_lines, start=3):
            guide_ws.cell(row=idx, column=1, value=line).alignment = Alignment(vertical="top", wrap_text=True)

    exclude = set(autofit_exclude_labels or set())
    if columns:
        _autosize_excel_columns(ws, min_px=EXCEL_MIN_COL_PX, max_char=64)
        for col_index, (_, label, width) in enumerate(columns, start=1):
            if label in exclude:
                ws.column_dimensions[get_column_letter(col_index)].width = width

    out = io.BytesIO()
    wb.save(out)
    out.seek(0)
    return out


def _matches_template_sample(values: dict, columns: list[tuple[str, str, int]], sample_row: dict | None) -> bool:
    if not sample_row:
        return False
    for key, label, _ in columns:
        expected = _clean_xlsx_text(sample_row.get(key, ""))
        actual = _clean_xlsx_text(values.get(label, ""))
        if actual != expected:
            return False
    return True


def _clean_xlsx_text(value) -> str:
    if value is None:
        return ""
    if isinstance(value, datetime):
        return value.strftime("%d.%m.%Y")
    return str(value).strip()


def _format_tr_date_text(value) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(raw, fmt).strftime("%d.%m.%Y")
        except Exception:
            pass
    return raw


def _parse_tr_date_for_storage(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    for fmt in ("%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%d", "%Y/%m/%d"):
        try:
            return datetime.strptime(raw, fmt).strftime("%Y-%m-%d")
        except Exception:
            pass
    return raw


def _normalize_importance_level_value(value) -> str:
    raw = str(value or "").strip().upper()
    if not raw:
        return ""
    legacy_map = {
        "A++": "A1",
        "A+": "A2",
        "A": "A3",
        "B+": "B1",
        "B": "B2",
        "C": "C1",
    }
    raw = legacy_map.get(raw, raw)
    match = re.fullmatch(r"([ABCDE])\s*([1-9])", raw)
    if not match:
        return ""
    return f"{match.group(1)}{match.group(2)}"


def _normalize_gender_value(value) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    lowered = raw.lower()
    if lowered in {"kadın", "kadin"}:
        return "Kadın"
    if lowered == "erkek":
        return "Erkek"
    if lowered in {"belirtmek istemiyor", "belirtmek istemiyorum"}:
        return "Belirtmek İstemiyor"
    return ""


def _load_logo_image(max_w: int, max_h: int) -> Image.Image | None:
    logo_path = Path(__file__).with_name("kontrast_logo.png")
    if not logo_path.exists():
        return None
    try:
        img = Image.open(logo_path).convert("RGBA")
        img.thumbnail((max_w, max_h))
        crop_px = max(0, int(round(img.width * 0.11)))
        if crop_px > 0 and img.width - crop_px > 10:
            img = img.crop((0, 0, img.width - crop_px, img.height))
        return img
    except Exception:
        return None


def _text_wrap_for_width(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.ImageFont, max_width: int) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return [""]
    if "\n" in raw:
        out_lines: list[str] = []
        for part in raw.splitlines():
            part = str(part or "").strip()
            if not part:
                continue
            words = part.split()
            if not words:
                out_lines.append(part)
                continue
            current = words[0]
            for word in words[1:]:
                trial = current + " " + word
                box = draw.textbbox((0, 0), trial, font=font)
                if (box[2] - box[0]) <= max_width:
                    current = trial
                else:
                    out_lines.append(current)
                    current = word
            out_lines.append(current)
            if len(out_lines) >= 3:
                break
        return (out_lines or [""])[:3]
    words = raw.split()
    if not words:
        return [raw]
    lines: list[str] = []
    current = words[0]
    for word in words[1:]:
        trial = current + " " + word
        box = draw.textbbox((0, 0), trial, font=font)
        if (box[2] - box[0]) <= max_width:
            current = trial
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines[:3]


def _normalize_pdf_duplicate_text(value) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def _normalize_pdf_identity_text(value) -> str:
    return re.sub(r"[^0-9A-Za-z]", "", str(value or "").strip()).upper()


def _attach_pdf_alerts(rows: list[dict], kind: str) -> list[dict]:
    items = [dict(row or {}) for row in list(rows or [])]
    if not items:
        return items
    if kind == "people":
        name_counts: dict[str, int] = {}
        kimlik_counts: dict[str, int] = {}
        for row in items:
            full_name = " ".join(
                [str(row.get("isim") or "").strip(), str(row.get("soyisim") or "").strip()]
            ).strip()
            name_key = _normalize_pdf_duplicate_text(full_name)
            kimlik_key = _normalize_pdf_identity_text(row.get("kimlik_no"))
            if name_key:
                name_counts[name_key] = int(name_counts.get(name_key) or 0) + 1
            if kimlik_key:
                kimlik_counts[kimlik_key] = int(kimlik_counts.get(kimlik_key) or 0) + 1
        for row in items:
            alerts: dict[str, str] = {}
            full_name = " ".join(
                [str(row.get("isim") or "").strip(), str(row.get("soyisim") or "").strip()]
            ).strip()
            name_key = _normalize_pdf_duplicate_text(full_name)
            kimlik_key = _normalize_pdf_identity_text(row.get("kimlik_no"))
            if name_key and int(name_counts.get(name_key) or 0) > 1:
                alerts["ad_soyad"] = "Aynı Ad Soyad uyarısı"
                alerts["isim"] = "Aynı Ad Soyad uyarısı"
                alerts["soyisim"] = "Aynı Ad Soyad uyarısı"
            if kimlik_key and int(kimlik_counts.get(kimlik_key) or 0) > 1:
                alerts["kimlik_no"] = "Aynı Kimlik No uyarısı"
            row["__cell_alerts"] = alerts
        return items
    if kind == "companies":
        display_counts: dict[str, int] = {}
        legal_counts: dict[str, int] = {}
        tax_counts: dict[str, int] = {}
        for row in items:
            display_key = _normalize_pdf_duplicate_text(row.get("display_name"))
            legal_key = _normalize_pdf_duplicate_text(row.get("legal_name"))
            tax_key = _normalize_pdf_identity_text(row.get("tax_number"))
            if display_key:
                display_counts[display_key] = int(display_counts.get(display_key) or 0) + 1
            if legal_key:
                legal_counts[legal_key] = int(legal_counts.get(legal_key) or 0) + 1
            if tax_key:
                tax_counts[tax_key] = int(tax_counts.get(tax_key) or 0) + 1
        for row in items:
            alerts: dict[str, str] = {}
            display_key = _normalize_pdf_duplicate_text(row.get("display_name"))
            legal_key = _normalize_pdf_duplicate_text(row.get("legal_name"))
            tax_key = _normalize_pdf_identity_text(row.get("tax_number"))
            if display_key and int(display_counts.get(display_key) or 0) > 1:
                alerts["display_name"] = "Aynı Firma Adı uyarısı"
            if legal_key and int(legal_counts.get(legal_key) or 0) > 1:
                alerts["legal_name"] = "Aynı Firma Ünvanı uyarısı"
            if tax_key and int(tax_counts.get(tax_key) or 0) > 1:
                alerts["tax_number"] = "Aynı Vergi No uyarısı"
            row["__cell_alerts"] = alerts
        return items
    return items


def _build_pdf_summary_sections(kind: str, rows: list[dict]) -> list[tuple[str, list[str]]]:
    items = list(rows or [])
    sections: list[tuple[str, list[str]]] = []
    if kind == "people":
        importance = Counter(str(r.get("importance_level") or "").strip() for r in items if str(r.get("importance_level") or "").strip())
        gender = Counter(str(r.get("cinsiyet") or "").strip() for r in items if str(r.get("cinsiyet") or "").strip())
        roles = Counter(str(r.get("unvan") or "").strip() for r in items if str(r.get("unvan") or "").strip())
        kurum_unique = {str(r.get("kurum") or "").strip() for r in items if str(r.get("kurum") or "").strip()}
        dup_name = sum(1 for r in items if "ad_soyad" in dict(r.get("__cell_alerts") or {}))
        dup_kimlik = sum(1 for r in items if "kimlik_no" in dict(r.get("__cell_alerts") or {}))
        sections.append(("Genel", [
            f"Toplam kayıt: {len(items)}",
            f"Tekil kurum sayısı: {len(kurum_unique)}",
            f"Ad Soyad uyarılı kayıt: {dup_name}",
            f"Kimlik No uyarılı kayıt: {dup_kimlik}",
        ]))
        if importance:
            sections.append(("Önem Dağılımı", [f"{k}: {v}" for k, v in sorted(importance.items())]))
        if gender:
            sections.append(("Cinsiyet Dağılımı", [f"{k}: {v}" for k, v in sorted(gender.items())]))
        if roles:
            sections.append(("Görev Dağılımı", [f"{k}: {v}" for k, v in roles.most_common(20)]))
        return sections
    if kind == "companies":
        city = Counter(str(r.get("city") or "").strip() for r in items if str(r.get("city") or "").strip())
        dup_display = sum(1 for r in items if "display_name" in dict(r.get("__cell_alerts") or {}))
        dup_legal = sum(1 for r in items if "legal_name" in dict(r.get("__cell_alerts") or {}))
        dup_tax = sum(1 for r in items if "tax_number" in dict(r.get("__cell_alerts") or {}))
        rep_phone = sum(1 for r in items if str(r.get("rep_phone") or "").strip())
        rep_email = sum(1 for r in items if str(r.get("rep_email") or "").strip())
        sections.append(("Genel", [
            f"Toplam firma: {len(items)}",
            f"Temsilci telefonu dolu: {rep_phone}",
            f"Temsilci mail dolu: {rep_email}",
            f"Firma Adı uyarılı kayıt: {dup_display}",
            f"Firma Ünvanı uyarılı kayıt: {dup_legal}",
            f"Vergi No uyarılı kayıt: {dup_tax}",
        ]))
        if city:
            sections.append(("İl Dağılımı", [f"{k}: {v}" for k, v in city.most_common(10)]))
        return sections
    return sections


def _compact_pdf_phone_fields(rows: list[dict], fields: list[str]) -> list[dict]:
    items: list[dict] = []
    for row in list(rows or []):
        obj = dict(row or {})
        for field in fields:
            if field in obj:
                obj[field] = _format_kayit_phone_display(obj.get(field), spaced=False)
        items.append(obj)
    return items


def _filter_pdf_columns_by_data(columns: list[tuple[str, str, int]], rows: list[dict]) -> list[tuple[str, str, int]]:
    if not rows:
        return list(columns or [])
    keep: list[tuple[str, str, int]] = []
    for col in list(columns or []):
        key = str(col[0] or "")
        if any(str((row or {}).get(key) or "").strip() for row in rows):
            keep.append(col)
    return keep


def _fit_font_for_text(text: str, base_pt: float, min_pt: float, max_width: int, dpi: int, font_family: str = "Arial"):
    current_pt = float(base_pt)
    normalized = str(text or "")
    while current_pt >= float(min_pt):
        font = _load_draw_font(font_family, current_pt, dpi)
        temp = Image.new("RGB", (10, 10), "#fff")
        draw = ImageDraw.Draw(temp)
        box = draw.textbbox((0, 0), normalized, font=font)
        if (box[2] - box[0]) <= max_width:
            return font
        current_pt -= 0.5
    return _load_draw_font(font_family, min_pt, dpi)


def _build_pdf_row_layout(
    temp_draw: ImageDraw.ImageDraw,
    row: dict,
    columns: list[tuple[str, str, int]],
    col_widths: list[int],
    font_regular: ImageFont.ImageFont,
    line_h: int,
    no_wrap_keys: set[str],
) -> tuple[list[list[str]], int]:
    wrapped_per_col: list[list[str]] = []
    max_lines = 1
    for idx, (key, _, _) in enumerate(columns):
        if key == "ad_soyad":
            full_name = str(row.get("ad_soyad") or "").strip()
            if not full_name:
                full_name = " ".join([str(row.get("isim") or "").strip(), str(row.get("soyisim") or "").strip()]).strip()
            parts = full_name.split()
            if len(parts) >= 2:
                lines = [" ".join(parts[:-1]), parts[-1]]
            else:
                lines = [full_name or ""]
        elif key in no_wrap_keys:
            lines = [str(row.get(key, "") or "").strip()]
        else:
            lines = _text_wrap_for_width(temp_draw, row.get(key, ""), font_regular, max(20, col_widths[idx] - 8))
        wrapped_per_col.append(lines)
        max_lines = max(max_lines, len(lines))
    row_h = max(24, 8 + (max_lines * line_h))
    return wrapped_per_col, row_h


def _build_table_pdf_stream(
    title: str,
    subtitle: str,
    columns: list[tuple[str, str, int]],
    rows: list[dict],
    filename: str,
    summary_sections: list[tuple[str, list[str]]] | None = None,
) -> StreamingResponse:
    page_w, page_h = 1754, 1240  # A4 landscape approx @150dpi
    margin_x, margin_y = 40, 34
    header_h = 70
    footer_h = 56
    table_top = margin_y + header_h + 10
    table_bottom = page_h - margin_y - footer_h
    available_h = table_bottom - table_top

    logo = _load_logo_image(250, 60)
    font_regular = _load_draw_font("Arial", 8, 150)
    font_bold = _load_draw_font("Arial", 8, 150)
    font_title = _load_draw_font("Arial", 12, 150)
    line_h = 16
    header_row_h = 24
    no_wrap_keys = {"organization_id", "unvan", "akademik_unvan", "ad_soyad", "kimlik_no", "telefon", "mail"}

    total_weight = sum(max(1, int(width or 1)) for _, _, width in columns)
    usable_w = page_w - (margin_x * 2)
    col_widths: list[int] = [max(52, int(usable_w * (max(1, int(width or 1)) / total_weight))) for _, _, width in columns]
    width_diff = usable_w - sum(col_widths)
    if col_widths:
        col_widths[-1] += width_diff

    temp_img = Image.new("RGB", (10, 10), "#fff")
    temp_draw = ImageDraw.Draw(temp_img)
    header_wrapped: list[list[str]] = []
    header_max_lines = 1
    for idx, (_, label, _) in enumerate(columns):
        lines = _text_wrap_for_width(temp_draw, str(label or ""), font_bold, max(20, col_widths[idx] - 8))
        header_wrapped.append(lines)
        header_max_lines = max(header_max_lines, len(lines))
    header_row_h = max(24, 8 + (header_max_lines * line_h))

    pages: list[list[dict]] = []
    page_rows: list[dict] = []
    current_h = header_row_h
    for row in rows:
        _, row_h = _build_pdf_row_layout(temp_draw, row, columns, col_widths, font_regular, line_h, no_wrap_keys)
        if current_h + row_h > available_h and page_rows:
            pages.append(page_rows)
            page_rows = []
            current_h = header_row_h
        page_rows.append(row)
        current_h += row_h
    if page_rows or not pages:
        pages.append(page_rows)

    total_pages = len(pages) + (1 if summary_sections else 0)
    rendered_pages: list[Image.Image] = []
    for page_index, page_rows in enumerate(pages, start=1):
        img = Image.new("RGB", (page_w, page_h), "#ffffff")
        draw = ImageDraw.Draw(img)
        left_band_w = 208
        draw.rounded_rectangle((0, 0, left_band_w, 64), radius=0, fill="#0A1024")
        if logo is not None:
            img.paste(logo, (margin_x, 4), logo)
        title_box = draw.textbbox((0, 0), title, font=font_title)
        title_w = title_box[2] - title_box[0]
        draw.text(((page_w - title_w) / 2, 18), title, fill="#0A214A", font=font_title)
        subtitle_box = draw.textbbox((0, 0), subtitle, font=font_regular)
        subtitle_w = subtitle_box[2] - subtitle_box[0]
        sub_pad_x = 12
        sub_x0 = max(page_w - margin_x - subtitle_w - (sub_pad_x * 2), left_band_w + 28)
        draw.rounded_rectangle((sub_x0, 12, page_w - margin_x, 52), radius=10, fill="#0A1024")
        draw.text((page_w - margin_x - subtitle_w - sub_pad_x, 24), subtitle, fill="#ffffff", font=font_regular)

        x = margin_x
        y = table_top
        for idx, (_, label, _) in enumerate(columns):
            w = col_widths[idx]
            draw.rectangle((x, y, x + w, y + header_row_h), fill="#eef5ff", outline="#cdd8ea")
            wrapped_lines = header_wrapped[idx][:3]
            for line_idx, line in enumerate(wrapped_lines):
                line_text = str(line)
                box = draw.textbbox((0, 0), line_text, font=font_bold)
                line_w = box[2] - box[0]
                text_x = x + max(4, int((w - line_w) / 2))
                draw.text((text_x, y + 4 + (line_idx * line_h)), line_text, fill="#0A214A", font=font_bold)
            x += w

        y += header_row_h
        for row_idx, row in enumerate(page_rows):
            wrapped_per_col, row_h = _build_pdf_row_layout(temp_draw, row, columns, col_widths, font_regular, line_h, no_wrap_keys)
            row_fill = "#ffffff" if (row_idx % 2 == 0) else "#eff6ff"
            alerts = dict(row.get("__cell_alerts") or {})
            x = margin_x
            for idx, lines in enumerate(wrapped_per_col):
                w = col_widths[idx]
                key = columns[idx][0]
                is_alert = key in alerts
                cell_fill = "#fde8e8" if is_alert else row_fill
                text_fill = "#7f1d1d" if is_alert else "#1c2635"
                draw.rectangle((x, y, x + w, y + row_h), fill=cell_fill, outline="#dde4ef")
                if is_alert:
                    draw.rectangle((x, y, x + 6, y + row_h), fill="#c62828", outline="#c62828")
                    alert_box = draw.textbbox((0, 0), "!", font=font_bold)
                    alert_w = alert_box[2] - alert_box[0]
                    draw.text((x + w - alert_w - 6, y + 4), "!", fill="#c62828", font=font_bold)
                for line_idx, line in enumerate(lines[:3]):
                    text_x = x + (10 if is_alert else 4)
                    cell_font = font_regular
                    if key in no_wrap_keys:
                        cell_font = _fit_font_for_text(str(line or ""), 8, 6, max(20, w - (16 if is_alert else 8)), 150)
                    draw.text((text_x, y + 4 + (line_idx * line_h)), line, fill=text_fill, font=cell_font)
                x += w
            y += row_h

        footer_y0 = page_h - margin_y - footer_h + 8
        footer_y1 = page_h - margin_y + 6
        draw.rectangle((margin_x - 4, footer_y0 - 2, page_w - margin_x + 4, footer_y1), fill="#ffffff", outline=None)
        draw.line((margin_x, footer_y0, page_w - margin_x, footer_y0), fill="#cfd9ea", width=1)
        footer_note = "Creatro PDF Raporu"
        draw.text((margin_x, footer_y0 + 12), footer_note, fill="#5c6b82", font=font_regular)
        page_text = f"Sayfa {page_index}/{total_pages}"
        box = draw.textbbox((0, 0), page_text, font=font_regular)
        draw.text((page_w - margin_x - (box[2] - box[0]), footer_y0 + 12), page_text, fill="#5c6b82", font=font_regular)
        rendered_pages.append(img)

    if summary_sections:
        img = Image.new("RGB", (page_w, page_h), "#ffffff")
        draw = ImageDraw.Draw(img)
        left_band_w = 208
        draw.rounded_rectangle((0, 0, left_band_w, 64), radius=0, fill="#0A1024")
        if logo is not None:
            img.paste(logo, (margin_x, 4), logo)
        summary_title = f"{title} - Rapor Özeti"
        title_box = draw.textbbox((0, 0), summary_title, font=font_title)
        title_w = title_box[2] - title_box[0]
        draw.text(((page_w - title_w) / 2, 18), summary_title, fill="#0A214A", font=font_title)
        subtitle_box = draw.textbbox((0, 0), subtitle, font=font_regular)
        subtitle_w = subtitle_box[2] - subtitle_box[0]
        sub_pad_x = 12
        sub_x0 = max(page_w - margin_x - subtitle_w - (sub_pad_x * 2), left_band_w + 28)
        draw.rounded_rectangle((sub_x0, 12, page_w - margin_x, 52), radius=10, fill="#0A1024")
        draw.text((page_w - margin_x - subtitle_w - sub_pad_x, 24), subtitle, fill="#ffffff", font=font_regular)
        y = table_top
        section_title_font = _load_draw_font("Arial", 12, 150)
        for section_title, lines in summary_sections:
            draw.rounded_rectangle((margin_x, y, page_w - margin_x, y + 34), radius=10, fill="#eef5ff", outline="#cdd8ea")
            draw.text((margin_x + 12, y + 8), section_title, fill="#0A214A", font=section_title_font)
            y += 42
            for line in list(lines or []):
                draw.text((margin_x + 14, y), f"• {line}", fill="#1c2635", font=font_regular)
                y += 24
                if y > page_h - margin_y - footer_h - 32:
                    break
            y += 12
            if y > page_h - margin_y - footer_h - 32:
                break
        footer_y0 = page_h - margin_y - footer_h + 8
        footer_y1 = page_h - margin_y + 6
        draw.rectangle((margin_x - 4, footer_y0 - 2, page_w - margin_x + 4, footer_y1), fill="#ffffff", outline=None)
        draw.line((margin_x, footer_y0, page_w - margin_x, footer_y0), fill="#cfd9ea", width=1)
        footer_note = "Creatro PDF Raporu"
        draw.text((margin_x, footer_y0 + 12), footer_note, fill="#5c6b82", font=font_regular)
        page_text = f"Sayfa {total_pages}/{total_pages}"
        box = draw.textbbox((0, 0), page_text, font=font_regular)
        draw.text((page_w - margin_x - (box[2] - box[0]), footer_y0 + 12), page_text, fill="#5c6b82", font=font_regular)
        rendered_pages.append(img)

    return _pdf_response_from_images(rendered_pages, filename=filename, dpi=150)


def _export_filename(prefix: str, ext: str, project: Project | None = None) -> str:
    code = str((project.system_code if project and project.system_code else project.operation_code if project else "") or "").strip().upper()
    suffix = code or _now_istanbul().strftime("%Y%m%d")
    return f"{prefix}_{suffix}.{ext}"


def _ensure_all_users_have_user_code(db: Session, rotate_existing: bool = False) -> int:
    users = db.query(User).order_by(User.id.asc()).all()
    changed = 0
    for u in users:
        current = str(u.user_code or "").strip().upper()
        if (not rotate_existing) and re.fullmatch(r"[A-Z0-9]{6}", current):
            continue
        u.user_code = _generate_unique_user_code(
            db=db,
            tc_kimlik_no=u.tc_kimlik_no,
            passport_no=getattr(u, "passport_no", None),
            existing_user_id=int(u.id),
        )
        changed += 1
    return changed


def _ensure_all_projects_have_system_code(db: Session) -> int:
    rows = db.query(Project).order_by(Project.id.asc()).all()
    changed = 0
    assigned_by_tenant: dict[int, set[str]] = {}
    for p in rows:
        code = str(p.system_code or "").strip().upper()
        if re.fullmatch(r"[A-Z]{3}-\d{3}", code):
            assigned_by_tenant.setdefault(int(p.tenant_id or 0), set()).add(code)
            continue
        tenant_id = int(p.tenant_id or 0)
        prefix = _tenant_project_prefix(db, tenant_id)
        assigned = assigned_by_tenant.setdefault(tenant_id, set())
        next_code = None
        for candidate in _iter_project_system_codes(prefix):
            if candidate not in assigned:
                next_code = candidate
                assigned.add(candidate)
                break
        if not next_code:
            raise HTTPException(status_code=500, detail="Project system code üretilemedi")
        p.system_code = next_code
        changed += 1
    return changed


def _find_user_by_login_identifier(db: Session, identifier: str) -> User | None:
    raw = str(identifier or "").strip()
    if not raw:
        return None
    login_email = _normalize_login_email(raw)
    login_tc = _normalize_tc_kimlik_no(raw)
    login_passport = _normalize_passport_no(raw)
    login_filters = [
        User.username == raw,
        func.lower(func.coalesce(User.username, "")) == raw.lower(),
        User.user_code == raw.upper(),
    ]
    if login_email:
        login_filters.append(func.lower(func.coalesce(User.email, "")) == login_email)
    if login_tc:
        login_filters.append(func.coalesce(User.tc_kimlik_no, "") == login_tc)
    if login_passport:
        login_filters.append(func.upper(func.coalesce(User.passport_no, "")) == login_passport)
    return db.query(User).filter(or_(*login_filters)).order_by(User.id.asc()).first()


def _send_password_reset_notification(channel: str, destination: str, message: str) -> tuple[str, str]:
    ch = str(channel or "").strip().lower()
    dest = str(destination or "").strip()
    if ch == "email":
        if SMTP_HOST and SMTP_FROM:
            try:
                msg = EmailMessage()
                msg["Subject"] = "CreaTRo Şifre Sıfırlama"
                msg["From"] = SMTP_FROM
                msg["To"] = dest
                msg.set_content(message)
                with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=12) as smtp:
                    smtp.starttls()
                    if SMTP_USER:
                        smtp.login(SMTP_USER, SMTP_PASS)
                    smtp.send_message(msg)
                return "sent", "E-posta gönderildi."
            except Exception as exc:
                return "failed", f"E-posta gönderilemedi: {exc}"
        return "queued_local", "SMTP tanımlı değil; istek kuyruğa alındı."
    if ch == "sms":
        if SMS_WEBHOOK_URL:
            try:
                req = urllib.request.Request(
                    SMS_WEBHOOK_URL,
                    data=json.dumps({"to": dest, "message": message}).encode("utf-8"),
                    headers={"Content-Type": "application/json"},
                    method="POST",
                )
                urllib.request.urlopen(req, timeout=12).read()
                return "sent", "SMS gönderildi."
            except Exception as exc:
                return "failed", f"SMS gönderilemedi: {exc}"
        return "queued_local", "SMS webhook tanımlı değil; istek kuyruğa alındı."
    return "failed", "Geçersiz kanal."


def _extract_bearer_token(authorization: str | None) -> str | None:
    if not authorization:
        return None
    parts = authorization.strip().split(" ", 1)
    if len(parts) != 2 or parts[0].lower() != "bearer":
        return None
    return parts[1].strip()


def _mask_sensitive(value):
    if isinstance(value, dict):
        masked: dict = {}
        for key, item in value.items():
            key_lower = str(key).lower()
            if key_lower in AUDIT_SENSITIVE_KEYS:
                masked[key] = "***"
            else:
                masked[key] = _mask_sensitive(item)
        return masked
    if isinstance(value, list):
        return [_mask_sensitive(item) for item in value]
    return value


def _text_encoding_noise_score(value: str) -> int:
    text = str(value or "")
    score = 0
    for bad in ("Ã", "Ä", "Å", "â", "�"):
        score += text.count(bad) * (3 if bad == "ï¿½" else 1)
    return score


def _repair_text_encoding(value):
    if not isinstance(value, str):
        return value
    text = unicodedata.normalize("NFC", value)
    best = text
    best_score = _text_encoding_noise_score(text)
    for enc in ("latin1", "cp1252"):
        try:
            candidate = unicodedata.normalize("NFC", text.encode(enc).decode("utf-8"))
        except Exception:
            continue
        candidate_score = _text_encoding_noise_score(candidate)
        if candidate_score < best_score:
            best = candidate
            best_score = candidate_score
    return best


def _normalize_text_payload(value, key: str | None = None):
    if isinstance(value, dict):
        return {item_key: _normalize_text_payload(item, item_key) for item_key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_text_payload(item, key) for item in value]
    if isinstance(value, str):
        normalized = _repair_text_encoding(value)
        if str(key or "").strip().lower() in {"soyisim", "f_soyisim", "soyad", "f_soyad", "last_name"}:
            return _upper_tr_text(normalized)
        return normalized
    return value


def _safe_int(value) -> int | None:
    if value is None:
        return None
    txt = str(value).strip()
    if not txt:
        return None
    try:
        return int(txt)
    except Exception:
        return None


def _resolve_request_project_id(request: Request, body_payload, user: User | None) -> int | None:
    query_project = _safe_int(request.query_params.get("project_id"))
    if query_project is not None:
        return query_project
    if isinstance(body_payload, dict):
        body_project = _safe_int(body_payload.get("project_id"))
        if body_project is not None:
            return body_project
    if user is not None:
        return _safe_int(user.active_project_id)
    return None


def _resolve_related_transfer_id(request: Request, body_payload) -> int | None:
    for key in ("transfer_id", "related_transfer_id"):
        if key in request.path_params:
            value = _safe_int(request.path_params.get(key))
            if value is not None:
                return value
        value = _safe_int(request.query_params.get(key))
        if value is not None:
            return value
    if isinstance(body_payload, dict):
        for key in ("transfer_id", "related_transfer_id"):
            value = _safe_int(body_payload.get(key))
            if value is not None:
                return value
    return None


def _module_key_for_request(request: Request, body_payload: dict | None = None) -> str | None:
    path = request.url.path or ""
    if any(path.startswith(pfx) for pfx in MODULE_ENFORCEMENT_EXCLUDE_PREFIXES):
        return None

    if path == "/module-data":
        module_name = request.query_params.get("module_name")
        if not module_name and isinstance(body_payload, dict):
            module_name = body_payload.get("module_name")
        if module_name:
            try:
                return _normalize_module_name(module_name)
            except HTTPException:
                return None
        return None

    for route_prefix, module_key in MODULE_ENFORCEMENT_ROUTE_MAP:
        if path == route_prefix or path.startswith(route_prefix + "/"):
            return module_key
    return None


def _classify_action(method: str, path: str) -> str:
    verb = (method or "").upper()
    if verb == "POST":
        if "/auth/login" in path:
            return "auth_login"
        return "create"
    if verb in {"PUT", "PATCH"}:
        return "update"
    if verb == "DELETE":
        return "delete"
    if verb == "GET":
        return "read"
    return verb.lower() or "unknown"


async def _read_json_body_for_audit(request: Request):
    content_type = (request.headers.get("content-type") or "").lower()
    if "application/json" not in content_type:
        return None
    content_length = _safe_int(request.headers.get("content-length")) or 0
    if content_length > 200_000:
        return {"_truncated": True, "reason": "payload_too_large", "size": content_length}
    try:
        raw = await request.body()
    except Exception:
        return None
    if not raw:
        return None
    if len(raw) > 200_000:
        return {"_truncated": True, "reason": "payload_too_large", "size": len(raw)}
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except Exception:
        return {"_raw": raw[:500].decode("utf-8", errors="ignore")}
    return _mask_sensitive(parsed)


def _read_json_response_for_audit(response):
    if response is None:
        return None
    content_type = (response.headers.get("content-type") or "").lower()
    if "application/json" not in content_type:
        return None
    raw = getattr(response, "body", None)
    if not isinstance(raw, (bytes, bytearray)) or not raw:
        return None
    if len(raw) > 200_000:
        return {"_truncated": True, "reason": "response_too_large", "size": len(raw)}
    try:
        parsed = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return None
    return _mask_sensitive(parsed)


def _find_user_by_token(db: Session, token: str | None, touch_session: bool) -> User | None:
    if not token:
        return None
    now = datetime.now(timezone.utc)
    session = (
        db.query(UserSession)
        .filter(UserSession.token == token, UserSession.expires_at > now)
        .first()
    )
    if not session:
        return None
    if touch_session:
        session.expires_at = now + timedelta(minutes=max(1, SESSION_IDLE_MINUTES))
        db.commit()
    user = db.query(User).filter(User.id == session.user_id, User.is_active.is_(True)).first()
    return user


def require_auth(
    db: Session = Depends(get_db),
    authorization: str | None = Header(default=None),
) -> User:
    token = _extract_bearer_token(authorization)
    if not token:
        raise HTTPException(status_code=401, detail="Missing bearer token")
    user = _find_user_by_token(db, token, touch_session=True)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid or expired session")
    return user


def require_admin_db_auth(
    db: Session = Depends(get_db),
    authorization: str | None = Header(default=None),
    admin_db_session: str | None = Cookie(default=None),
) -> User:
    token = _extract_bearer_token(authorization) or (str(admin_db_session or "").strip() or None)
    if not token:
        raise HTTPException(status_code=401, detail="Admin DB login required")
    user = _find_user_by_token(db, token, touch_session=True)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid or expired admin DB session")
    if normalize_role(user.role) != "superadmin":
        raise HTTPException(status_code=403, detail="Superadmin required")
    return user


def require_company_admin(current_user: User = Depends(require_auth)) -> User:
    if role_level(current_user.role) < role_level("tenant_manager"):
        raise HTTPException(status_code=403, detail="Admin or manager role required")
    return current_user


def _normalize_supplier_company_type(raw: str | None) -> str:
    v = str(raw or "").strip().lower()
    return "vehicle" if v == "vehicle" else "agency"


def _is_vehicle_supplier_admin(db: Session, user: User) -> bool:
    if normalize_role(user.role) != "supplier_admin":
        return False
    company_id = int(getattr(user, "supplier_company_id", 0) or 0)
    if company_id <= 0:
        return False
    company = db.query(SupplierCompany).filter(SupplierCompany.id == company_id).first()
    if not company:
        return False
    if int(company.tenant_id or 0) != int(user.tenant_id or 0):
        return False
    return _normalize_supplier_company_type(getattr(company, "company_type", None)) == "vehicle"


def _vehicle_supplier_company_id(db: Session, user: User) -> int | None:
    if not _is_vehicle_supplier_admin(db, user):
        return None
    cid = int(getattr(user, "supplier_company_id", 0) or 0)
    return cid if cid > 0 else None


def _vehicle_accepted_project_ids(db: Session, tenant_id: int, supplier_company_id: int) -> set[int]:
    rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "transfer",
            ModuleData.entity_type == "vehicle_project_invite",
            ModuleData.tenant_id == int(tenant_id),
        )
        .all()
    )
    out: set[int] = set()
    for r in rows:
        d = dict(r.data or {})
        try:
            scid = int(d.get("supplier_company_id") or 0)
            pid = int(d.get("project_id") or 0)
        except (TypeError, ValueError):
            continue
        status = str(d.get("status") or "").strip().lower()
        if scid == int(supplier_company_id) and pid > 0 and status == "accepted":
            out.add(pid)
    return out


def _transfer_departure_dt(transfer: Transfer) -> datetime | None:
    date_raw = str(getattr(transfer, "flight_date", "") or "").strip()
    time_raw = str(getattr(transfer, "flight_time", "") or "").strip()
    if not date_raw:
        return None
    for fmt in ("%Y-%m-%d %H:%M", "%d.%m.%Y %H:%M"):
        try:
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_raw):
                t = time_raw if re.fullmatch(r"\d{2}:\d{2}", time_raw) else "00:00"
                return datetime.strptime(f"{date_raw} {t}", "%Y-%m-%d %H:%M")
            if re.fullmatch(r"\d{2}\.\d{2}\.\d{4}", date_raw):
                t = time_raw if re.fullmatch(r"\d{2}:\d{2}", time_raw) else "00:00"
                return datetime.strptime(f"{date_raw} {t}", "%d.%m.%Y %H:%M")
        except ValueError:
            continue
    return None


def can_manage_projects(db: Session, user: User) -> bool:
    role = normalize_role(user.role)
    if role == "superadmin":
        return True
    return _is_vehicle_supplier_admin(db, user)


def can_skip_project_dates(db: Session, user: User) -> bool:
    role = normalize_role(user.role)
    if role == "superadmin":
        return True
    return _is_vehicle_supplier_admin(db, user)


def is_superadmin(user: User) -> bool:
    return (user.role or "").lower() == "superadmin"


def is_supertranslator(user: User) -> bool:
    return normalize_role(user.role) == "supertranslator"


def normalize_role(role: str | None) -> str:
    raw = str(role or "").strip().lower()
    if not raw:
        return "tenant_operator"
    return ROLE_ALIASES.get(raw, raw)


def role_level(role: str | None) -> int:
    return ROLE_LEVEL.get(normalize_role(role), 0)


def can_access_interpreter_module(user: User) -> bool:
    role = normalize_role(user.role)
    return role in {
        "interpreter",
        "tenant_manager",
        "tenant_admin",
        "supertranslator",
        "superadmin_staff",
        "superadmin",
    }


def can_assign_role(current_user: User, target_role: str) -> bool:
    if is_superadmin(current_user):
        return True
    return role_level(target_role) <= role_level(current_user.role)


def can_manage_user(current_user: User, target_user: User) -> bool:
    if is_superadmin(current_user):
        return True
    if target_user.tenant_id != current_user.tenant_id:
        return False
    return role_level(target_user.role) < role_level(current_user.role)


def _is_salon_assignable_role(role: str | None) -> bool:
    r = normalize_role(role)
    return r in {
        "tenant_operator",   # part-time/operasyon ekipleri
        "tenant_manager",
        "tenant_admin",
        "supplier_admin",    # acente tarafı
        "superadmin_staff",
        "superadmin",
    }


def _is_management_project(project: Project | None) -> bool:
    if not project:
        return False
    return str(project.operation_code or "").strip().upper() == MANAGEMENT_PROJECT_CODE


def _resolve_active_project(db: Session, user: User) -> Project | None:
    if not user.active_project_id:
        return None
    return db.query(Project).filter(Project.id == user.active_project_id).first()


def _can_user_access_project(db: Session, user: User, project: Project) -> bool:
    if is_superadmin(user):
        return True
    if not project or not user.tenant_id or int(project.tenant_id or 0) != int(user.tenant_id):
        return False
    deny = (
        db.query(UserProjectAccess)
        .filter(
            UserProjectAccess.user_id == user.id,
            UserProjectAccess.project_id == project.id,
            UserProjectAccess.is_denied.is_(True),
        )
        .first()
    )
    if deny:
        return False
    allow = (
        db.query(UserProjectAccess)
        .filter(
            UserProjectAccess.user_id == user.id,
            UserProjectAccess.project_id == project.id,
            UserProjectAccess.is_denied.is_(False),
            UserProjectAccess.can_view.is_(True),
        )
        .first()
    )
    if allow:
        return True
    return True


def _ensure_project_modules_defaults(db: Session, project_id: int) -> None:
    for key in DEFAULT_MODULE_KEYS:
        db.execute(
            text(
                "INSERT INTO project_modules (project_id, module_key, enabled) "
                "VALUES (:project_id, :module_key, true) "
                "ON CONFLICT (project_id, module_key) DO NOTHING"
            ),
            {"project_id": int(project_id), "module_key": str(key)},
        )


def _ensure_management_project_for_tenant(db: Session, tenant_id: int) -> Project:
    project = (
        db.query(Project)
        .filter(
            Project.tenant_id == tenant_id,
            Project.operation_code == MANAGEMENT_PROJECT_CODE,
        )
        .first()
    )
    if not project:
        project = Project(
            tenant_id=tenant_id,
            name="Yönetim Projesi",
            city="Sistem",
            operation_code=MANAGEMENT_PROJECT_CODE,
            token_limit=None,
            token_used=0,
            is_active=True,
        )
        db.add(project)
        db.flush()
    _ensure_project_modules_defaults(db, int(project.id))
    return project


def _is_module_enabled_for_project(db: Session, project_id: int, module_key: str) -> bool:
    row = (
        db.query(ProjectModule)
        .filter(
            ProjectModule.project_id == project_id,
            ProjectModule.module_key == str(module_key or "").strip().lower(),
        )
        .first()
    )
    if not row:
        return True
    return bool(row.enabled)


def _role_default_module_set(role: str | None) -> set[str]:
    r = normalize_role(role)
    if r == "superadmin":
        return set(MODULE_DISPLAY_ORDER)
    if r in {"superadmin_staff", "tenant_admin", "tenant_manager"}:
        return set(MODULE_DISPLAY_ORDER)
    if r == "supertranslator":
        return {"toplanti", "tercuman"}
    if r == "interpreter":
        return {"toplanti", "tercuman"}
    if r == "participant":
        return {"toplanti", "duyurular"}
    if r in {"driver", "greeter", "supplier_admin"}:
        return {"transfer"}
    return {"transfer", "operasyon", "kayit", "konaklama", "toplanti", "muhasebe_finans", "duyurular"}


def _is_user_module_allowed(db: Session, user: User, project_id: int, module_key: str) -> bool:
    mk = str(module_key or "").strip().lower()
    if mk == "yonetim":
        return normalize_role(user.role) in {"superadmin", "superadmin_staff", "tenant_admin"}
    role_key = normalize_role(user.role)
    base_allowed = _role_default_module_set(role_key)
    # Strict ceiling for scoped roles: DB override cannot expand beyond role base set.
    if role_key in {"driver", "greeter", "supplier_admin", "participant", "interpreter", "supertranslator"}:
        return mk in base_allowed
    row = (
        db.query(UserModuleAccess)
        .filter(
            UserModuleAccess.user_id == int(user.id),
            UserModuleAccess.project_id == int(project_id),
            UserModuleAccess.module_key == mk,
        )
        .first()
    )
    if row is not None:
        return bool(row.allowed)
    return mk in base_allowed


def _visible_modules_for_user(db: Session, user: User) -> list[str]:
    if is_superadmin(user) and not user.active_project_id:
        return list(MODULE_DISPLAY_ORDER)
    project = _resolve_active_project(db, user)
    if not project:
        return []
    if not _can_user_access_project(db, user, project):
        return []
    visible = []
    for mk in MODULE_DISPLAY_ORDER:
        if mk != "yonetim" and not _is_module_enabled_for_project(db, int(project.id), mk):
            continue
        if _is_user_module_allowed(db, user, int(project.id), mk):
            visible.append(mk)
    return visible


def _visible_module_payload(db: Session, user: User) -> list[dict]:
    keys = _visible_modules_for_user(db, user)
    return [
        {
            "key": mk,
            "href": MODULE_HREF_MAP.get(mk, ""),
        }
        for mk in keys
    ]


def _require_module_access(db: Session, current_user: User, module_key: str) -> None:
    mk = str(module_key or "").strip().lower()
    if is_superadmin(current_user) and not current_user.active_project_id:
        return
    project = _resolve_active_project(db, current_user)
    if not project:
        raise HTTPException(status_code=403, detail="Active project required")
    if not _can_user_access_project(db, current_user, project):
        raise HTTPException(status_code=403, detail="Project access denied")
    if mk != "yonetim" and not _is_module_enabled_for_project(db, int(project.id), mk):
        raise HTTPException(status_code=403, detail="Module disabled for active project")
    if not _is_user_module_allowed(db, current_user, int(project.id), mk):
        raise HTTPException(status_code=403, detail="Module access denied for user")


def _active_project_and_management_scope(db: Session, user: User) -> tuple[Project | None, bool]:
    active_project = _resolve_active_project(db, user)
    management_scope = bool(
        (active_project is not None and _is_management_project(active_project))
        or (is_superadmin(user) and user.active_project_id is None)
    )
    return active_project, management_scope


def _resolve_project_scope_for_user(
    db: Session,
    user: User,
    requested_project_id: int | str | None = None,
) -> tuple[int | None, bool]:
    active_project, management_scope = _active_project_and_management_scope(db, user)
    parsed_project_id: int | None = None
    if requested_project_id is not None and str(requested_project_id).strip() != "":
        try:
            parsed_project_id = int(requested_project_id)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="project_id must be integer")
    elif active_project is not None:
        parsed_project_id = int(active_project.id)

    if management_scope:
        if (
            active_project is not None
            and _is_management_project(active_project)
            and parsed_project_id == int(active_project.id)
        ):
            parsed_project_id = None
        return parsed_project_id, True

    if active_project is None:
        raise HTTPException(status_code=400, detail="Active project required")
    if parsed_project_id is not None and parsed_project_id != int(active_project.id):
        raise HTTPException(status_code=403, detail="Only active project is allowed")
    return int(active_project.id), False


def _normalize_module_name(module_name: str | None) -> str:
    name = str(module_name or "").strip().lower()
    if name not in ALLOWED_MODULE_DATA_NAMES:
        raise HTTPException(status_code=400, detail="Invalid module_name")
    return name


def _resolve_tenant_for_module_data(
    db: Session,
    current_user: User,
    scoped_project_id: int | None,
    payload_tenant_id: int | None = None,
) -> int:
    if scoped_project_id is not None:
        project = db.query(Project).filter(Project.id == scoped_project_id).first()
        if not project:
            raise HTTPException(status_code=404, detail="Project not found")
        return int(project.tenant_id)

    if not is_superadmin(current_user):
        if not current_user.tenant_id:
            raise HTTPException(status_code=400, detail="Tenant scope required")
        return int(current_user.tenant_id)

    if payload_tenant_id is None:
        raise HTTPException(status_code=400, detail="tenant_id is required in management scope")
    return int(payload_tenant_id)


def _extract_kayit_id_from_payload(payload: dict | None) -> int | None:
    payload = payload or {}
    direct = payload.get("kayit_id")
    if direct is None:
        data_obj = payload.get("data")
        if isinstance(data_obj, dict):
            direct = data_obj.get("kayit_id")
    if direct is None or str(direct).strip() == "":
        return None
    try:
        return int(direct)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="kayit_id must be integer")


def _ensure_kayit_exists_for_scope(
    db: Session,
    tenant_id: int,
    project_id: int | None,
    kayit_id: int | None,
) -> int:
    if not tenant_id:
        raise HTTPException(status_code=400, detail="Tenant scope required")
    if kayit_id is None:
        raise HTTPException(status_code=400, detail="kayit_id is required for this module")
    query = db.query(ModuleData).filter(
        ModuleData.id == kayit_id,
        ModuleData.module_name == "kayit",
        ModuleData.tenant_id == tenant_id,
    )
    if project_id is not None:
        query = query.filter(ModuleData.project_id == project_id)
    row = query.first()
    if not row:
        raise HTTPException(status_code=404, detail="Kişi kartı bulunamadı (kayit_id)")
    return int(row.id)


def _resolve_superadmin_tenant_id(db: Session, payload: dict | None = None) -> int | None:
    payload = payload or {}
    raw = payload.get("tenant_id")
    if raw is not None and str(raw).strip() != "":
        return int(raw)
    first_tenant = db.query(Tenant).order_by(Tenant.id.asc()).first()
    return int(first_tenant.id) if first_tenant else None


def _safe_name_part(value: str | None) -> str:
    txt = (value or "").strip()
    txt = re.sub(r"\s+", "_", txt)
    txt = re.sub(r"[^A-Za-z0-9._-]", "", txt)
    return txt or "BILET"


def _to_float(value) -> float:
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    raw = str(value).strip()
    if not raw:
        return 0.0
    if raw.lower() in {"hidden", "nan", "none", "-"}:
        return 0.0
    cleaned = re.sub(r"[^0-9,.\-]", "", raw)
    if not cleaned:
        return 0.0
    if cleaned.count(",") > 0 and cleaned.count(".") > 0:
        cleaned = cleaned.replace(".", "").replace(",", ".")
    elif cleaned.count(",") > 0:
        cleaned = cleaned.replace(",", ".")
    try:
        return float(cleaned)
    except Exception:
        m = re.search(r"-?\d+(?:[.,]\d+)?", cleaned)
        if not m:
            return 0.0
        try:
            return float(m.group(0).replace(",", "."))
        except Exception:
            return 0.0


def _normalize_project_city(value: str | None) -> str:
    txt = str(value or "").strip().upper()
    if not txt:
        return ""
    repl = {
        "İ": "I",
        "I·": "I",
        "Ş": "S",
        "Ğ": "G",
        "Ü": "U",
        "Ö": "O",
        "Ç": "C",
        "Â": "A",
        "Î": "I",
        "Û": "U",
    }
    for k, v in repl.items():
        txt = txt.replace(k, v)
    txt = re.sub(r"\s+", " ", txt)
    return txt


def _tenant_project_prefix(db: Session, tenant_id: int | None) -> str:
    tenant = db.query(Tenant).filter(Tenant.id == int(tenant_id or 0)).first() if tenant_id else None
    raw = str((tenant.name if tenant else "") or "").strip().upper()
    if not raw:
        return "PRJ"
    repl = {
        "İ": "I",
        "I·": "I",
        "Ş": "S",
        "Ğ": "G",
        "Ü": "U",
        "Ö": "O",
        "Ç": "C",
        "Â": "A",
        "Î": "I",
        "Û": "U",
    }
    for k, v in repl.items():
        raw = raw.replace(k, v)
    raw = re.sub(r"[^A-Z]", "", raw)
    consonants = "".join(ch for ch in raw if ch not in "AEIOUY")
    if len(consonants) < 3:
        consonants = (consonants + "".join(ch for ch in raw if ch in "AEIOUY") + "PRJ")[:3]
    return consonants[:3]


def _normalize_project_system_code(value: str | None) -> str | None:
    raw = str(value or "").strip().upper()
    if not raw:
        return None
    raw = re.sub(r"\s+", "", raw)
    if not re.fullmatch(r"[A-Z]{3}-\d{3}", raw):
        raise HTTPException(status_code=400, detail="system_code must match XXX-001..XXX-999")
    return raw


def _iter_project_system_codes(prefix: str):
    safe_prefix = re.sub(r"[^A-Z]", "", str(prefix or "").upper())[:3]
    safe_prefix = (safe_prefix + "PRJ")[:3]
    for num in range(1, 1000):
        yield f"{safe_prefix}-{num:03d}"


def _generate_project_system_code(db: Session, tenant_id: int, operation_code: str | None = None) -> str:
    prefix = _tenant_project_prefix(db, tenant_id)
    used = {
        str(code or "").strip().upper()
        for (code,) in db.query(Project.system_code).filter(Project.tenant_id == int(tenant_id)).all()
        if re.fullmatch(r"[A-Z]{3}-\d{3}", str(code or "").strip().upper())
    }
    for candidate in _iter_project_system_codes(prefix):
        if candidate not in used:
            return candidate
    raise HTTPException(status_code=500, detail="Project system code üretilemedi")


def _resequence_all_project_system_codes(db: Session) -> int:
    changed = 0
    tenant_ids = [
        int(tid)
        for (tid,) in db.query(Project.tenant_id).distinct().order_by(Project.tenant_id.asc()).all()
        if tid is not None
    ]
    for tenant_id in tenant_ids:
        prefix = _tenant_project_prefix(db, tenant_id)
        assigned: set[str] = set()
        code_iter = _iter_project_system_codes(prefix)
        rows = (
            db.query(Project)
            .filter(Project.tenant_id == int(tenant_id))
            .order_by(Project.id.asc())
            .all()
        )
        for project in rows:
            next_code = next(code_iter)
            while next_code in assigned:
                next_code = next(code_iter)
            assigned.add(next_code)
            current = str(project.system_code or "").strip().upper()
            if current != next_code:
                project.system_code = next_code
                changed += 1
    return changed


def _normalize_iso_date_or_none(value: str | None, field_name: str) -> str | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.strptime(raw, "%Y-%m-%d").strftime("%Y-%m-%d")
    except ValueError:
        raise HTTPException(status_code=400, detail=f"{field_name} must be YYYY-MM-DD")


def _safe_translation_code() -> str:
    raw = secrets.token_urlsafe(7).upper()
    raw = re.sub(r"[^A-Z0-9]", "", raw)
    return (raw[:10] or "TRN0000001")


def _public_listener_url(req: Request | None, access_code: str) -> str:
    code = str(access_code or "").strip()
    if not code:
        return ""
    if req is None:
        return f"/canli-ceviri?code={code}"
    base = str(req.base_url).rstrip("/")
    return f"{base}/canli-ceviri?code={code}"


PRODUCT_META_PREFIX = "__META__"
PRODUCT_META_DESC_SEP = "__DESC__"


def _pack_product_description(raw_description: str | None, meta: dict | None) -> str | None:
    desc = str(raw_description or "").strip()
    meta_obj = meta or {}
    has_meta = any(v not in (None, "") for v in meta_obj.values())
    if not has_meta:
        return desc or None
    payload = json.dumps(meta_obj, ensure_ascii=False, separators=(",", ":"))
    return f"{PRODUCT_META_PREFIX}{payload}{PRODUCT_META_DESC_SEP}{desc}"


def _unpack_product_description(stored_description: str | None) -> tuple[str | None, dict]:
    raw = str(stored_description or "")
    if not raw.startswith(PRODUCT_META_PREFIX):
        return (raw.strip() or None), {}
    body = raw[len(PRODUCT_META_PREFIX):]
    sep_idx = body.find(PRODUCT_META_DESC_SEP)
    if sep_idx < 0:
        return (raw.strip() or None), {}
    meta_json = body[:sep_idx]
    desc = body[sep_idx + len(PRODUCT_META_DESC_SEP):].strip() or None
    try:
        meta_obj = json.loads(meta_json)
        if not isinstance(meta_obj, dict):
            meta_obj = {}
    except Exception:
        meta_obj = {}
    return desc, meta_obj


def _normalized_person_name(transfer: Transfer | None) -> str:
    if not transfer or not transfer.passenger_name:
        return ""
    raw = str(transfer.passenger_name or "").strip()
    if (getattr(transfer, "airline", "") or "").lower() == "thy":
        parts = [p for p in raw.split() if p]
        if len(parts) >= 2:
            return " ".join(parts[1:] + [parts[0]]).strip()
    return raw


def _format_full_name_display(value: str | None) -> str:
    raw = str(value or "").strip()
    parts = [p for p in raw.split() if p]
    if not parts:
        return ""
    if len(parts) == 1:
        return parts[0].upper()
    first_names = " ".join(parts[:-1]).title()
    surname = parts[-1].upper()
    return f"{first_names} {surname}".strip()


def _display_person_name_for_transfer(transfer: Transfer | None, db: Session | None = None) -> str:
    if not transfer:
        return ""
    if getattr(transfer, "participant_kayit_id", None) and db is not None:
        linked_row = db.query(ModuleData).filter(ModuleData.id == int(transfer.participant_kayit_id)).first()
        linked_data = dict(getattr(linked_row, "data", {}) or {}) if linked_row else {}
        kayit_name = _primary_kayit_full_name(linked_data)
        if kayit_name:
            return _format_full_name_display(kayit_name)
    return _format_full_name_display(_normalized_person_name(transfer) or str(transfer.passenger_name or "").strip())


def _split_person_name(transfer: Transfer | None) -> tuple[str, str]:
    full = (_normalized_person_name(transfer) or "").strip()
    parts = [p for p in full.split() if p]
    if len(parts) <= 1:
        return full, ""
    return " ".join(parts[:-1]), parts[-1]


def _resolve_target_airports(target_airports: str | None, operation_city: str | None) -> str | None:
    def _normalize(value: str | None) -> str | None:
        raw = (value or "").strip().upper()
        if not raw:
            return None
        parts = [p.strip() for p in raw.replace(";", ",").split(",") if p.strip()]
        expanded: list[str] = []
        for p in parts:
            if p in CITY_TO_IATA:
                expanded.extend([x.strip() for x in CITY_TO_IATA[p].split(",") if x.strip()])
            elif re.fullmatch(r"[A-Z]{3}", p):
                expanded.append(p)
        if not expanded:
            return None
        # tekilleştir ve sırayı koru
        seen = set()
        ordered = []
        for c in expanded:
            if c in seen:
                continue
            seen.add(c)
            ordered.append(c)
        return ",".join(ordered) if ordered else None

    # 1) Öncelik Operasyon Şehri
    city_codes = _normalize(operation_city)
    if city_codes:
        return city_codes
    # 2) Sonra opsiyonel alan (şehir veya IATA kabul edilir)
    manual_codes = _normalize(target_airports)
    if manual_codes:
        return manual_codes
    # 3) Boşsa worker tarafında biletten otomatik bulunacak
    return DEFAULT_TARGET_AIRPORTS or None


def _join_dt(date_value: str | None, time_value: str | None) -> str | None:
    d = (date_value or "").strip()
    t = (time_value or "").strip()
    if not d and not t:
        return None
    return f"{d} {t}".strip()


def _transfer_datetimes(transfer: Transfer) -> tuple[str | None, str | None]:
    # Ã–ncelik: segment bazlÄ± net alanlar
    if transfer.trip_type == "return_only":
        dep = _join_dt(transfer.return_departure_date, transfer.return_departure_time)
        arr = _join_dt(transfer.return_arrival_date, transfer.return_arrival_time)
        if dep or arr:
            return dep, arr

    dep = _join_dt(transfer.outbound_departure_date, transfer.outbound_departure_time)
    arr = _join_dt(transfer.outbound_arrival_date, transfer.outbound_arrival_time)
    if dep or arr:
        return dep, arr

    raw = transfer.raw_parse or {}
    if isinstance(raw, dict):
        segments = raw.get("segments") or []
        if isinstance(segments, list) and segments:
            chosen = None
            if transfer.trip_type == "return_only":
                chosen = next((s for s in segments if s.get("segment_role") == "donus"), None)
            if not chosen:
                chosen = next((s for s in segments if s.get("segment_role") == "gidis"), None)
            if not chosen:
                chosen = segments[0]
            dep = _join_dt(chosen.get("departure_date"), chosen.get("departure_time"))
            arr = _join_dt(chosen.get("arrival_date"), chosen.get("arrival_time"))
            if dep or arr:
                return dep, arr

    # Fallback: eski alanlar
    dep = _join_dt(transfer.flight_date, transfer.flight_time)
    return dep, None


def _gender_label_tr(value: str | None) -> str:
    v = (value or "").lower()
    if v == "male":
        return "Erkek"
    if v == "female":
        return "Kadin"
    return "UNKNOW"


def _next_transfer_action(current: str | None) -> str | None:
    if not current:
        return TRANSFER_ACTION_FLOW[0]
    try:
        idx = TRANSFER_ACTION_FLOW.index(current)
    except ValueError:
        return TRANSFER_ACTION_FLOW[0]
    if idx >= len(TRANSFER_ACTION_FLOW) - 1:
        return None
    return TRANSFER_ACTION_FLOW[idx + 1]


def _next_personnel_action(current: str | None) -> str | None:
    if not current:
        return PERSONNEL_ACTION_FLOW[0]
    key = str(current or "").strip().lower()
    try:
        idx = PERSONNEL_ACTION_FLOW.index(key)
    except ValueError:
        return PERSONNEL_ACTION_FLOW[0]
    if idx >= len(PERSONNEL_ACTION_FLOW) - 1:
        return None
    return PERSONNEL_ACTION_FLOW[idx + 1]


def _project_trace_code(db: Session, project_id: int | None) -> str:
    if not project_id:
        return "PROJESIZ"
    project = db.query(Project).filter(Project.id == int(project_id)).first()
    if not project:
        return f"P{int(project_id)}"
    candidate = (
        str(getattr(project, "system_code", "") or "").strip()
        or str(getattr(project, "operation_code", "") or "").strip()
        or f"P{int(project.id)}"
    )
    norm = re.sub(r"[^A-Z0-9]", "", candidate.upper())
    return norm[:12] or f"P{int(project.id)}"


def _build_reservation_code(vehicle_code: str, flight_date: str | None, project_trace: str | None, sequence_no: int | None = None) -> str:
    safe_vehicle = re.sub(r"[^A-Za-z0-9]", "", (vehicle_code or "").upper())[:12] or "VEH"
    safe_date = (flight_date or _now_istanbul().strftime("%Y-%m-%d")).replace("-", "")
    safe_project = re.sub(r"[^A-Z0-9]", "", str(project_trace or "").upper())[:12] or "P0"
    if sequence_no is not None:
        seq_part = f"{int(sequence_no):06d}"
    else:
        seq_part = secrets.token_hex(2).upper()
    return f"RSV-{safe_project}-{safe_date}-{safe_vehicle}-{seq_part}"


def _build_transfer_sub_reservation_no(db: Session, reservation_code: str | None, project_id: int | None) -> str | None:
    base = str(reservation_code or "").strip().upper()
    if not base:
        return None
    q = db.query(Transfer.sub_reservation_no).filter(Transfer.reservation_code == base)
    if project_id is None:
        q = q.filter(Transfer.project_id.is_(None))
    else:
        q = q.filter(Transfer.project_id == int(project_id))
    rows = q.all()
    max_seq = 0
    for (value,) in rows:
        txt = str(value or "").strip().upper()
        if not txt:
            continue
        m = re.fullmatch(rf"{re.escape(base)}-(\d+)", txt)
        if not m:
            continue
        try:
            num = int(m.group(1))
        except Exception:
            continue
        if num > max_seq:
            max_seq = num
    next_seq = max_seq + 1
    return f"{base}-{next_seq:03d}"


def _backfill_transfer_sub_reservations(db: Session) -> dict:
    rows = (
        db.query(Transfer)
        .filter(Transfer.reservation_code.isnot(None))
        .order_by(Transfer.project_id.asc(), Transfer.reservation_code.asc(), Transfer.created_at.asc(), Transfer.id.asc())
        .all()
    )
    groups: dict[tuple[int | None, str], dict] = {}
    for r in rows:
        base = str(r.reservation_code or "").strip().upper()
        if not base:
            continue
        key = (r.project_id, base)
        if key not in groups:
            groups[key] = {"max_seq": 0, "items": []}
        groups[key]["items"].append(r)
        existing = str(r.sub_reservation_no or "").strip().upper()
        m = re.fullmatch(rf"{re.escape(base)}-(\d+)", existing)
        if m:
            try:
                seq = int(m.group(1))
            except Exception:
                seq = 0
            if seq > groups[key]["max_seq"]:
                groups[key]["max_seq"] = seq

    changed = 0
    touched_groups = 0
    for key, bundle in groups.items():
        max_seq = int(bundle["max_seq"] or 0)
        local_changed = 0
        base = key[1]
        for r in bundle["items"]:
            existing = str(r.sub_reservation_no or "").strip().upper()
            if existing and re.fullmatch(rf"{re.escape(base)}-(\d+)", existing):
                continue
            max_seq += 1
            r.sub_reservation_no = f"{base}-{max_seq:03d}"
            changed += 1
            local_changed += 1
        if local_changed:
            touched_groups += 1
    if changed:
        db.commit()
    return {"updated_rows": changed, "touched_groups": touched_groups, "total_groups": len(groups)}


def _flight_shape_label(transfer: Transfer) -> str:
    raw = transfer.raw_parse or {}
    segments = raw.get("segments") if isinstance(raw, dict) else []
    roles = [str(s.get("segment_role") or "") for s in (segments or []) if isinstance(s, dict)]
    has_gidis = "gidis" in roles
    has_donus = "donus" in roles
    has_aktarma = "aktarma" in roles
    if has_gidis and has_donus and has_aktarma:
        return "gelis+donus+aktarma"
    if has_gidis and has_donus:
        return "gelis+donus"
    if has_donus and has_aktarma:
        return "donus_aktarma"
    if has_gidis and has_aktarma:
        return "gelis_aktarma"
    if has_donus:
        return "donus"
    if has_gidis:
        return "gelis"
    if has_aktarma:
        return "aktarma"
    trip = (transfer.trip_type or "").lower()
    if trip == "return_only":
        return "donus"
    if trip == "round_trip":
        return "gelis+donus"
    if trip == "connection":
        return "aktarma"
    if trip == "one_way":
        return "gelis"
    return ""


def _parse_segment_dt(seg: dict, date_key: str, time_key: str) -> datetime | None:
    d = (seg.get(date_key) or "").strip()
    t = (seg.get(time_key) or "").strip()
    if not d or not t:
        return None
    try:
        return datetime.strptime(f"{d} {t}", "%Y-%m-%d %H:%M")
    except ValueError:
        return None


def _infer_center_airport(segments: list[dict]) -> str | None:
    # En uzun bekleme (arrival -> next departure) oluşan havalimanı operasyon merkezi adayıdır.
    best_airport = None
    best_gap = None
    for i in range(len(segments) - 1):
        cur = segments[i]
        nxt = segments[i + 1]
        if cur.get("to") != nxt.get("from"):
            continue
        arr = _parse_segment_dt(cur, "arrival_date", "arrival_time")
        dep = _parse_segment_dt(nxt, "departure_date", "departure_time")
        if not arr or not dep:
            continue
        gap = dep - arr
        if gap.total_seconds() < 0:
            continue
        if best_gap is None or gap > best_gap:
            best_gap = gap
            best_airport = cur.get("to")
    return best_airport


def _segment_rows_for_transfer(transfer: Transfer) -> list[dict]:
    raw = transfer.raw_parse or {}
    segments = raw.get("segments") if isinstance(raw, dict) else None
    if not isinstance(segments, list) or not segments:
        return [
            {
                "ucus_sekli": _flight_shape_label(transfer),
                "flight_no": transfer.flight_no,
                "from_to": f"{transfer.pickup_location or ''}/{transfer.dropoff_location or ''}".strip("/"),
                "kalkis_tarihi_saati": _transfer_datetimes(transfer)[0],
                "inis_tarihi_saati": _transfer_datetimes(transfer)[1],
            }
        ]

    center = _infer_center_airport(segments)
    first_donus_idx = None
    for i, seg in enumerate(segments):
        if (seg.get("segment_role") or "") == "donus":
            first_donus_idx = i
            break

    rows: list[dict] = []
    for i, seg in enumerate(segments):
        role = (seg.get("segment_role") or "").lower()
        ucus_sekli = ""
        if role == "gidis":
            ucus_sekli = "gelis"
        elif role == "donus":
            ucus_sekli = "donus"
        elif role == "aktarma":
            if first_donus_idx is not None and i >= first_donus_idx:
                ucus_sekli = "donus_aktarma"
            else:
                ucus_sekli = "gelis_aktarma"
        else:
            # Eski kayıtlarda role yoksa merkez havalimanına göre türet.
            from_code = seg.get("from")
            to_code = seg.get("to")
            if center and to_code == center and from_code != center:
                ucus_sekli = "gelis"
            elif center and from_code == center and to_code != center:
                ucus_sekli = "donus"
            elif first_donus_idx is not None and i >= first_donus_idx:
                ucus_sekli = "donus_aktarma"
            else:
                ucus_sekli = "gelis_aktarma"

        rows.append(
            {
                "ucus_sekli": ucus_sekli,
                "flight_no": seg.get("flight_no") or transfer.flight_no,
                "from_to": f"{seg.get('from') or ''}/{seg.get('to') or ''}".strip("/"),
                "kalkis_tarihi_saati": _join_dt(seg.get("departure_date"), seg.get("departure_time")),
                "inis_tarihi_saati": _join_dt(seg.get("arrival_date"), seg.get("arrival_time")),
            }
        )
    return rows


