@app.post("/render/bulk-layout-pdf")
def render_bulk_layout_pdf(
    payload: dict,
    current_user: User = Depends(require_auth),
):
    docs = payload.get("docs") if isinstance(payload, dict) else []
    if not isinstance(docs, list) or not docs:
        raise HTTPException(status_code=400, detail="docs is required")
    filename = str((payload or {}).get("filename") or "bulk_layout.pdf").strip() or "bulk_layout.pdf"
    dpi = int(_safe_num((payload or {}).get("dpi"), 300, 96, 600))
    pages: list[Image.Image] = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        pages.append(_render_layout_image(d, default_w_mm=90, default_h_mm=55))
    return _pdf_response_from_images(pages, filename=filename, dpi=dpi)


def _render_toblerone_image(payload: dict) -> Image.Image:
    layout = payload.get("layout") if isinstance(payload, dict) else {}
    if not isinstance(layout, dict):
        layout = {}
    text = str((payload or {}).get("text") or "").strip()
    if not text:
        text = str((payload or {}).get("name") or "").strip()
    if not text:
        text = "KONUŞMACI"

    dpi = int(_safe_num((payload or {}).get("dpi"), 300, 96, 600))
    width_mm = _safe_num(layout.get("width_mm"), 297, 10, 999.99)
    height_mm = _safe_num(layout.get("height_mm"), 105, 10, 999.99)
    img_w = _mm_to_px(width_mm, dpi)
    img_h = _mm_to_px(height_mm, dpi)
    image = Image.new("RGB", (img_w, img_h), (255, 255, 255))
    draw = ImageDraw.Draw(image)

    left_rect = (0, 0, img_w // 2, img_h)
    right_rect = (img_w // 2, 0, img_w, img_h)
    draw.rectangle(left_rect, outline=(190, 206, 235), width=max(1, int(round(dpi / 300))))
    draw.rectangle(right_rect, outline=(190, 206, 235), width=max(1, int(round(dpi / 300))))

    pt = _safe_num((payload or {}).get("font_size_pt"), 40, 10, 180)
    font_family = str((payload or {}).get("font_family") or "Arial")
    fill = _hex_to_rgb(str((payload or {}).get("font_color") or "#0a214a"))
    font = _load_draw_font(font_family, pt, dpi)

    # Left face: top->down
    txt_img = Image.new("RGBA", (img_h, img_w // 2), (255, 255, 255, 0))
    txt_draw = ImageDraw.Draw(txt_img)
    bbox = txt_draw.textbbox((0, 0), text, font=font)
    tw = max(1, bbox[2] - bbox[0])
    th = max(1, bbox[3] - bbox[1])
    tx = max(0, (txt_img.width - tw) // 2)
    ty = max(0, (txt_img.height - th) // 2)
    txt_draw.text((tx, ty), text, fill=fill + (255,), font=font)
    left_rot = txt_img.rotate(90, expand=True)
    lx = max(0, (left_rect[2] - left_rect[0] - left_rot.width) // 2)
    ly = max(0, (left_rect[3] - left_rect[1] - left_rot.height) // 2)
    image.paste(left_rot, (lx, ly), left_rot)

    # Right face: bottom->up mirrored
    txt_img2 = Image.new("RGBA", (img_h, img_w // 2), (255, 255, 255, 0))
    txt_draw2 = ImageDraw.Draw(txt_img2)
    bbox2 = txt_draw2.textbbox((0, 0), text, font=font)
    tw2 = max(1, bbox2[2] - bbox2[0])
    th2 = max(1, bbox2[3] - bbox2[1])
    tx2 = max(0, (txt_img2.width - tw2) // 2)
    ty2 = max(0, (txt_img2.height - th2) // 2)
    txt_draw2.text((tx2, ty2), text, fill=fill + (255,), font=font)
    right_rot = ImageOps.mirror(txt_img2.rotate(-90, expand=True))
    rx = right_rect[0] + max(0, (right_rect[2] - right_rect[0] - right_rot.width) // 2)
    ry = max(0, (right_rect[3] - right_rect[1] - right_rot.height) // 2)
    image.paste(right_rot, (rx, ry), right_rot)
    return image


@app.post("/render/toblerone-pdf")
def render_toblerone_pdf(
    payload: dict,
    current_user: User = Depends(require_auth),
):
    image = _render_toblerone_image(payload if isinstance(payload, dict) else {})
    dpi = int(_safe_num((payload or {}).get("dpi"), 300, 96, 600))
    return _pdf_response_from_images([image], filename="toblerone.pdf", dpi=dpi)


@app.post("/render/bulk-toblerone-pdf")
def render_bulk_toblerone_pdf(
    payload: dict,
    current_user: User = Depends(require_auth),
):
    docs = payload.get("docs") if isinstance(payload, dict) else []
    if not isinstance(docs, list) or not docs:
        raise HTTPException(status_code=400, detail="docs is required")
    dpi = int(_safe_num((payload or {}).get("dpi"), 300, 96, 600))
    pages: list[Image.Image] = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        pages.append(_render_toblerone_image(d))
    return _pdf_response_from_images(pages, filename="bulk_toblerone.pdf", dpi=dpi)


@app.get("/auth/personal-qr")
def auth_personal_qr(
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    active_project = (
        db.query(Project).filter(Project.id == current_user.active_project_id).first()
        if current_user.active_project_id
        else None
    )
    if active_project and not re.fullmatch(r"[A-Z]{3}-\d{3}", str(active_project.system_code or "").upper()):
        active_project.system_code = _generate_project_system_code(db, int(active_project.tenant_id or 0), active_project.operation_code)
        db.commit()
        db.refresh(active_project)
    project_system_code = (
        str(active_project.system_code or "").strip().upper()
        if active_project
        else "0000"
    ) or "0000"
    if not re.fullmatch(r"[A-Z]{3}-\d{3}", project_system_code):
        project_system_code = "0000"
    ucode = str(current_user.user_code or "").strip().upper() or ""
    if not re.fullmatch(r"[A-Z0-9]{6}", ucode):
        current_user.user_code = _generate_random_user_code(db, existing_user_id=int(current_user.id))
        db.commit()
        db.refresh(current_user)
        ucode = str(current_user.user_code or "").strip().upper()
    payload = f"{project_system_code}-{ucode}"
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=10,
        border=4,
    )
    qr.add_data(payload)
    qr.make(fit=True)
    img = qr.make_image(fill_color=(24, 34, 64), back_color=(255, 255, 255)).convert("RGB")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    headers = {"X-QR-Payload": payload}
    return StreamingResponse(buf, media_type="image/png", headers=headers)


@app.put("/auth/active-project")
def set_active_project(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    project_id_raw = payload.get("project_id")
    if project_id_raw is None:
        if is_superadmin(current_user):
            current_user.active_project_id = None
            db.commit()
            return {
                "ok": True,
                "active_project_id": None,
                "active_project_name": None,
                "active_project_code": None,
                "management_mode": True,
            }
        raise HTTPException(status_code=400, detail="project_id is required")
    try:
        project_id = int(project_id_raw)
    except Exception:
        raise HTTPException(status_code=400, detail="project_id must be integer")
    query = db.query(Project).filter(Project.id == project_id, Project.is_active.is_(True))
    if not is_superadmin(current_user):
        query = query.filter(Project.tenant_id == current_user.tenant_id)
    project = query.first()
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not _can_user_access_project(db, current_user, project):
        raise HTTPException(status_code=403, detail="Project access denied")
    current_user.active_project_id = project.id
    db.commit()
    return {
        "ok": True,
        "active_project_id": project.id,
        "active_project_name": project.name,
        "active_project_code": project.operation_code,
        "management_mode": False,
    }


@app.put("/auth/management-project")
def set_management_project(
    payload: dict | None = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    tenant_id = current_user.tenant_id
    if is_superadmin(current_user):
        raw = (payload or {}).get("tenant_id") if payload else None
        if raw is not None:
            try:
                tenant_id = int(raw)
            except Exception:
                raise HTTPException(status_code=400, detail="tenant_id must be integer")
        elif tenant_id is None:
            first_tenant = db.query(Tenant).order_by(Tenant.id.asc()).first()
            tenant_id = int(first_tenant.id) if first_tenant else None
    if not tenant_id:
        raise HTTPException(status_code=400, detail="tenant_id is required")
    mgmt = _ensure_management_project_for_tenant(db, int(tenant_id))
    current_user.active_project_id = mgmt.id
    db.commit()
    return {
        "ok": True,
        "active_project_id": mgmt.id,
        "active_project_name": mgmt.name,
        "active_project_code": mgmt.operation_code,
        "management_mode": False,
    }


