def _safe_font_slug(name: str) -> str:
    base = re.sub(r"[^a-zA-Z0-9]+", "_", str(name or "").strip()).strip("_").lower()
    return base or "font"


def _font_file_path_by_family(name: str) -> Path:
    return FONT_STORE_DIR / f"{_safe_font_slug(name)}.ttf"


def _font_format_by_suffix(suffix: str) -> str:
    s = str(suffix or "").strip().lower()
    if s == ".woff2":
        return "woff2"
    if s == ".woff":
        return "woff"
    if s == ".otf":
        return "opentype"
    return "truetype"


@app.get("/fonts/catalog")
def fonts_catalog():
    rows = []
    slug_to_family = {_safe_font_slug(k): k for k in WEB_FONT_SOURCES.keys()}
    try:
        for p in sorted(FONT_STORE_DIR.glob("*")):
            if not p.is_file():
                continue
            if p.suffix.lower() not in ALLOWED_FONT_UPLOAD_EXTENSIONS:
                continue
            stem = p.stem
            fam = slug_to_family.get(stem, stem.replace("_", " ").title())
            rows.append(
                {
                    "family": fam,
                    "filename": p.name,
                    "url": f"/fonts-static/{p.name}",
                    "format": _font_format_by_suffix(p.suffix),
                }
            )
    except Exception:
        rows = []
    return rows


@app.post("/fonts/ensure-web")
def fonts_ensure_web(
    payload: dict,
    current_user: User = Depends(require_auth),
):
    families = payload.get("families") or []
    if not isinstance(families, list):
        raise HTTPException(status_code=400, detail="families must be array")
    requested = [str(x or "").strip() for x in families if str(x or "").strip()]
    requested = list(dict.fromkeys(requested))

    installed = []
    skipped = []
    unsupported = []
    errors = []
    for fam in requested:
        src = WEB_FONT_SOURCES.get(fam)
        if not src:
            unsupported.append(fam)
            continue
        target = _font_file_path_by_family(fam)
        if target.exists() and target.stat().st_size > 0:
            skipped.append(fam)
            installed.append({"family": fam, "filename": target.name, "url": f"/fonts-static/{target.name}"})
            continue
        try:
            req = urllib.request.Request(src, headers={"User-Agent": "MicetroFontInstaller/1.0"})
            with urllib.request.urlopen(req, timeout=20) as r:
                data = r.read()
            if not data:
                raise RuntimeError("empty file")
            target.write_bytes(data)
            installed.append({"family": fam, "filename": target.name, "url": f"/fonts-static/{target.name}"})
        except Exception as exc:
            errors.append({"family": fam, "error": str(exc)})

    return {
        "ok": True,
        "requested": requested,
        "installed": installed,
        "skipped": skipped,
        "unsupported": unsupported,
        "errors": errors,
    }


@app.post("/fonts/upload")
def fonts_upload(
    file: UploadFile = File(...),
    family: str | None = Form(default=None),
    current_user: User = Depends(require_auth),
):
    filename = str(file.filename or "").strip()
    if not filename:
        raise HTTPException(status_code=400, detail="filename required")
    ext = Path(filename).suffix.lower()
    if ext not in ALLOWED_FONT_UPLOAD_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Unsupported font extension")
    family_name = str(family or "").strip() or Path(filename).stem.replace("_", " ").replace("-", " ").strip()
    if not family_name:
        raise HTTPException(status_code=400, detail="family required")

    base = _safe_font_slug(family_name)
    target = FONT_STORE_DIR / f"{base}{ext}"
    idx = 1
    while target.exists():
        target = FONT_STORE_DIR / f"{base}_{idx}{ext}"
        idx += 1
    try:
        with target.open("wb") as fw:
            shutil.copyfileobj(file.file, fw)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Font save failed: {exc}")
    return {
        "ok": True,
        "family": family_name,
        "filename": target.name,
        "url": f"/fonts-static/{target.name}",
        "format": _font_format_by_suffix(target.suffix),
    }


