@app.post("/auth/password-reset/request")
def auth_password_reset_request(payload: dict, db: Session = Depends(get_db)):
    identifier = str(payload.get("identifier") or "").strip()
    destination_raw = str(payload.get("destination") or "").strip()
    channel = str(payload.get("channel") or "sms").strip().lower()
    if not identifier or not destination_raw:
        raise HTTPException(status_code=400, detail="identifier and destination required")
    if channel not in {"email", "sms"}:
        raise HTTPException(status_code=400, detail="invalid channel")

    user = _find_user_by_login_identifier(db, identifier)
    if not user or not user.is_active:
        raise HTTPException(status_code=404, detail="Kullanıcı bulunamadı")

    destination = _normalize_login_email(destination_raw) if channel == "email" else _normalize_phone(destination_raw)
    if not destination:
        raise HTTPException(status_code=400, detail="Geçerli bir alıcı bilgisi girin")
    if channel == "email" and "@" not in destination:
        raise HTTPException(status_code=400, detail="Geçerli e-posta girin")
    if channel == "sms" and len(destination) < 10:
        raise HTTPException(status_code=400, detail="Geçerli telefon girin")

    reset_code = f"{secrets.randbelow(1_000_000):06d}"
    expires_at = datetime.now(timezone.utc) + timedelta(minutes=10)
    row = PasswordResetRequest(
        user_id=user.id,
        identifier=identifier,
        channel=channel,
        destination=destination,
        reset_code=reset_code,
        status="queued",
        expires_at=expires_at,
    )
    db.add(row)
    db.commit()
    db.refresh(row)

    if channel == "email":
        msg_text = f"Şifre sıfırlama kodunuz: {reset_code}. Bu kod 10 dakika geçerlidir."
    else:
        msg_text = f"CreaTRo şifre sıfırlama kodunuz: {reset_code} (10 dk)."
    status, info = _send_password_reset_notification(channel, destination, msg_text)
    row.status = status
    db.commit()

    masked = destination
    if channel == "email" and "@" in destination:
        local, domain = destination.split("@", 1)
        masked = (local[:2] + "***@" + domain) if len(local) > 2 else ("***@" + domain)
    elif channel == "sms":
        masked = ("***" + destination[-4:]) if len(destination) >= 4 else "***"
    return {"ok": True, "detail": f"Kod {masked} adresine iletildi. {info}", "expires_at": expires_at.isoformat()}


