def _parse_ticket_budget(data_obj: dict | None) -> float | None:
    if not isinstance(data_obj, dict):
        return None
    candidates = [
        data_obj.get("bilet_limiti"),
        data_obj.get("ticket_budget"),
        data_obj.get("f_bilet_limiti"),
        data_obj.get("bilet_butcesi"),
    ]
    for raw in candidates:
        if raw is None:
            continue
        txt = str(raw).strip().replace(",", ".")
        if not txt:
            continue
        try:
            v = float(txt)
            if v >= 0:
                return v
        except Exception:
            continue
    return None


def require_transfer_operator(current_user: User = Depends(require_auth)) -> User:
    if role_level(current_user.role) < role_level("supplier_admin"):
        raise HTTPException(status_code=403, detail="Transfer operator role required")
    return current_user


def _driver_panel_token_hash(raw_token: str) -> str:
    return hashlib.sha256(str(raw_token or "").encode("utf-8")).hexdigest()


def _issue_driver_panel_token(
    db: Session,
    *,
    tenant_id: int,
    project_id: int | None,
    supplier_company_id: int | None,
    panel_role: str,
    staff_id: int,
    created_by_user_id: int | None,
    ttl_minutes: int,
) -> tuple[str, DriverPanelToken]:
    role = str(panel_role or "").strip().lower()
    if role not in {"driver", "greeter"}:
        raise HTTPException(status_code=400, detail="panel_role must be driver or greeter")
    token_raw = secrets.token_urlsafe(32)
    row = DriverPanelToken(
        token_hash=_driver_panel_token_hash(token_raw),
        tenant_id=int(tenant_id),
        project_id=int(project_id) if project_id is not None else None,
        supplier_company_id=int(supplier_company_id) if supplier_company_id is not None else None,
        driver_staff_id=int(staff_id) if role == "driver" else int(staff_id),
        greeter_staff_id=int(staff_id) if role == "greeter" else None,
        panel_role=role,
        created_by_user_id=int(created_by_user_id) if created_by_user_id is not None else None,
        is_active=True,
        expires_at=datetime.now(timezone.utc) + timedelta(minutes=max(5, int(ttl_minutes))),
    )
    db.add(row)
    db.flush()
    return token_raw, row


def _get_driver_panel_token_row(db: Session, raw_token: str | None) -> DriverPanelToken | None:
    token_hash = _driver_panel_token_hash(str(raw_token or "").strip())
    if not token_hash:
        return None
    now = datetime.now(timezone.utc)
    return (
        db.query(DriverPanelToken)
        .filter(
            DriverPanelToken.token_hash == token_hash,
            DriverPanelToken.is_active.is_(True),
            DriverPanelToken.expires_at > now,
        )
        .first()
    )


def _driver_panel_transfers_query(db: Session, token_row: DriverPanelToken):
    role = str(token_row.panel_role or "driver").strip().lower()
    if role == "greeter":
        q = db.query(Transfer).filter(
            Transfer.tenant_id == int(token_row.tenant_id or 0),
            Transfer.greeter_staff_id == int(token_row.greeter_staff_id or token_row.driver_staff_id or 0),
        )
    else:
        q = db.query(Transfer).filter(
            Transfer.tenant_id == int(token_row.tenant_id or 0),
            Transfer.driver_staff_id == int(token_row.driver_staff_id or 0),
        )
    if token_row.project_id is not None:
        q = q.filter(Transfer.project_id == int(token_row.project_id))
    if token_row.supplier_company_id is not None:
        q = q.filter(Transfer.supplier_company_id == int(token_row.supplier_company_id))
    return q


def _transfer_sms_status_text(action: str | None) -> str:
    key = str(action or "").strip().lower()
    mapping = {
        "bekliyorum": "Sorumlu personelimiz sizi bekliyor.",
        "aldim": "Sorumlu personelimiz sizi aldı.",
        "biraktim": "Sorumlu personelimiz sizi bıraktı.",
        "karsilamaya_gectim": "Sürücünüz karşılama noktasına geçmiştir.",
        "karsiladim": "Sürücünüz sizi karşıladı.",
        "misafiri_bekliyorum": "Sürücünüz sizi bekliyor.",
        "misafiri_aldim": "Transferiniz başladı, sürücünüz sizi araca aldı.",
        "misafiri_biraktim": "Transferiniz tamamlandı, varış noktasına bırakıldınız.",
    }
    return mapping.get(key, f"Transfer durumunuz güncellendi: {key or '-'}")


def _normalize_person_name_for_match(value: str | None) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    txt = raw.translate(_TR_ASCII_MAP)
    txt = unicodedata.normalize("NFKD", txt)
    txt = "".join(ch for ch in txt if not unicodedata.combining(ch))
    txt = txt.encode("ascii", "ignore").decode("ascii")
    txt = re.sub(r"[^A-Za-z0-9\\s]", " ", txt).upper()
    txt = re.sub(r"\\s+", " ", txt).strip()
    return txt


def _compact_person_name(value: str | None) -> str:
    return _normalize_person_name_for_match(value).replace(" ", "")


def _tokenize_kayit_search_query(value: str | None) -> list[str]:
    raw = str(value or "").strip()
    if not raw:
        return []
    parts = re.split(r"\s+", raw)
    out: list[str] = []
    for part in parts:
        token = _compact_person_name(str(part or "").replace("*", ""))
        if token and token not in out:
            out.append(token)
    return out


def _kayit_name_candidates(data_obj: dict | None) -> list[str]:
    d = data_obj if isinstance(data_obj, dict) else {}
    out: list[str] = []
    pairs = [
        (d.get("isim"), d.get("soyisim")),
        (d.get("f_isim"), d.get("f_soyisim")),
        (d.get("ad"), d.get("soyad")),
    ]
    for a, b in pairs:
        name = (str(a or "").strip() + " " + str(b or "").strip()).strip()
        if name and name not in out:
            out.append(name)
    for key in ("full_name", "ad_soyad", "adsoyad", "f_adsoyad", "passenger_name"):
        v = str(d.get(key) or "").strip()
        if v and v not in out:
            out.append(v)
    return out


def _primary_kayit_full_name(data_obj: dict | None) -> str:
    cands = _kayit_name_candidates(data_obj)
    if cands:
        return str(cands[0] or "").strip()
    return ""


def _kayit_searchable_values(data_obj: dict | None) -> list[str]:
    d = data_obj if isinstance(data_obj, dict) else {}
    values: list[str] = []
    values.extend(_kayit_name_candidates(d))
    for key in (
        "tc",
        "tc_kimlik_no",
        "kimlik_no",
        "identity_no",
        "tckn",
        "telefon",
        "f_telefon",
        "mail",
        "f_mail",
        "cinsiyet",
        "gender",
        "kurum",
        "kurumu",
        "kurum_adi",
        "institution",
        "organization",
        "firma",
        "firma_adi",
        "company",
        "company_name",
        "universite",
        "university",
        "unvan",
        "gorev",
        "bolum",
        "sehir",
        "city",
    ):
        v = str(d.get(key) or "").strip()
        if v:
            values.append(v)
    seen = {str(v) for v in values if str(v or "").strip()}

    def _collect_all_scalar_values(obj):
        if isinstance(obj, dict):
            for vv in obj.values():
                yield from _collect_all_scalar_values(vv)
            return
        if isinstance(obj, (list, tuple, set)):
            for vv in obj:
                yield from _collect_all_scalar_values(vv)
            return
        if obj is None or isinstance(obj, bool):
            return
        if isinstance(obj, (str, int, float)):
            txt = str(obj).strip()
            if txt:
                yield txt

    for item in _collect_all_scalar_values(d):
        if item not in seen:
            seen.add(item)
            values.append(item)
    return values


def _score_kayit_search_match(data_obj: dict | None, query: str) -> tuple[int, str]:
    tokens = _tokenize_kayit_search_query(query)
    if not tokens:
        return (0, "")
    values = _kayit_searchable_values(data_obj)
    if not values:
        return (0, "")
    blob = " ".join(_normalize_person_name_for_match(v) for v in values if str(v or "").strip()).strip()
    compact_blob = blob.replace(" ", "")
    if not compact_blob:
        return (0, "")
    score = 0
    for token in tokens:
        if token == compact_blob:
            score += 500
            continue
        if token in compact_blob:
            score += 120 + min(len(token), 24)
            continue
        return (0, "")
    primary_name = _primary_kayit_full_name(data_obj)
    primary_compact = _compact_person_name(primary_name)
    query_compact = "".join(tokens)
    if primary_compact and query_compact:
        if primary_compact == query_compact:
            score += 300
        elif query_compact in primary_compact or primary_compact in query_compact:
            score += 180 - min(abs(len(primary_compact) - len(query_compact)), 24)
    return (score, primary_name)


def _find_kayit_row_by_passenger_name(
    db: Session,
    tenant_id: int,
    project_id: int | None,
    passenger_name: str | None,
) -> ModuleData | None:
    key = _compact_person_name(passenger_name)
    if not key:
        return None
    q = db.query(ModuleData).filter(
        ModuleData.module_name == "kayit",
        ModuleData.tenant_id == int(tenant_id),
    )
    if project_id is not None:
        q = q.filter(ModuleData.project_id == int(project_id))
    rows = q.order_by(ModuleData.created_at.desc(), ModuleData.id.desc()).all()
    best: ModuleData | None = None
    best_score = -1
    for row in rows:
        data_obj = row.data if isinstance(row.data, dict) else {}
        cand_names = _kayit_name_candidates(data_obj)
        for cand in cand_names:
            cand_key = _compact_person_name(cand)
            if not cand_key:
                continue
            if cand_key == key:
                return row
            score = 0
            if key and cand_key and (key in cand_key or cand_key in key):
                # Allow near matches with spacing/name-part differences but keep strict.
                diff = abs(len(cand_key) - len(key))
                if diff <= 2:
                    score = 60 - diff
            if score > best_score:
                best_score = score
                best = row
    return best if best_score >= 60 else None


def _build_transfer_card_summary(transfer: Transfer) -> str:
    route = " / ".join(
        [x for x in [str(transfer.pickup_location or "").strip(), str(transfer.dropoff_location or "").strip()] if x]
    ) or "-"
    flight_part = " ".join([x for x in [str(transfer.flight_no or "").strip(), str(transfer.flight_date or "").strip(), str(transfer.flight_time or "").strip()] if x]).strip() or "-"
    pnr = str(transfer.pnr or "").strip() or "-"
    return f"Uçuş: {flight_part} | PNR: {pnr} | Rota: {route}"


def _sync_transfer_to_kayit_card(
    db: Session,
    transfer: Transfer,
    actor_user_id: int | None = None,
) -> int | None:
    if not transfer:
        return None
    tenant_id = int(transfer.tenant_id or 0)
    if tenant_id <= 0:
        return None
    project_id = int(transfer.project_id) if transfer.project_id is not None else None
    target_row = None
    if transfer.participant_kayit_id:
        target_row = db.query(ModuleData).filter(
            ModuleData.id == int(transfer.participant_kayit_id),
            ModuleData.module_name == "kayit",
            ModuleData.tenant_id == tenant_id,
        ).first()
    if not target_row:
        target_row = _find_kayit_row_by_passenger_name(db, tenant_id, project_id, transfer.passenger_name)
    if not target_row:
        return None
    transfer.participant_kayit_id = int(target_row.id)
    data_obj = target_row.data if isinstance(target_row.data, dict) else {}
    canonical_name = _primary_kayit_full_name(data_obj)
    if canonical_name:
        transfer.passenger_name = canonical_name
    phone = str(data_obj.get("telefon") or data_obj.get("f_telefon") or "").strip()
    if phone and not str(transfer.participant_phone or "").strip():
        transfer.participant_phone = phone
    data_obj["transfer"] = _build_transfer_card_summary(transfer)
    data_obj["f_transfer"] = data_obj["transfer"]
    data_obj["transfer_flight_no"] = transfer.flight_no or ""
    data_obj["transfer_flight_date"] = transfer.flight_date or ""
    data_obj["transfer_flight_time"] = transfer.flight_time or ""
    data_obj["transfer_pnr"] = transfer.pnr or ""
    data_obj["transfer_pickup_time"] = transfer.pickup_time or ""
    data_obj["transfer_transfer_point"] = transfer.transfer_point or ""
    data_obj["transfer_vehicle_code"] = transfer.vehicle_code or ""
    data_obj["transfer_linked_transfer_id"] = int(transfer.id or 0) or None
    target_row.data = data_obj
    if actor_user_id is not None:
        target_row.updated_by_user_id = int(actor_user_id)
    return int(target_row.id)


def _safe_file_token(v: str | None, fallback: str = "DOSYA") -> str:
    raw = str(v or "").strip().upper()
    if not raw:
        raw = fallback
    raw = unicodedata.normalize("NFKD", raw).encode("ascii", "ignore").decode("ascii")
    raw = re.sub(r"[^A-Z0-9._-]+", "_", raw)
    raw = re.sub(r"_+", "_", raw).strip("._-")
    return raw or fallback


def _add_months(date_obj: datetime, months: int) -> datetime:
    m = int(months or 0)
    y = int(date_obj.year)
    mon = int(date_obj.month) + m
    while mon > 12:
        y += 1
        mon -= 12
    while mon <= 0:
        y -= 1
        mon += 12
    day = min(date_obj.day, calendar.monthrange(y, mon)[1])
    return datetime(y, mon, day, date_obj.hour, date_obj.minute, date_obj.second, date_obj.microsecond)


def _parse_project_end_date(project: Project | None) -> datetime | None:
    if not project:
        return None
    val = str(getattr(project, "end_date", "") or "").strip()
    if not val:
        return None
    try:
        return datetime.strptime(val, "%Y-%m-%d")
    except ValueError:
        return None


def _auto_cleanup_expired_ticket_uploads(db: Session, force: bool = False) -> dict:
    global _LAST_TICKET_CLEANUP_AT
    now_utc = datetime.now(timezone.utc)
    if (not force) and _LAST_TICKET_CLEANUP_AT and (now_utc - _LAST_TICKET_CLEANUP_AT).total_seconds() < 6 * 3600:
        return {"ok": True, "skipped": True, "deleted_uploads": 0, "deleted_files": 0, "detached_transfers": 0}
    _LAST_TICKET_CLEANUP_AT = now_utc
    projects = db.query(Project).filter(Project.is_active.is_(True)).all()
    expired_project_ids: list[int] = []
    for p in projects:
        end_dt = _parse_project_end_date(p)
        if not end_dt:
            continue
        expires_at = _add_months(end_dt, 2)
        if datetime.utcnow() > expires_at:
            expired_project_ids.append(int(p.id))
    if not expired_project_ids:
        return {"ok": True, "skipped": False, "deleted_uploads": 0, "deleted_files": 0, "detached_transfers": 0}
    uploads = db.query(Upload).filter(Upload.project_id.in_(expired_project_ids)).all()
    upload_ids = [int(u.id) for u in uploads if u and u.id]
    deleted_files = 0
    for u in uploads:
        fp = Path(str(u.file_path or "").strip())
        try:
            if fp.exists() and fp.is_file():
                fp.unlink()
                deleted_files += 1
        except Exception:
            pass
    detached_transfers = 0
    if upload_ids:
        detached_transfers = (
            db.query(Transfer)
            .filter(Transfer.upload_id.in_(upload_ids))
            .update({Transfer.upload_id: None}, synchronize_session=False)
        ) or 0
        db.query(Upload).filter(Upload.id.in_(upload_ids)).delete(synchronize_session=False)
    db.commit()
    return {
        "ok": True,
        "skipped": False,
        "expired_project_count": len(expired_project_ids),
        "deleted_uploads": len(upload_ids),
        "deleted_files": int(deleted_files),
        "detached_transfers": int(detached_transfers),
    }


def _lookup_kayit_phone_by_name(db: Session, tenant_id: int, project_id: int | None, full_name: str) -> str | None:
    row = _find_kayit_row_by_passenger_name(db, tenant_id, project_id, full_name)
    if not row:
        return None
    data = row.data if isinstance(row.data, dict) else {}
    phone = str(data.get("telefon") or data.get("f_telefon") or "").strip()
    return phone or None


def _queue_driver_group_sms(db: Session, base_transfer: Transfer, action_key: str | None) -> int:
    if not base_transfer:
        return 0
    group_q = db.query(Transfer).filter(
        Transfer.tenant_id == int(base_transfer.tenant_id or 0),
        Transfer.project_id == base_transfer.project_id,
    )
    if str(base_transfer.reservation_code or "").strip():
        group_q = group_q.filter(Transfer.reservation_code == base_transfer.reservation_code)
    elif str(base_transfer.vehicle_code or "").strip() and str(base_transfer.flight_date or "").strip():
        group_q = group_q.filter(
            Transfer.vehicle_code == base_transfer.vehicle_code,
            Transfer.flight_date == base_transfer.flight_date,
        )
    else:
        group_q = group_q.filter(Transfer.id == base_transfer.id)
    members = group_q.order_by(Transfer.id.asc()).all()
    if not members:
        members = [base_transfer]

    queued = 0
    status_text = _transfer_sms_status_text(action_key)
    for idx, tr in enumerate(members, start=1):
        if tr.participant_order_no is None:
            tr.participant_order_no = idx
        person_name = (_normalized_person_name(tr) or tr.passenger_name or "").strip()
        if not person_name:
            continue
        phone = str(tr.participant_phone or "").strip() or None
        if not phone:
            phone = _lookup_kayit_phone_by_name(
                db,
                int(tr.tenant_id or 0),
                int(tr.project_id) if tr.project_id is not None else None,
                person_name,
            )
            if phone:
                tr.participant_phone = phone
        if not phone:
            continue
        msg = (
            f"{idx}. sıradaki {person_name} sayın katılımcımız, {status_text} "
            f"Rezervasyon: {tr.reservation_code or '-'} | Araç: {tr.vehicle_code or '-'}"
        ).strip()
        db.add(
            SupplierSmsQueue(
                tenant_id=int(tr.tenant_id or 0),
                booking_id=None,
                to_phone=phone,
                message=msg,
                status="queued",
                error_message=None,
            )
        )
        queued += 1
    return queued


