def _iso_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _parse_dt_flexible(value: str | None) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        pass
    for fmt in ("%Y-%m-%dT%H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(raw, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    return None


def _duyuru_scope_project(db: Session, current_user: User, project_id: int | None) -> tuple[int | None, bool]:
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    return scoped_project_id, management_scope


def _kayit_targets_for_project(db: Session, current_user: User, project_id: int) -> list[dict]:
    q = db.query(ModuleData).filter(
        ModuleData.module_name == "kayit",
        ModuleData.project_id == int(project_id),
    )
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    rows = q.order_by(ModuleData.created_at.desc()).limit(10000).all()
    out: list[dict] = []
    for r in rows:
        d = r.data if isinstance(r.data, dict) else {}
        full_name = _primary_kayit_full_name(d) or f"Kayıt {r.id}"
        phone = str(d.get("telefon") or d.get("f_telefon") or "").strip()
        mail = str(d.get("mail") or d.get("f_mail") or "").strip()
        out.append({"kayit_id": int(r.id), "full_name": full_name, "phone": phone, "mail": mail})
    return out


def _norm_text(v: str | None) -> str:
    s = str(v or "").strip().lower()
    s = s.replace("ı", "i").replace("ğ", "g").replace("ü", "u").replace("ş", "s").replace("ö", "o").replace("ç", "c")
    s = re.sub(r"\s+", " ", s)
    return s


def _duyuru_item_summary(row: ModuleData) -> dict:
    data_obj = row.data if isinstance(row.data, dict) else {}
    tc = int(data_obj.get("target_count") or 0)
    dc = int(data_obj.get("delivered_count") or 0)
    cc = int(data_obj.get("clicked_count") or 0)
    return {
        "id": int(row.id),
        "kind": str(data_obj.get("kind") or ""),
        "title": str(data_obj.get("title") or ""),
        "message": str(data_obj.get("message") or ""),
        "deeplink": str(data_obj.get("deeplink") or ""),
        "emojis": str(data_obj.get("emojis") or ""),
        "send_mode": str(data_obj.get("send_mode") or "manual"),
        "status": str(data_obj.get("status") or "draft"),
        "event_key": str(data_obj.get("event_key") or ""),
        "schedule_at": str(data_obj.get("schedule_at") or ""),
        "deadline_at": str(data_obj.get("deadline_at") or ""),
        "target_count": tc,
        "target_kayit_ids": data_obj.get("target_kayit_ids") if isinstance(data_obj.get("target_kayit_ids"), list) else [],
        "delivered_count": dc,
        "clicked_count": cc,
        "not_clicked_count": max(0, dc - cc),
        "created_at": str(data_obj.get("created_at") or (row.created_at.isoformat() if row.created_at else "")),
    }


def _dispatch_duyuru_item(db: Session, item_row: ModuleData, actor_user_id: int | None = None) -> dict:
    data_obj = item_row.data if isinstance(item_row.data, dict) else {}
    if str(data_obj.get("kind") or "") != "notification":
        return {"ok": True, "delivered_count": 0, "clicked_count": int(data_obj.get("clicked_count") or 0)}
    project_id = int(item_row.project_id or 0)
    target_ids = data_obj.get("target_kayit_ids") or []
    if not isinstance(target_ids, list):
        target_ids = []
    target_ids = [int(x) for x in target_ids if str(x).strip().isdigit()]
    if not target_ids and project_id > 0:
        # fallback: active project all participants
        q = db.query(ModuleData.id).filter(ModuleData.module_name == "kayit", ModuleData.project_id == project_id).all()
        target_ids = [int(x[0]) for x in q if x and x[0]]
    if not target_ids:
        data_obj["status"] = "sent"
        data_obj["sent_at"] = _iso_now()
        data_obj["target_count"] = 0
        data_obj["delivered_count"] = 0
        item_row.data = data_obj
        if actor_user_id is not None:
            item_row.updated_by_user_id = int(actor_user_id)
        return {"ok": True, "delivered_count": 0, "clicked_count": int(data_obj.get("clicked_count") or 0)}

    existing = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "duyurular",
            ModuleData.entity_type == "delivery",
            ModuleData.project_id == item_row.project_id,
        )
        .all()
    )
    existing_pairs = set()
    for e in existing:
        d = e.data if isinstance(e.data, dict) else {}
        if int(d.get("item_id") or 0) == int(item_row.id):
            existing_pairs.add(int(d.get("kayit_id") or 0))
    delivered = 0
    for kid in target_ids:
        if kid in existing_pairs:
            continue
        drow = ModuleData(
            tenant_id=item_row.tenant_id,
            project_id=item_row.project_id,
            module_name="duyurular",
            entity_type="delivery",
            data={
                "item_id": int(item_row.id),
                "kind": "notification",
                "kayit_id": int(kid),
                "delivered_at": _iso_now(),
                "clicked_at": "",
                "push_status": "queued",
                "inapp_status": "delivered",
            },
            created_by_user_id=actor_user_id,
            updated_by_user_id=actor_user_id,
        )
        db.add(drow)
        delivered += 1
    data_obj["status"] = "sent"
    data_obj["sent_at"] = _iso_now()
    data_obj["target_count"] = len(target_ids)
    data_obj["delivered_count"] = int(data_obj.get("delivered_count") or 0) + delivered
    data_obj["clicked_count"] = int(data_obj.get("clicked_count") or 0)
    item_row.data = data_obj
    if actor_user_id is not None:
        item_row.updated_by_user_id = int(actor_user_id)
    return {"ok": True, "delivered_count": int(data_obj.get("delivered_count") or 0), "clicked_count": int(data_obj.get("clicked_count") or 0)}


def _dispatch_due_notifications(db: Session) -> None:
    now = datetime.now(timezone.utc)
    rows = (
        db.query(ModuleData)
        .filter(ModuleData.module_name == "duyurular", ModuleData.entity_type == "item")
        .order_by(ModuleData.created_at.desc())
        .limit(2000)
        .all()
    )
    for r in rows:
        d = r.data if isinstance(r.data, dict) else {}
        if str(d.get("kind") or "") != "notification":
            continue
        status = str(d.get("status") or "draft")
        mode = str(d.get("send_mode") or "manual")
        if mode == "manual" and status == "draft":
            _dispatch_duyuru_item(db, r, actor_user_id=None)
        elif mode == "scheduled" and status in {"draft", "scheduled"}:
            due_at = _parse_dt_flexible(d.get("schedule_at"))
            if due_at and due_at.tzinfo is None:
                due_at = due_at.replace(tzinfo=timezone.utc)
            if due_at and due_at <= now:
                _dispatch_duyuru_item(db, r, actor_user_id=None)
    db.commit()


@app.get("/duyurular/emojis")
def duyurular_emojis(current_user: User = Depends(require_auth)):
    _ = current_user
    return _load_unicode_emoji_catalog()


@app.get("/duyurular/targets")
def duyurular_targets(
    project_id: int | None = Query(default=None),
    limit: int = Query(default=3000, ge=1, le=10000),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, _ = _duyuru_scope_project(db, current_user, project_id)
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    rows = _kayit_targets_for_project(db, current_user, int(scoped_project_id))
    return rows[:limit]


@app.post("/duyurular/targets/by-ids")
def duyurular_targets_by_ids(
    payload: dict,
    project_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, _ = _duyuru_scope_project(db, current_user, project_id)
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    raw_ids = payload.get("ids") or []
    if not isinstance(raw_ids, list):
        raw_ids = []
    ids = [int(x) for x in raw_ids if str(x).strip().isdigit()]
    if not ids:
        return []
    q = db.query(ModuleData).filter(
        ModuleData.module_name == "kayit",
        ModuleData.project_id == int(scoped_project_id),
        ModuleData.id.in_(ids),
    )
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    rows = q.all()
    out = []
    for r in rows:
        d = r.data if isinstance(r.data, dict) else {}
        unvan = str(d.get("f_unvan_akd") or d.get("unvan_akd") or "").strip()
        isim = str(d.get("f_isim") or d.get("isim") or "").strip()
        soyisim = str(d.get("f_soyisim") or d.get("soyisim") or "").strip()
        display_name = " ".join([x for x in [unvan, isim, soyisim] if x]).strip() or (_primary_kayit_full_name(d) or f"Kayıt {r.id}")
        out.append({"kayit_id": int(r.id), "full_name": _primary_kayit_full_name(d) or display_name, "display_name": display_name})
    return out


@app.post("/duyurular/targets/resolve")
def duyurular_targets_resolve(
    payload: dict,
    project_id: int | None = Query(default=None),
    limit: int = Query(default=5000, ge=1, le=20000),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, _ = _duyuru_scope_project(db, current_user, project_id)
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    pid = int(scoped_project_id)
    query_expr_raw = str(payload.get("query_expr") or payload.get("query_all") or "").strip()
    expr_clean = query_expr_raw.strip().strip("(").strip(")")
    tokens = [_norm_text(x) for x in expr_clean.split(",") if _norm_text(x)]

    q = db.query(ModuleData).filter(ModuleData.module_name == "kayit", ModuleData.project_id == pid)
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    kayit_rows = q.order_by(ModuleData.created_at.desc()).limit(limit).all()
    by_kayit_id: dict[int, dict] = {}
    for row in kayit_rows:
        d = row.data if isinstance(row.data, dict) else {}
        unvan = str(d.get("f_unvan_akd") or d.get("unvan_akd") or "").strip()
        isim = str(d.get("f_isim") or d.get("isim") or "").strip()
        soyisim = str(d.get("f_soyisim") or d.get("soyisim") or "").strip()
        display_name = " ".join([x for x in [unvan, isim, soyisim] if x]).strip() or (_primary_kayit_full_name(d) or f"Kayıt {row.id}")
        by_kayit_id[int(row.id)] = {
            "kayit_id": int(row.id),
            "full_name": _primary_kayit_full_name(d) or f"Kayıt {row.id}",
            "display_name": display_name,
            "blob": _norm_text(json.dumps(d, ensure_ascii=False)),
        }

    transfer_blob_by_kayit: dict[int, str] = {}
    tq = db.query(Transfer).filter(Transfer.project_id == pid)
    if not is_superadmin(current_user):
        tq = tq.filter(Transfer.tenant_id == current_user.tenant_id)
    trs = tq.order_by(Transfer.created_at.desc()).limit(30000).all()
    for t in trs:
        kid = int(t.participant_kayit_id or 0)
        if kid <= 0:
            continue
        frag = " ".join(
            [
                str(t.passenger_name or ""),
                str(t.flight_no or ""),
                str(t.pnr or ""),
                str(t.trip_type or ""),
                str(t.issue_date or ""),
                str(t.pickup_time or ""),
                str(t.transfer_point or ""),
                str(t.vehicle_code or ""),
            ]
        )
        transfer_blob_by_kayit[kid] = f"{transfer_blob_by_kayit.get(kid, '')} {_norm_text(frag)}".strip()

    def token_match(token: str, hay: str) -> bool:
        if not token:
            return True
        if "*" in token:
            pattern = re.escape(token).replace("\\*", ".*")
            try:
                return re.search(pattern, hay, re.IGNORECASE) is not None
            except re.error:
                return token.replace("*", "") in hay
        return token in hay

    out = []
    for kid, rec in by_kayit_id.items():
        rec = by_kayit_id.get(int(kid))
        if not rec:
            continue
        blob = f"{str(rec.get('blob') or '')} {transfer_blob_by_kayit.get(int(kid), '')}".strip()
        ok = True
        for tok in tokens:
            if not token_match(tok, blob):
                ok = False
                break
        if not ok:
            continue
        out.append({
            "kayit_id": int(kid),
            "full_name": str(rec.get("full_name") or ""),
            "display_name": str(rec.get("display_name") or rec.get("full_name") or ""),
        })
    out.sort(key=lambda x: str(x.get("full_name") or ""))
    return out[:limit]


@app.post("/duyurular/items")
def create_duyuru_item(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, _ = _duyuru_scope_project(db, current_user, payload.get("project_id"))
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    kind = str(payload.get("kind") or "").strip().lower()
    if kind not in {"announcement", "notification"}:
        raise HTTPException(status_code=400, detail="kind must be announcement or notification")
    title = str(payload.get("title") or "").strip()
    message = str(payload.get("message") or "").strip()
    if not title or not message:
        raise HTTPException(status_code=400, detail="title and message are required")
    send_mode = str(payload.get("send_mode") or "manual").strip().lower()
    if kind == "announcement":
        send_mode = "manual"
    if send_mode not in {"manual", "scheduled", "event"}:
        raise HTTPException(status_code=400, detail="invalid send_mode")
    target_kayit_ids = payload.get("target_kayit_ids") or []
    if not isinstance(target_kayit_ids, list):
        target_kayit_ids = []
    target_kayit_ids = [int(x) for x in target_kayit_ids if str(x).strip().isdigit()]
    status = "draft"
    if kind == "announcement":
        status = "published"
    elif send_mode == "scheduled":
        status = "scheduled"
    elif send_mode == "event":
        status = "event_wait"
    row = ModuleData(
        tenant_id=int(current_user.tenant_id or 0) or None,
        project_id=int(scoped_project_id),
        module_name="duyurular",
        entity_type="item",
        data={
            "kind": kind,
            "title": title,
            "message": message,
            "deeplink": str(payload.get("deeplink") or "").strip(),
            "emojis": str(payload.get("emojis") or "").strip(),
            "links": payload.get("links") if isinstance(payload.get("links"), list) else [],
            "files": payload.get("files") if isinstance(payload.get("files"), list) else [],
            "deadline_at": str(payload.get("deadline_at") or "").strip(),
            "send_mode": send_mode,
            "schedule_at": str(payload.get("schedule_at") or "").strip(),
            "event_key": str(payload.get("event_key") or "").strip(),
            "target_kayit_ids": target_kayit_ids,
            "target_count": len(target_kayit_ids),
            "delivered_count": 0,
            "clicked_count": 0,
            "status": status,
            "created_at": _iso_now(),
        },
        created_by_user_id=int(current_user.id),
        updated_by_user_id=int(current_user.id),
    )
    db.add(row)
    db.flush()
    if kind == "notification" and send_mode == "manual":
        _dispatch_duyuru_item(db, row, actor_user_id=int(current_user.id))
    db.commit()
    db.refresh(row)
    return _duyuru_item_summary(row)


@app.get("/duyurular/items")
@app.get("/api/duyurular/items")
def list_duyuru_items(
    kind: str = Query(default="announcement"),
    project_id: int | None = Query(default=None),
    limit: int = Query(default=200, ge=1, le=1000),
    offset: int = Query(default=0, ge=0),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, management_scope = _duyuru_scope_project(db, current_user, project_id)
    _dispatch_due_notifications(db)
    q = db.query(ModuleData).filter(ModuleData.module_name == "duyurular", ModuleData.entity_type == "item")
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    if not management_scope and scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    elif scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    rows = q.order_by(ModuleData.created_at.desc(), ModuleData.id.desc()).offset(offset).limit(limit).all()
    out = []
    kind_n = str(kind or "").strip().lower()
    for r in rows:
        sm = _duyuru_item_summary(r)
        if kind_n and sm["kind"] != kind_n:
            continue
        out.append(sm)
    return out


@app.post("/duyurular/items/{item_id}/dispatch")
def dispatch_duyuru_item(
    item_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    row = db.query(ModuleData).filter(
        ModuleData.id == int(item_id),
        ModuleData.module_name == "duyurular",
        ModuleData.entity_type == "item",
    ).first()
    if not row:
        raise HTTPException(status_code=404, detail="Kayıt bulunamadı")
    if not is_superadmin(current_user) and int(row.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="forbidden")
    res = _dispatch_duyuru_item(db, row, actor_user_id=int(current_user.id))
    db.commit()
    return {"ok": True, **res, "item_id": int(row.id)}


