@app.post("/duyurular/events/trigger")
def trigger_duyuru_event(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    event_key = str(payload.get("event_key") or "").strip()
    if not event_key:
        raise HTTPException(status_code=400, detail="event_key is required")
    scoped_project_id, management_scope = _duyuru_scope_project(db, current_user, payload.get("project_id"))
    q = db.query(ModuleData).filter(ModuleData.module_name == "duyurular", ModuleData.entity_type == "item")
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    if not management_scope and scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    elif scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    rows = q.order_by(ModuleData.created_at.desc()).limit(1000).all()
    triggered = 0
    for r in rows:
        d = r.data if isinstance(r.data, dict) else {}
        if str(d.get("kind") or "") != "notification":
            continue
        if str(d.get("send_mode") or "") != "event":
            continue
        if str(d.get("event_key") or "") != event_key:
            continue
        if str(d.get("status") or "") not in {"event_wait", "draft", "scheduled"}:
            continue
        _dispatch_duyuru_item(db, r, actor_user_id=int(current_user.id))
        triggered += 1
    db.commit()
    return {"ok": True, "event_key": event_key, "triggered": triggered}


@app.post("/mobile/device/register")
def register_mobile_device(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    kayit_id = int(payload.get("kayit_id") or 0)
    if kayit_id <= 0:
        raise HTTPException(status_code=400, detail="kayit_id is required")
    platform = str(payload.get("platform") or "").strip().lower()
    if platform not in {"android", "ios"}:
        raise HTTPException(status_code=400, detail="platform must be android or ios")
    device_token = str(payload.get("device_token") or "").strip()
    if not device_token:
        raise HTTPException(status_code=400, detail="device_token is required")
    row = ModuleData(
        tenant_id=int(current_user.tenant_id or 0) or None,
        project_id=int(payload.get("project_id") or current_user.active_project_id or 0) or None,
        module_name="duyurular",
        entity_type="device",
        data={
            "kayit_id": kayit_id,
            "platform": platform,
            "device_token": device_token,
            "app_version": str(payload.get("app_version") or "").strip(),
            "created_at": _iso_now(),
        },
        created_by_user_id=int(current_user.id),
        updated_by_user_id=int(current_user.id),
    )
    db.add(row)
    db.commit()
    return {"ok": True, "id": int(row.id)}


@app.get("/mobile/inbox")
def mobile_inbox(
    kayit_id: int = Query(..., ge=1),
    project_id: int | None = Query(default=None),
    limit: int = Query(default=100, ge=1, le=500),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, management_scope = _duyuru_scope_project(db, current_user, project_id)
    _dispatch_due_notifications(db)
    q = db.query(ModuleData).filter(
        ModuleData.module_name == "duyurular",
        ModuleData.entity_type == "delivery",
    )
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    if not management_scope and scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    elif scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    deliveries = q.order_by(ModuleData.created_at.desc()).limit(5000).all()
    item_ids: list[int] = []
    filtered: list[dict] = []
    for drow in deliveries:
        d = drow.data if isinstance(drow.data, dict) else {}
        if int(d.get("kayit_id") or 0) != int(kayit_id):
            continue
        iid = int(d.get("item_id") or 0)
        if iid <= 0:
            continue
        item_ids.append(iid)
        filtered.append({"delivery_id": int(drow.id), "item_id": iid, "delivery": d})
    item_map: dict[int, ModuleData] = {}
    if item_ids:
        rows = db.query(ModuleData).filter(ModuleData.id.in_(list(set(item_ids)))).all()
        item_map = {int(x.id): x for x in rows}
    out = []
    for rec in filtered:
        item = item_map.get(int(rec["item_id"]))
        if not item:
            continue
        idata = item.data if isinstance(item.data, dict) else {}
        out.append(
            {
                "delivery_id": int(rec["delivery_id"]),
                "item_id": int(item.id),
                "title": str(idata.get("title") or ""),
                "message": str(idata.get("message") or ""),
                "deeplink": str(idata.get("deeplink") or ""),
                "emojis": str(idata.get("emojis") or ""),
                "delivered_at": str(rec["delivery"].get("delivered_at") or ""),
                "clicked_at": str(rec["delivery"].get("clicked_at") or ""),
            }
        )
    return out[:limit]


@app.post("/mobile/inbox/{delivery_id}/click")
def mobile_inbox_click(
    delivery_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    drow = db.query(ModuleData).filter(
        ModuleData.id == int(delivery_id),
        ModuleData.module_name == "duyurular",
        ModuleData.entity_type == "delivery",
    ).first()
    if not drow:
        raise HTTPException(status_code=404, detail="delivery not found")
    if not is_superadmin(current_user) and int(drow.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="forbidden")
    d = drow.data if isinstance(drow.data, dict) else {}
    if not str(d.get("clicked_at") or "").strip():
        d["clicked_at"] = _iso_now()
        drow.data = d
        item_id = int(d.get("item_id") or 0)
        if item_id > 0:
            irow = db.query(ModuleData).filter(
                ModuleData.id == item_id,
                ModuleData.module_name == "duyurular",
                ModuleData.entity_type == "item",
            ).first()
            if irow and isinstance(irow.data, dict):
                irow.data["clicked_count"] = int(irow.data.get("clicked_count") or 0) + 1
                irow.updated_by_user_id = int(current_user.id)
        drow.updated_by_user_id = int(current_user.id)
        db.commit()
    return {"ok": True, "delivery_id": int(delivery_id), "clicked_at": str(d.get("clicked_at") or "")}


@app.get("/finance/auto-lines")
def finance_auto_lines(
    project_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required in management scope")

    project = db.query(Project).filter(Project.id == scoped_project_id).first()
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not is_superadmin(current_user) and int(project.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="Forbidden")
    tenant_scope = int(project.tenant_id or 0)

    def _name_from_kayit_data(d: dict | None) -> str:
        d = d or {}
        first = str(d.get("isim") or d.get("f_isim") or "").strip()
        last = str(d.get("soyisim") or d.get("f_soyisim") or "").strip()
        full = f"{first} {last}".strip()
        if full:
            return full
        fallback = str(d.get("f_id") or d.get("id") or "").strip()
        return fallback or "Bilinmiyor"

    def _to_iso_date(v) -> str:
        if not v:
            return ""
        if isinstance(v, datetime):
            return v.strftime("%Y-%m-%d")
        raw = str(v).strip()
        if not raw:
            return ""
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
            return raw
        m = re.search(r"(\d{4}-\d{2}-\d{2})", raw)
        if m:
            return m.group(1)
        m2 = re.search(r"(\d{2})[./-](\d{2})[./-](\d{4})", raw)
        if m2:
            return f"{m2.group(3)}-{m2.group(2)}-{m2.group(1)}"
        return raw[:10]

    def _mk_line(
        kind: str,
        service_name: str,
        alan: str,
        odeyen: str,
        matrah: float,
        kdv: float,
        toplam: float,
        currency: str = "TRY",
        source_id: int | None = None,
        detail: str = "",
        date_str: str = "",
    ) -> dict:
        return {
            "kind": kind,
            "service_name": service_name,
            "alan": alan or "Bilinmiyor",
            "odeyen": odeyen or "Bilinmiyor",
            "matrah": round(_to_float(matrah), 2),
            "kdv": round(_to_float(kdv), 2),
            "toplam": round(_to_float(toplam), 2),
            "currency": (currency or "TRY").upper(),
            "source_id": source_id,
            "detail": detail or "",
            "date": date_str or "",
        }

    category_defaults: dict[str, dict] = {}
    product_rows = (
        db.query(ProjectServiceProduct, ServiceProduct)
        .join(ServiceProduct, ServiceProduct.id == ProjectServiceProduct.product_id)
        .filter(
            ProjectServiceProduct.project_id == int(scoped_project_id),
            ProjectServiceProduct.is_active == True,  # noqa: E712
            ServiceProduct.is_active == True,  # noqa: E712
        )
        .order_by(ProjectServiceProduct.created_at.desc())
        .all()
    )
    for ps, sp in product_rows:
        cat = str(sp.category or "").strip().lower()
        if not cat or cat in category_defaults:
            continue
        price = ps.price_override if ps.price_override is not None else sp.price
        currency = ps.currency_override if ps.currency_override else sp.currency
        category_defaults[cat] = {
            "price": _to_float(price),
            "vat_rate": _to_float(sp.vat_rate),
            "currency": (currency or "TRY").upper(),
            "name": str(sp.name or cat).strip(),
        }

    kayit_rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "kayit",
            ModuleData.project_id == int(scoped_project_id),
            ModuleData.tenant_id == tenant_scope,
        )
        .order_by(ModuleData.created_at.desc())
        .all()
    )
    kayit_name_map: dict[int, str] = {}
    for row in kayit_rows:
        kayit_name_map[int(row.id)] = _name_from_kayit_data(row.data if isinstance(row.data, dict) else {})

    lines: list[dict] = []

    kayit_cfg = category_defaults.get("kayit", {})
    kayit_price = _to_float(kayit_cfg.get("price"))
    kayit_vat_rate = _to_float(kayit_cfg.get("vat_rate"))
    kayit_currency = str(kayit_cfg.get("currency") or "TRY").upper()
    kayit_service = str(kayit_cfg.get("name") or "Kayıt Hizmeti")
    for row in kayit_rows:
        d = row.data if isinstance(row.data, dict) else {}
        person_name = _name_from_kayit_data(d)
        matrah = _to_float(d.get("matrah")) or _to_float(d.get("ucret")) or kayit_price
        kdv = _to_float(d.get("kdv"))
        if kdv <= 0 and kayit_vat_rate > 0:
            kdv = round(matrah * kayit_vat_rate / 100.0, 2)
        toplam = _to_float(d.get("toplam")) or round(matrah + kdv, 2)
        lines.append(
            _mk_line(
                "kayit",
                kayit_service,
                person_name,
                person_name,
                matrah,
                kdv,
                toplam,
                kayit_currency,
                source_id=int(row.id),
                detail=str(d.get("kurum") or d.get("f_kurum") or ""),
                date_str=_to_iso_date(row.created_at),
            )
        )

    kon_cfg = category_defaults.get("konaklama", {})
    kon_currency = str(kon_cfg.get("currency") or "TRY").upper()
    kon_service = str(kon_cfg.get("name") or "Konaklama")
    kon_rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "konaklama",
            ModuleData.project_id == int(scoped_project_id),
            ModuleData.tenant_id == tenant_scope,
        )
        .order_by(ModuleData.created_at.desc())
        .all()
    )
    for row in kon_rows:
        d = row.data if isinstance(row.data, dict) else {}
        detail_parts = [
            str(d.get("hotel") or "").strip(),
            str(d.get("package_code") or "").strip(),
            str(d.get("room_type") or "").strip(),
        ]
        detail = " / ".join([p for p in detail_parts if p])
        person_amounts = [
            (str(d.get("person1_name") or "").strip(), _to_float(d.get("amount1"))),
            (str(d.get("person2_name") or "").strip(), _to_float(d.get("amount2"))),
            (str(d.get("person3_name") or "").strip(), _to_float(d.get("amount3"))),
        ]
        for person_name, amount in person_amounts:
            if not person_name or amount <= 0:
                continue
            lines.append(
                _mk_line(
                    "konaklama",
                    kon_service,
                    person_name,
                    person_name,
                    amount,
                    0.0,
                    amount,
                    kon_currency,
                    source_id=int(row.id),
                    detail=detail,
                    date_str=_to_iso_date(row.created_at),
                )
            )

    transfer_cfg = category_defaults.get("transfer", {})
    transfer_price = _to_float(transfer_cfg.get("price"))
    transfer_vat_rate = _to_float(transfer_cfg.get("vat_rate"))
    transfer_currency_default = str(transfer_cfg.get("currency") or "TRY").upper()
    transfer_service = str(transfer_cfg.get("name") or "Transfer")
    transfer_rows = (
        db.query(Transfer)
        .filter(Transfer.project_id == int(scoped_project_id), Transfer.tenant_id == tenant_scope)
        .order_by(Transfer.created_at.desc())
        .all()
    )
    for t in transfer_rows:
        person_name = (_normalized_person_name(t) or t.passenger_name or "Bilinmiyor").strip() or "Bilinmiyor"
        trip_label = _flight_shape_label(t)
        transfer_matrah = transfer_price
        transfer_kdv = round(transfer_matrah * transfer_vat_rate / 100.0, 2) if transfer_vat_rate > 0 else 0.0
        transfer_toplam = round(transfer_matrah + transfer_kdv, 2)
        lines.append(
            _mk_line(
                "transfer",
                transfer_service,
                person_name,
                person_name,
                transfer_matrah,
                transfer_kdv,
                transfer_toplam,
                transfer_currency_default,
                source_id=int(t.id),
                detail=trip_label,
                date_str=_to_iso_date(t.flight_date or t.created_at),
            )
        )

        fare = _to_float(t.base_fare)
        tax = _to_float(t.tax_total)
        total = _to_float(t.total_amount)
        if fare > 0 or tax > 0 or total > 0:
            if total <= 0:
                total = round(fare + tax, 2)
            lines.append(
                _mk_line(
                    "ucak_bileti",
                    "Uçak Bileti",
                    person_name,
                    person_name,
                    fare,
                    tax,
                    total,
                    str((t.currency or transfer_currency_default) or "TRY").upper(),
                    source_id=int(t.id),
                    detail=f"{(t.flight_no or '').strip()} / {(t.pnr or '').strip()}".strip(" /"),
                    date_str=_to_iso_date(t.flight_date or t.created_at),
                )
            )

    lines.sort(key=lambda x: ((x.get("date") or ""), int(x.get("source_id") or 0)), reverse=True)
    return {
        "project_id": int(scoped_project_id),
        "count": len(lines),
        "rows": lines,
    }


@app.get("/fx/tcmb-rates")
def fx_tcmb_rates(
    date: str | None = Query(default=None, description="YYYY-MM-DD"),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    if not current_user:
        raise HTTPException(status_code=401, detail="Unauthorized")

    target = (date or "").strip()
    if target:
        try:
            dt = datetime.strptime(target, "%Y-%m-%d")
        except ValueError:
            raise HTTPException(status_code=400, detail="date must be YYYY-MM-DD")
    else:
        dt = _now_istanbul_naive()
        target = dt.strftime("%Y-%m-%d")

    ddmmyyyy = dt.strftime("%d%m%Y")
    yyyymm = dt.strftime("%Y%m")
    url = f"https://www.tcmb.gov.tr/kurlar/{yyyymm}/{ddmmyyyy}.xml"
    if dt.date() == _now_istanbul_naive().date():
        url = "https://www.tcmb.gov.tr/kurlar/today.xml"

    try:
        with urllib.request.urlopen(url, timeout=15) as resp:
            xml_bytes = resp.read()
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"TCMB kur verisi alınamadı: {exc}")

    try:
        root = ET.fromstring(xml_bytes)
    except Exception:
        raise HTTPException(status_code=502, detail="TCMB XML parse edilemedi")

    def _rate_for(code: str) -> float | None:
        node = root.find(f".//Currency[@Kod='{code}']")
        if node is None:
            return None
        tags = ["ForexSelling", "BanknoteSelling", "ForexBuying", "BanknoteBuying"]
        for tag in tags:
            val_node = node.find(tag)
            raw = (val_node.text if val_node is not None else "") or ""
            raw = raw.strip().replace(",", ".")
            try:
                if raw:
                    return float(raw)
            except Exception:
                continue
        return None

    usd = _rate_for("USD")
    eur = _rate_for("EUR")
    gbp = _rate_for("GBP")
    if usd is None and eur is None and gbp is None:
        raise HTTPException(status_code=502, detail="TCMB verisinde kur bulunamadı")

    return {
        "date": target,
        "source": "tcmb",
        "rates": {
            "TL": 1.0,
            "USD": usd,
            "EUR": eur,
            "GBP": gbp,
        },
    }


