@app.post("/transfers/rematch-kayit")
def rematch_transfers_kayit(
    project_id: int | None = Query(default=None),
    limit: int = Query(default=5000, ge=1, le=20000),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _auto_cleanup_expired_ticket_uploads(db)
    active_project, management_scope = _active_project_and_management_scope(db, current_user)
    requested_project_id: int | None = project_id
    if requested_project_id is None and active_project is not None:
        requested_project_id = int(active_project.id)
    if requested_project_id is not None:
        try:
            requested_project_id = int(requested_project_id)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="project_id must be integer")
    if (
        management_scope
        and active_project is not None
        and _is_management_project(active_project)
        and requested_project_id == int(active_project.id)
    ):
        requested_project_id = None

    query = db.query(Transfer)
    if not is_superadmin(current_user):
        query = query.filter(Transfer.tenant_id == current_user.tenant_id)
    if not management_scope:
        if active_project is None:
            raise HTTPException(status_code=400, detail="Active project required")
        if requested_project_id is not None and int(requested_project_id) != int(active_project.id):
            raise HTTPException(status_code=403, detail="Only active project is allowed")
        query = query.filter(Transfer.project_id == int(active_project.id))
    elif requested_project_id is not None:
        query = query.filter(Transfer.project_id == int(requested_project_id))

    items = query.order_by(Transfer.created_at.desc()).limit(limit).all()
    processed = 0
    matched = 0
    relinked = 0
    phone_filled = 0
    for tr in items:
        processed += 1
        before_kayit = int(tr.participant_kayit_id or 0)
        before_phone = str(tr.participant_phone or "").strip()
        matched_id = _sync_transfer_to_kayit_card(db, tr, actor_user_id=int(current_user.id))
        after_kayit = int(tr.participant_kayit_id or 0)
        after_phone = str(tr.participant_phone or "").strip()
        if matched_id:
            matched += 1
        if after_kayit > 0 and after_kayit != before_kayit:
            relinked += 1
        if not before_phone and after_phone:
            phone_filled += 1
    db.commit()
    return {
        "ok": True,
        "processed": processed,
        "matched": matched,
        "relinked": relinked,
        "phone_filled": phone_filled,
        "project_id": requested_project_id,
    }


def _transfer_display_name_for_ticket(tr: Transfer, db: Session) -> str:
    if tr and tr.participant_kayit_id:
        row = db.query(ModuleData).filter(
            ModuleData.id == int(tr.participant_kayit_id),
            ModuleData.module_name == "kayit",
        ).first()
        if row and isinstance(row.data, dict):
            kname = _primary_kayit_full_name(row.data)
            if kname:
                return kname
    return str(tr.passenger_name or "").strip() or "YOLCU"


def _transfer_flight_type_label(tr: Transfer) -> str:
    val = str(getattr(tr, "trip_type", "") or "").strip().lower()
    mapped = {
        "round_trip": "gidis_donus",
        "one_way": "tek_yon",
        "return_only": "donus",
        "connection": "aktarma",
    }.get(val)
    if mapped:
        return mapped
    if val:
        return val
    return _flight_shape_label(tr) or "UCUS"


@app.post("/transfers/tickets/clean-export")
def clean_export_project_tickets(
    project_id: int | None = Query(default=None),
    upload_ids: str | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "transfer")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    target_project_id = int(scoped_project_id) if scoped_project_id is not None else None
    if target_project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    parsed_upload_ids: list[int] = []
    if upload_ids:
        try:
            parsed_upload_ids = [
                int(x.strip())
                for x in str(upload_ids).split(",")
                if str(x).strip()
            ]
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="upload_ids must be comma separated integers")
        if not parsed_upload_ids:
            raise HTTPException(status_code=400, detail="upload_ids is required")

    q = db.query(Transfer).filter(Transfer.project_id == int(target_project_id))
    if not is_superadmin(current_user):
        q = q.filter(Transfer.tenant_id == current_user.tenant_id)
    if parsed_upload_ids:
        q = q.filter(Transfer.upload_id.in_(parsed_upload_ids))
    transfers = q.order_by(Transfer.created_at.desc()).all()
    if not transfers:
        raise HTTPException(status_code=404, detail="Transfer kaydı bulunamadı")

    upload_ids = [int(t.upload_id) for t in transfers if t and t.upload_id]
    upload_map: dict[int, Upload] = {}
    if upload_ids:
        uq = db.query(Upload).filter(Upload.id.in_(upload_ids))
        if not is_superadmin(current_user):
            uq = uq.filter(Upload.tenant_id == current_user.tenant_id)
        for u in uq.all():
            upload_map[int(u.id)] = u

    TICKET_ARCHIVE_DIR.mkdir(parents=True, exist_ok=True)
    ts = _now_istanbul().strftime("%Y%m%d_%H%M%S")
    zip_name = f"bilet_temiz_{target_project_id}_{ts}.zip"
    zip_path = TICKET_ARCHIVE_DIR / zip_name
    used_names: dict[str, int] = {}
    exported = 0
    skipped = 0
    duplicate_skipped = 0
    seen_signatures: set[str] = set()

    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for tr in transfers:
            uid = int(tr.upload_id or 0)
            if uid <= 0:
                skipped += 1
                continue
            up = upload_map.get(uid)
            if not up:
                skipped += 1
                continue
            src = Path(str(up.file_path or "").strip())
            if not (src.exists() and src.is_file()):
                skipped += 1
                continue
            dup_signature = "|".join(
                [
                    _normalize_person_name_for_match(_transfer_display_name_for_ticket(tr, db)),
                    _normalize_person_name_for_match(str(tr.pnr or "").strip()),
                    _normalize_person_name_for_match(str(tr.flight_no or "").strip()),
                    _normalize_person_name_for_match(str(tr.from_to or "").strip()),
                    _normalize_person_name_for_match(str(tr.issue_date or "").strip()),
                    _normalize_person_name_for_match(str(tr.ucus_sekli or "").strip()),
                ]
            )
            if dup_signature in seen_signatures:
                duplicate_skipped += 1
                continue
            seen_signatures.add(dup_signature)
            person_name = _safe_file_token(_transfer_display_name_for_ticket(tr, db), fallback="YOLCU")
            flight_type = _safe_file_token(_transfer_flight_type_label(tr), fallback="UCUS")
            pnr = _safe_file_token(str(tr.pnr or "").strip(), fallback="PNR")
            base = f"{person_name}_{flight_type}_{pnr}"
            count = used_names.get(base, 0) + 1
            used_names[base] = count
            final_base = base if count == 1 else f"{base}_{count}"
            ext = src.suffix.lower()
            arcname = f"{final_base}.pdf"
            if ext == ".pdf":
                zf.write(src, arcname=arcname)
                exported += 1
                continue
            if ext in {".jpg", ".jpeg", ".png"}:
                try:
                    with Image.open(src) as im:
                        if im.mode not in ("RGB", "L"):
                            im = im.convert("RGB")
                        elif im.mode == "L":
                            im = im.convert("RGB")
                        tmp = io.BytesIO()
                        im.save(tmp, format="PDF")
                        tmp.seek(0)
                        zf.writestr(arcname, tmp.read())
                        exported += 1
                except Exception:
                    skipped += 1
                continue
            skipped += 1

    if exported <= 0:
        try:
            if zip_path.exists():
                zip_path.unlink()
        except Exception:
            pass
        raise HTTPException(status_code=400, detail="PDF dönüştürülebilir bilet bulunamadı")

    tenant_id = int(current_user.tenant_id or 0)
    if is_superadmin(current_user):
        project = db.query(Project).filter(Project.id == int(target_project_id)).first()
        if project and project.tenant_id:
            tenant_id = int(project.tenant_id)
    file_row = ModuleData(
        tenant_id=tenant_id or None,
        project_id=int(target_project_id),
        module_name="yonetim",
        entity_type="dosya",
        data={
            "title": f"Bilet Temiz Çıktı {ts}",
            "kind": "transfer_ticket_archive",
            "zip_name": zip_name,
            "relative_path": str(zip_path).replace("\\\\", "/"),
            "download_url": f"/yonetici/files/{0}/download",
            "exported_count": int(exported),
            "skipped_count": int(skipped),
            "duplicate_skipped_count": int(duplicate_skipped),
            "created_at": _now_istanbul().isoformat(timespec="seconds"),
        },
        created_by_user_id=int(current_user.id),
        updated_by_user_id=int(current_user.id),
    )
    db.add(file_row)
    db.commit()
    db.refresh(file_row)
    data_obj = file_row.data if isinstance(file_row.data, dict) else {}
    data_obj["download_url"] = f"/yonetici/files/{int(file_row.id)}/download"
    file_row.data = data_obj
    db.commit()
    return {
        "ok": True,
        "project_id": int(target_project_id),
        "manager_file_id": int(file_row.id),
        "download_url": str(data_obj.get("download_url") or ""),
        "zip_name": zip_name,
        "exported_count": int(exported),
        "skipped_count": int(skipped),
        "duplicate_skipped_count": int(duplicate_skipped),
    }


@app.get("/yonetici/files/{file_id}/download")
def download_manager_file(
    file_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    row = db.query(ModuleData).filter(
        ModuleData.id == int(file_id),
        ModuleData.module_name == "yonetim",
        ModuleData.entity_type == "dosya",
    ).first()
    if not row:
        raise HTTPException(status_code=404, detail="Dosya kaydı bulunamadı")
    if (not is_superadmin(current_user)) and int(row.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="forbidden")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, row.project_id)
    if not management_scope and scoped_project_id is not None and int(row.project_id or 0) != int(scoped_project_id):
        raise HTTPException(status_code=403, detail="forbidden")
    data_obj = row.data if isinstance(row.data, dict) else {}
    rel = str(data_obj.get("relative_path") or "").strip()
    if not rel:
        raise HTTPException(status_code=404, detail="Dosya yolu bulunamadı")
    fp = Path(rel)
    if not fp.is_absolute():
        fp = (Path(".") / fp).resolve()
    root = TICKET_ARCHIVE_DIR.resolve()
    try:
        fp_resolved = fp.resolve()
    except Exception:
        raise HTTPException(status_code=404, detail="Dosya bulunamadı")
    if root not in fp_resolved.parents and fp_resolved != root:
        raise HTTPException(status_code=403, detail="invalid file scope")
    if not fp_resolved.exists() or not fp_resolved.is_file():
        raise HTTPException(status_code=404, detail="Dosya bulunamadı")
    return FileResponse(path=str(fp_resolved), filename=str(data_obj.get("zip_name") or fp_resolved.name), media_type="application/zip")


@app.get("/yonetici/files")
def list_manager_files(
    project_id: int | None = Query(default=None),
    limit: int = Query(default=200, ge=1, le=1000),
    offset: int = Query(default=0, ge=0),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    q = db.query(ModuleData).filter(
        ModuleData.module_name == "yonetim",
        ModuleData.entity_type == "dosya",
    )
    if not is_superadmin(current_user):
        q = q.filter(ModuleData.tenant_id == current_user.tenant_id)
    if not management_scope:
        if scoped_project_id is None:
            raise HTTPException(status_code=400, detail="Active project required")
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    elif scoped_project_id is not None:
        q = q.filter(ModuleData.project_id == int(scoped_project_id))
    rows = q.order_by(ModuleData.created_at.desc(), ModuleData.id.desc()).offset(offset).limit(limit).all()
    out = []
    for r in rows:
        data_obj = r.data if isinstance(r.data, dict) else {}
        out.append(
            {
                "id": int(r.id),
                "project_id": r.project_id,
                "title": str(data_obj.get("title") or f"Dosya {r.id}"),
                "kind": str(data_obj.get("kind") or ""),
                "zip_name": str(data_obj.get("zip_name") or ""),
                "created_at": str(data_obj.get("created_at") or (r.created_at.isoformat() if r.created_at else "")),
                "exported_count": int(data_obj.get("exported_count") or 0),
                "skipped_count": int(data_obj.get("skipped_count") or 0),
                "download_url": f"/yonetici/files/{int(r.id)}/download",
            }
        )
    return out


