@app.put("/transfers/{transfer_id}")
def update_transfer(
    transfer_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    role_key = normalize_role(current_user.role)
    scoped_project_id, management_scope = _resolve_project_scope_for_user(
        db, current_user, payload.get("project_id")
    )
    row = db.query(Transfer).filter(Transfer.id == transfer_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="Transfer not found")
    if not is_superadmin(current_user) and row.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=403, detail="forbidden")
    if role_key != "supplier_admin":
        if not management_scope and row.project_id != scoped_project_id:
            raise HTTPException(status_code=403, detail="forbidden")
        if management_scope and scoped_project_id is not None and row.project_id != scoped_project_id:
            raise HTTPException(status_code=403, detail="transfer is outside selected project scope")
    else:
        own_company_id = _vehicle_supplier_company_id(db, current_user)
        if own_company_id is None:
            raise HTTPException(status_code=403, detail="Only vehicle supplier admin can edit transfers")
        accepted_projects = _vehicle_accepted_project_ids(db, int(current_user.tenant_id or 0), int(own_company_id))
        if int(row.supplier_company_id or 0) != int(own_company_id) and int(row.project_id or 0) not in accepted_projects:
            raise HTTPException(status_code=403, detail="Transfer is outside supplier scope")

    allowed = {
        "passenger_name",
        "participant_phone",
        "participant_order_no",
        "participant_kayit_id",
        "pnr",
        "issue_date",
        "pickup_time",
        "transfer_point",
        "vehicle_code",
        "status",
    }
    updated = 0
    for k, v in (payload or {}).items():
        if k not in allowed:
            continue
        txt = str(v).strip() if v is not None else ""
        if k == "participant_order_no":
            try:
                setattr(row, k, int(txt) if txt else None)
            except ValueError:
                raise HTTPException(status_code=400, detail="participant_order_no must be integer")
            updated += 1
            continue
        if k == "participant_kayit_id":
            if not txt:
                row.participant_kayit_id = None
                updated += 1
                continue
            try:
                kayit_id = int(txt)
            except ValueError:
                raise HTTPException(status_code=400, detail="participant_kayit_id must be integer")
            if kayit_id <= 0:
                raise HTTPException(status_code=400, detail="participant_kayit_id must be positive")
            kayit_query = db.query(ModuleData).filter(
                ModuleData.id == kayit_id,
                ModuleData.module_name == "kayit",
            )
            if not is_superadmin(current_user):
                kayit_query = kayit_query.filter(ModuleData.tenant_id == current_user.tenant_id)
            kayit_row = kayit_query.first()
            if not kayit_row:
                raise HTTPException(status_code=404, detail="Participant card not found")
            if row.project_id is not None and kayit_row.project_id is not None and int(kayit_row.project_id) != int(row.project_id):
                raise HTTPException(status_code=400, detail="participant_kayit_id project mismatch")
            row.participant_kayit_id = int(kayit_id)
            updated += 1
            continue
        if k == "vehicle_code":
            txt = txt.upper()
        setattr(row, k, txt or None)
        updated += 1
    if updated == 0:
        raise HTTPException(status_code=400, detail="No editable field provided")
    # Supplier admin accepted project transfer üzerinde işlem yaptığında transferi kendi firmasıyla ilişkilendir.
    if role_key == "supplier_admin":
        own_company_id = _vehicle_supplier_company_id(db, current_user)
        if own_company_id:
            row.supplier_company_id = int(own_company_id)
    # Agency/admin revizesi, kalkışa 24 saatten az kaldıysa araç firması onayına düşer.
    if role_key != "supplier_admin":
        dep_dt = _transfer_departure_dt(row)
        if dep_dt is not None:
            hours_left = (dep_dt - _now_istanbul_naive()).total_seconds() / 3600.0
            if hours_left <= 24:
                row.vehicle_revision_status = "pending"
                row.vehicle_revision_updated_at = datetime.now(timezone.utc)
                row.vehicle_revision_decision_at = None
                row.vehicle_revision_decision_by_user_id = None
                row.vehicle_revision_decision_note = None

    # Araç kodu varsa rezervasyon kodunu boş bırakmayalım
    if row.vehicle_code and not row.reservation_code:
        row.reservation_code = _build_reservation_code(
            row.vehicle_code,
            row.flight_date,
            _project_trace_code(db, row.project_id),
            row.id,
        )
    if row.reservation_code:
        must_regen_sub = (
            not row.sub_reservation_no
            or not str(row.sub_reservation_no).upper().startswith(f"{str(row.reservation_code).upper()}-")
        )
        if must_regen_sub:
            row.sub_reservation_no = _build_transfer_sub_reservation_no(
                db,
                row.reservation_code,
                row.project_id,
            )

    _sync_transfer_to_kayit_card(db, row, actor_user_id=int(current_user.id))

    db.commit()
    db.refresh(row)
    participant_display_id = ""
    if row.participant_kayit_id:
        linked_row = db.query(ModuleData).filter(ModuleData.id == int(row.participant_kayit_id)).first()
        linked_data = dict(getattr(linked_row, "data", {}) or {}) if linked_row else {}
        participant_display_id = _kayit_display_id_from_data(linked_data)
    return {
        "ok": True,
        "id": row.id,
        "reservation_code": row.reservation_code,
        "sub_reservation_no": row.sub_reservation_no,
        "passenger_name": row.passenger_name,
        "participant_phone": row.participant_phone,
        "participant_order_no": row.participant_order_no,
        "participant_kayit_id": row.participant_kayit_id,
        "participant_display_id": participant_display_id,
        "pnr": row.pnr,
        "issue_date": row.issue_date,
        "pickup_time": row.pickup_time,
        "transfer_point": row.transfer_point,
        "vehicle_code": row.vehicle_code,
        "status": row.status,
    }


@app.delete("/transfers/{transfer_id}")
def delete_transfer(
    transfer_id: int,
    project_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    role_key = normalize_role(current_user.role)
    scoped_project_id, management_scope = _resolve_project_scope_for_user(
        db, current_user, project_id
    )
    row = db.query(Transfer).filter(Transfer.id == transfer_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="Transfer not found")
    if not is_superadmin(current_user) and row.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=403, detail="forbidden")
    if role_key != "supplier_admin":
        if not management_scope and row.project_id != scoped_project_id:
            raise HTTPException(status_code=403, detail="forbidden")
        if management_scope and scoped_project_id is not None and row.project_id != scoped_project_id:
            raise HTTPException(status_code=403, detail="transfer is outside selected project scope")
    else:
        own_company_id = _vehicle_supplier_company_id(db, current_user)
        if own_company_id is None:
            raise HTTPException(status_code=403, detail="Only vehicle supplier admin can delete transfers")
        accepted_projects = _vehicle_accepted_project_ids(db, int(current_user.tenant_id or 0), int(own_company_id))
        if int(row.supplier_company_id or 0) != int(own_company_id) and int(row.project_id or 0) not in accepted_projects:
            raise HTTPException(status_code=403, detail="Transfer is outside supplier scope")

    upload_id = int(row.upload_id or 0) or None
    upload = db.query(Upload).filter(Upload.id == upload_id).first() if upload_id else None

    if row.participant_kayit_id:
        linked_row = db.query(ModuleData).filter(ModuleData.id == int(row.participant_kayit_id)).first()
        linked_data = dict(getattr(linked_row, "data", {}) or {}) if linked_row else None
        if linked_data is not None:
            for key in (
                "transfer",
                "f_transfer",
                "transfer_flight_no",
                "transfer_flight_date",
                "transfer_flight_time",
                "transfer_pnr",
                "transfer_pickup_time",
                "transfer_transfer_point",
                "transfer_vehicle_code",
                "transfer_linked_transfer_id",
            ):
                linked_data.pop(key, None)
            linked_row.data = linked_data

    if upload_id:
        transfer_plan_row = _get_module_list_row(db, int(row.tenant_id or 0) or None, int(row.project_id or 0) or None, "planning_transfer_lists")
        if transfer_plan_row and isinstance(transfer_plan_row.data, list):
            transfer_plan_row.data = [
                item for item in transfer_plan_row.data
                if not (isinstance(item, dict) and str(item.get("source_upload_id") or "").strip() == str(upload_id))
            ]
            transfer_plan_row.updated_by_user_id = int(current_user.id)

    db.query(OpsEvent).filter(OpsEvent.related_transfer_id == int(row.id)).delete(synchronize_session=False)
    db.delete(row)
    if upload is not None:
        upload_path = Path(str(upload.file_path or "").strip()) if str(upload.file_path or "").strip() else None
        db.delete(upload)
    else:
        upload_path = None
    db.commit()

    if upload_path and upload_path.exists() and upload_path.is_file():
        try:
            upload_path.unlink()
        except Exception:
            pass

    return {"ok": True, "id": int(transfer_id), "upload_id": upload_id}


def _program_scope(
    db: Session,
    current_user: User,
    project_id: int | None,
) -> tuple[int, int]:
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    project = db.query(Project).filter(Project.id == int(scoped_project_id), Project.is_active.is_(True)).first()
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not _can_user_access_project(db, current_user, project):
        raise HTTPException(status_code=403, detail="Project access denied")
    tenant_id = int(project.tenant_id or 0)
    if tenant_id <= 0:
        raise HTTPException(status_code=400, detail="Invalid project tenant scope")
    return int(project.id), tenant_id


def _program_days_from_project_dates(db: Session, project_id: int) -> list[str]:
    project = db.query(Project).filter(Project.id == int(project_id)).first()
    if not project:
        return []

    def _coerce_date(raw: str | None) -> datetime | None:
        val = str(raw or "").strip()
        if not val:
            return None
        try:
            return datetime.strptime(val, "%Y-%m-%d")
        except ValueError:
            return None

    start_dt = _coerce_date(getattr(project, "start_date", None))
    end_dt = _coerce_date(getattr(project, "end_date", None))

    # Fallback for legacy projects: use service sale date range if project date range is empty.
    if start_dt is None or end_dt is None:
        rows = (
            db.query(ProjectServiceProduct.sale_start_date, ProjectServiceProduct.sale_end_date)
            .filter(ProjectServiceProduct.project_id == int(project_id))
            .all()
        )
        starts = [_coerce_date(r[0]) for r in rows]
        ends = [_coerce_date(r[1]) for r in rows]
        starts = [x for x in starts if x is not None]
        ends = [x for x in ends if x is not None]
        if start_dt is None and starts:
            start_dt = min(starts)
        if end_dt is None and ends:
            end_dt = max(ends)

    if start_dt is None and end_dt is None:
        return []
    if start_dt is None:
        start_dt = end_dt
    if end_dt is None:
        end_dt = start_dt
    if start_dt is None or end_dt is None:
        return []
    if end_dt < start_dt:
        start_dt, end_dt = end_dt, start_dt

    max_days = 365
    out: list[str] = []
    cur = start_dt
    while cur <= end_dt and len(out) < max_days:
        out.append(cur.strftime("%Y-%m-%d"))
        cur = cur + timedelta(days=1)
    return out


def _program_name_key(full_name: str | None) -> tuple[str, str]:
    name = str(full_name or "").strip()
    name = re.sub(r"^(prof\\.?\\s*dr\\.?|do[cç]\\.?\\s*dr\\.?|dr\\.?)\\s+", "", name, flags=re.IGNORECASE).strip()
    parts = [p for p in re.split(r"\\s+", name) if p]
    first = parts[0] if parts else ""
    last = " ".join(parts[1:]) if len(parts) > 1 else ""

    def norm(v: str) -> str:
        txt = unicodedata.normalize("NFKD", str(v or "")).encode("ascii", "ignore").decode("ascii")
        txt = re.sub(r"[^a-zA-Z0-9]", "", txt).lower()
        return txt

    return norm(first), norm(last)


def _parse_program_date(raw: str | None) -> str:
    val = str(raw or "").strip()
    if not val:
        return _now_istanbul().strftime("%Y-%m-%d")
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(val, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return _now_istanbul().strftime("%Y-%m-%d")


def _parse_program_time(raw: str | None, fallback: str) -> str:
    val = str(raw or "").strip().replace(".", ":")
    if not val:
        return fallback
    m = re.match(r"^(\\d{1,2}):(\\d{1,2})$", val)
    if not m:
        return fallback
    hh = max(0, min(23, int(m.group(1))))
    mm = max(0, min(59, int(m.group(2))))
    return f"{hh:02d}:{mm:02d}"


def _time_minutes(hhmm: str) -> int:
    try:
        hh, mm = str(hhmm or "00:00").split(":")
        return int(hh) * 60 + int(mm)
    except Exception:
        return 0


def _normalize_hall_value(raw_hall: str | None) -> tuple[str, bool]:
    raw = str(raw_hall or "").strip()
    key = raw.lower()
    if key in {"all", "hepsi", "tum", "tüm", "genel"}:
        return "ALL", True
    if not raw:
        return "", False
    clean = re.sub(r"\s+", " ", raw).strip()
    if len(clean) < 2 or len(clean) > 64:
        return "", False
    if re.search(r"[\r\n\t]", clean):
        return "", False
    return clean, True


def _guess_program_type(raw_type: str | None, title: str | None, hall: str | None) -> str:
    t = str(raw_type or "").strip().lower()
    ttl = str(title or "").strip().lower()
    h = str(hall or "").strip().lower()
    if t in {"session", "symposium", "break", "social", "workshop"}:
        return t
    if any(k in ttl for k in ["uydu", "sempozyum", "sponsor"]) or "firma" in ttl:
        return "symposium"
    if any(k in ttl for k in ["mola", "kahve", "cay", "çay", "oglen", "öğlen", "yemek"]):
        return "break"
    if any(k in ttl for k in ["sosyal", "gala", "konser", "etkinlik", "gezi"]):
        return "social"
    if "workshop" in ttl or "atolye" in ttl or "atölye" in ttl:
        return "workshop"
    if h in {"all", "tum", "tüm", "genel"}:
        return "break"
    return "session"


def _extract_program_rows(file_name: str, content: bytes) -> list[dict]:
    ext = Path(file_name or "").suffix.lower()
    if ext in {".csv", ".xls", ".txt"}:
        text_val = content.decode("utf-8-sig", errors="ignore")
        sample = text_val[:2048]
        delimiter = "\t" if "\t" in sample else ("," if "," in sample else ";")
        reader = csv.DictReader(io.StringIO(text_val), delimiter=delimiter)
        return [dict(r or {}) for r in reader]
    raise HTTPException(status_code=400, detail="Only .xls or .csv template files are supported")


def _normalize_program_sessions_from_rows(rows: list[dict]) -> tuple[list[dict], list[str]]:
    sessions: list[dict] = []
    notes: list[str] = []
    for idx, r in enumerate(rows, start=2):
        row = {str(k or "").strip().lower(): (v if v is not None else "") for k, v in (r or {}).items()}
        title = str(row.get("title") or row.get("session_title") or "").strip()
        if not title:
            continue
        raw_day = str(row.get("date") or row.get("day") or "").strip()
        day = _parse_program_date(raw_day) if raw_day else ""
        hall_raw = str(row.get("hall") or "").strip()
        hall, hall_ok = _normalize_hall_value(hall_raw)
        if not hall_ok:
            notes.append(f"Satır {idx}: Salon değeri geçersiz, boş bırakıldı.")
            hall = ""
        raw_start = str(row.get("start_time") or row.get("start") or "").strip()
        raw_end = str(row.get("end_time") or row.get("end") or "").strip()
        start = _parse_program_time(raw_start, "") if raw_start else ""
        end = _parse_program_time(raw_end, "") if raw_end else ""
        if start and end and _time_minutes(end) <= _time_minutes(start):
            end_min = _time_minutes(start) + 30
            end = f"{min(23, end_min // 60):02d}:{(end_min % 60):02d}"
            notes.append(f"Satır {idx}: Bitiş <= başlangıç olduğu için +30 dk düzeltildi.")
        p_type = _guess_program_type(row.get("type"), title, hall)
        moderator = {
            "kayit_id": str(row.get("moderator_kayit_id") or row.get("moderator_id") or "").strip(),
            "title": str(row.get("moderator_title") or "").strip(),
            "name": str(row.get("moderator_name") or row.get("moderator") or "").strip(),
        }
        speakers: list[dict] = []
        for i in range(1, 8):
            s_id = str(row.get(f"speaker{i}_kayit_id") or row.get(f"speaker{i}_id") or "").strip()
            s_name = str(row.get(f"speaker{i}_name") or "").strip()
            s_title = str(row.get(f"speaker{i}_title") or "").strip()
            s_topic = str(row.get(f"speaker{i}_topic") or "").strip()
            s_role = str(row.get(f"speaker{i}_role") or "").strip()
            if s_name or s_id:
                speakers.append({"kayit_id": s_id, "name": s_name, "title": s_title, "topic": s_topic, "role": s_role or "Konuşmacı"})
        if not speakers:
            packed = str(row.get("speakers") or "").strip()
            if packed:
                for part in [x.strip() for x in packed.split(";") if x.strip()]:
                    pieces = [x.strip() for x in part.split("|")]
                    speakers.append({
                        "name": pieces[0] if pieces else "",
                        "title": pieces[1] if len(pieces) > 1 else "",
                        "topic": pieces[2] if len(pieces) > 2 else "",
                        "role": pieces[3] if len(pieces) > 3 else "Konuşmacı",
                    })
        subtopics: list[str] = []
        for i in range(1, 10):
            sub = str(row.get(f"subtopic_{i}") or row.get(f"alt_topic_{i}") or "").strip()
            if sub:
                subtopics.append(sub)
        if not subtopics:
            sp_topics = [str((sp or {}).get("topic") or "").strip() for sp in speakers]
            subtopics = [x for x in sp_topics if x]
        sessions.append(
            {
                "id": str(row.get("id") or f"imp_{idx}_{uuid.uuid4().hex[:8]}"),
                "title": title,
                "type": p_type,
                "day": day,
                "hall": hall,
                "start": start,
                "end": end,
                "moderator": moderator,
                "sponsor": {
                    "name": str(row.get("sponsor_name") or row.get("company_name") or "").strip(),
                    "logo_url": str(row.get("sponsor_logo_url") or row.get("logo_url") or "").strip(),
                },
                "notes": str(row.get("notes") or "").strip(),
                "subtopics": subtopics,
                "speakers": speakers,
            }
        )
    return sessions, notes


def _sync_speaker_schedule_to_kayit(
    db: Session,
    tenant_id: int,
    project_id: int,
    sessions: list[dict],
) -> dict:
    rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "kayit",
            ModuleData.entity_type == "person_card",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == project_id,
        )
        .all()
    )
    person_map: dict[tuple[str, str], ModuleData] = {}
    person_by_id: dict[int, ModuleData] = {}
    for r in rows:
        d = dict(r.data or {})
        if "scientific_program_schedule" in d:
            d["scientific_program_schedule"] = []
            r.data = d
        person_by_id[int(r.id)] = r
        isim = str(d.get("isim") or d.get("ad") or "").strip()
        soyisim = str(d.get("soyisim") or d.get("soyad") or "").strip()
        full = str(d.get("ad_soyad") or "").strip()
        if not isim and full:
            parts = [p for p in full.split(" ") if p]
            isim = parts[0] if parts else ""
            soyisim = " ".join(parts[1:]) if len(parts) > 1 else ""
        key = _program_name_key((isim + " " + soyisim).strip())
        if key[0] and key not in person_map:
            person_map[key] = r

    linked = 0
    index: dict[str, list[dict]] = {}
    for s in sessions:
        base = {
            "day": s.get("day"),
            "start": s.get("start"),
            "end": s.get("end"),
            "hall": s.get("hall"),
            "session_title": s.get("title"),
            "session_type": s.get("type"),
        }
        moderator = s.get("moderator") or {}
        mod_name = str(moderator.get("name") or "").strip()
        mod_id_raw = moderator.get("kayit_id")
        mod_id = None
        try:
            mod_id = int(mod_id_raw) if mod_id_raw is not None and str(mod_id_raw).strip() != "" else None
        except Exception:
            mod_id = None
        if mod_name or mod_id:
            row = person_by_id.get(mod_id) if mod_id else None
            if row is None and mod_name:
                m_key = _program_name_key(mod_name)
                row = person_map.get(m_key)
            if row:
                d = dict(row.data or {})
                sched = list(d.get("scientific_program_schedule") or [])
                sched.append({**base, "role": "moderator", "topic": ""})
                d["scientific_program_schedule"] = sched
                row.data = d
                linked += 1
                if not mod_name:
                    mod_name = str(d.get("ad_soyad") or (str(d.get("isim") or "") + " " + str(d.get("soyisim") or ""))).strip()
            index.setdefault(mod_name, []).append({**base, "role": "moderator", "topic": ""})
        for sp in list(s.get("speakers") or []):
            sp_name = str((sp or {}).get("name") or "").strip()
            sp_id_raw = (sp or {}).get("kayit_id")
            sp_id = None
            try:
                sp_id = int(sp_id_raw) if sp_id_raw is not None and str(sp_id_raw).strip() != "" else None
            except Exception:
                sp_id = None
            if not sp_name and not sp_id:
                continue
            role_raw = str((sp or {}).get("role") or "").strip()
            role_norm = role_raw or "Konuşmacı"
            ent = {**base, "role": role_norm, "topic": str((sp or {}).get("topic") or "").strip()}
            row = person_by_id.get(sp_id) if sp_id else None
            if row is None and sp_name:
                sp_key = _program_name_key(sp_name)
                row = person_map.get(sp_key)
            if row:
                d = dict(row.data or {})
                sched = list(d.get("scientific_program_schedule") or [])
                sched.append(ent)
                d["scientific_program_schedule"] = sched
                row.data = d
                linked += 1
                if not sp_name:
                    sp_name = str(d.get("ad_soyad") or (str(d.get("isim") or "") + " " + str(d.get("soyisim") or ""))).strip()
            index.setdefault(sp_name, []).append(ent)
    return {"linked_records": linked, "speaker_index": index}


def _save_program_payload(
    db: Session,
    current_user: User,
    project_id: int,
    tenant_id: int,
    payload_data: dict,
) -> tuple[ModuleData, dict]:
    sessions = list(payload_data.get("sessions") or [])
    normalized_sessions: list[dict] = []
    for idx, s in enumerate(sessions, start=1):
        row = dict(s or {})
        hall_norm, hall_ok = _normalize_hall_value(row.get("hall"))
        if not hall_ok:
            raise HTTPException(status_code=400, detail=f"Invalid hall value at session #{idx}")
        row["hall"] = hall_norm
        normalized_sessions.append(row)
    sessions = normalized_sessions
    person_rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "kayit",
            ModuleData.entity_type == "person_card",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == project_id,
        )
        .all()
    )
    by_id = {int(r.id): r for r in person_rows}
    for s in sessions:
        mod = s.get("moderator") or {}
        try:
            mid = int(mod.get("kayit_id")) if str(mod.get("kayit_id") or "").strip() else None
        except Exception:
            mid = None
        if mid and mid in by_id:
            d = dict(by_id[mid].data or {})
            full = str(d.get("ad_soyad") or (str(d.get("isim") or "") + " " + str(d.get("soyisim") or ""))).strip()
            if not str(mod.get("name") or "").strip():
                mod["name"] = full
            if not str(mod.get("title") or "").strip():
                mod["title"] = str(d.get("akademik_unvan") or "").strip()
            mod["kayit_id"] = mid
            s["moderator"] = mod
        sp_list = list(s.get("speakers") or [])
        for sp in sp_list:
            sp["role"] = str(sp.get("role") or "").strip() or "Konuşmacı"
            try:
                sid = int(sp.get("kayit_id")) if str(sp.get("kayit_id") or "").strip() else None
            except Exception:
                sid = None
            if sid and sid in by_id:
                d = dict(by_id[sid].data or {})
                full = str(d.get("ad_soyad") or (str(d.get("isim") or "") + " " + str(d.get("soyisim") or ""))).strip()
                if not str(sp.get("name") or "").strip():
                    sp["name"] = full
                if not str(sp.get("title") or "").strip():
                    sp["title"] = str(d.get("akademik_unvan") or "").strip()
                sp["kayit_id"] = sid
        s["speakers"] = sp_list
    days = sorted({str(s.get("day") or "").strip() for s in sessions if str(s.get("day") or "").strip()})
    halls = sorted({str(s.get("hall") or "").strip() for s in sessions if str(s.get("hall") or "").strip() and str(s.get("hall")).upper() != "ALL"})
    if not halls:
        halls = []
    sync = _sync_speaker_schedule_to_kayit(db, tenant_id, project_id, sessions)
    payload = dict(payload_data or {})
    payload["days"] = days
    payload["halls"] = halls
    payload.setdefault("summary", {})
    payload["summary"]["day_count"] = len(days)
    payload["summary"]["hall_count"] = len(halls)
    payload["summary"]["total_talks"] = len(sessions)
    payload["speaker_index"] = sync.get("speaker_index") or {}
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "scientific_program_demo",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    if not row:
        row = ModuleData(
            tenant_id=tenant_id,
            project_id=project_id,
            module_name="toplanti",
            entity_type="scientific_program_demo",
            data=payload,
            created_by_user_id=current_user.id,
            updated_by_user_id=current_user.id,
        )
        db.add(row)
        db.flush()
    else:
        row.data = payload
        row.updated_by_user_id = current_user.id
    return row, sync


@app.get("/toplanti/program")
def get_scientific_program(
    project_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, project_id)
    project_days = _program_days_from_project_dates(db, scoped_project_id)
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "scientific_program_demo",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    if not row:
        return {"id": None, "project_id": scoped_project_id, "tenant_id": tenant_id, "data": {"sessions": [], "days": project_days, "halls": []}}
    data = dict(row.data or {})
    if not list(data.get("days") or []):
        data["days"] = project_days
    return {"id": row.id, "project_id": row.project_id, "tenant_id": row.tenant_id, "data": data}


