@app.post("/toplanti/programlama-grid/save")
def save_programming_grid(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, payload.get("project_id"))
    data_obj = payload.get("data")
    if not isinstance(data_obj, dict):
        raise HTTPException(status_code=400, detail="data must be an object")
    columns = data_obj.get("columns")
    rows = data_obj.get("rows")
    if not isinstance(columns, list) or not isinstance(rows, list):
        raise HTTPException(status_code=400, detail="data.columns and data.rows must be arrays")
    ql = data_obj.get("quick_lists") if isinstance(data_obj.get("quick_lists"), dict) else {}
    quick_lists = {
        "halls": list((ql or {}).get("halls") or []),
        "sessions": list((ql or {}).get("sessions") or []),
        "subtopics": list((ql or {}).get("subtopics") or []),
        "breaks": list((ql or {}).get("breaks") or []),
    }
    norm_cols = [str(x or "").strip() or f"Sütun {i+1}" for i, x in enumerate(columns)]
    norm_rows: list[list[str]] = []
    for r in rows:
        rr = list(r) if isinstance(r, list) else []
        rr = [str(x if x is not None else "") for x in rr[: len(norm_cols)]]
        while len(rr) < len(norm_cols):
            rr.append("")
        norm_rows.append(rr)
    clean = {
        "template": "programming_grid",
        "version": int(data_obj.get("version") or 1),
        "columns": norm_cols,
        "rows": norm_rows,
        "quick_lists": quick_lists,
    }
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "programming_grid",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    if not row:
        row = ModuleData(
            tenant_id=tenant_id,
            project_id=scoped_project_id,
            module_name="toplanti",
            entity_type="programming_grid",
            data=clean,
            created_by_user_id=current_user.id,
            updated_by_user_id=current_user.id,
        )
        db.add(row)
        db.commit()
        db.refresh(row)
    else:
        row.data = clean
        row.updated_by_user_id = current_user.id
        db.commit()
        db.refresh(row)
    return {"ok": True, "id": row.id, "project_id": row.project_id, "column_count": len(norm_cols), "row_count": len(norm_rows), "quick_lists": quick_lists}


def _parse_programming_grid_file(file_name: str, content: bytes) -> tuple[list[str], list[list[str]]]:
    ext = Path(file_name or "").suffix.lower()
    if ext == ".xlsx":
        wb = load_workbook(filename=io.BytesIO(content), read_only=True, data_only=True)
        ws = wb.active
        raw_rows = []
        for row in ws.iter_rows(values_only=True):
            raw_rows.append([str(c if c is not None else "").strip() for c in row])
    elif ext in {".xls", ".csv", ".txt"}:
        text_val = content.decode("utf-8-sig", errors="ignore")
        sample = text_val[:2048]
        delim = "\t" if "\t" in sample else (";" if sample.count(";") > sample.count(",") else ",")
        reader = csv.reader(io.StringIO(text_val), delimiter=delim)
        raw_rows = [[str(c or "").strip() for c in row] for row in reader]
    else:
        raise HTTPException(status_code=400, detail="Only .xlsx/.xls/.csv/.txt files are supported")
    raw_rows = [r for r in raw_rows if any(x for x in r)]
    if not raw_rows:
        return [], []
    columns = [str(x or "").strip() for x in raw_rows[0]]
    columns = [(c if c else f"Sütun {i+1}") for i, c in enumerate(columns)]
    data_rows: list[list[str]] = []
    for r in raw_rows[1:]:
        rr = list(r[: len(columns)])
        while len(rr) < len(columns):
            rr.append("")
        data_rows.append([str(x or "") for x in rr])
    return columns, data_rows


