@app.post("/vehicle-project-invites")
def create_vehicle_project_invite(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_company_admin),
):
    role_key = normalize_role(current_user.role)
    if role_key == "supplier_admin":
        raise HTTPException(status_code=403, detail="Only agency/admin side can send invites")
    project_id = int(payload.get("project_id") or 0)
    supplier_company_id = int(payload.get("supplier_company_id") or 0)
    if project_id <= 0 or supplier_company_id <= 0:
        raise HTTPException(status_code=400, detail="project_id and supplier_company_id are required")
    project = db.query(Project).filter(Project.id == project_id).first()
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not is_superadmin(current_user) and int(project.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="Project tenant mismatch")
    company = db.query(SupplierCompany).filter(SupplierCompany.id == supplier_company_id).first()
    if not company:
        raise HTTPException(status_code=404, detail="Supplier company not found")
    if int(company.tenant_id or 0) != int(project.tenant_id or 0):
        raise HTTPException(status_code=403, detail="Supplier company tenant mismatch")
    if _normalize_supplier_company_type(getattr(company, "company_type", None)) != "vehicle":
        raise HTTPException(status_code=400, detail="Invite target must be vehicle supplier")
    existing = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "transfer",
            ModuleData.entity_type == "vehicle_project_invite",
            ModuleData.tenant_id == int(project.tenant_id),
        )
        .all()
    )
    for r in existing:
        d = dict(r.data or {})
        try:
            ep = int(d.get("project_id") or 0)
            es = int(d.get("supplier_company_id") or 0)
        except (TypeError, ValueError):
            continue
        if ep == project_id and es == supplier_company_id:
            d["status"] = "pending"
            d["updated_at"] = datetime.utcnow().isoformat()
            d["system_received"] = True
            d["system_received_at"] = datetime.utcnow().isoformat()
            r.data = d
            r.updated_by_user_id = current_user.id
            db.commit()
            return {
                "ok": True,
                "id": r.id,
                "status": "pending",
                "system_received": True,
                "system_received_at": d.get("system_received_at"),
                "already_exists": True,
            }
    row = ModuleData(
        tenant_id=int(project.tenant_id),
        project_id=project_id,
        module_name="transfer",
        entity_type="vehicle_project_invite",
        data={
            "project_id": project_id,
            "project_code": project.operation_code,
            "project_name": project.name,
            "supplier_company_id": supplier_company_id,
            "supplier_company_name": company.name,
            "status": "pending",
            "sent_by_user_id": int(current_user.id),
            "sent_at": datetime.utcnow().isoformat(),
            "system_received": True,
            "system_received_at": datetime.utcnow().isoformat(),
        },
        created_by_user_id=current_user.id,
        updated_by_user_id=current_user.id,
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    data_obj = dict(row.data or {})
    return {
        "ok": True,
        "id": row.id,
        "status": "pending",
        "system_received": bool(data_obj.get("system_received")),
        "system_received_at": data_obj.get("system_received_at"),
        "already_exists": False,
    }


@app.get("/vehicle-project-invites/check")
def check_vehicle_project_invite(
    project_id: int = Query(...),
    supplier_company_id: int = Query(...),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    role_key = normalize_role(current_user.role)
    if not is_superadmin(current_user) and int(current_user.tenant_id or 0) <= 0:
        raise HTTPException(status_code=403, detail="forbidden")
    rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "transfer",
            ModuleData.entity_type == "vehicle_project_invite",
            ModuleData.tenant_id == int(current_user.tenant_id or 0),
        )
        .order_by(ModuleData.updated_at.desc())
        .all()
    )
    own_company_id = int(getattr(current_user, "supplier_company_id", 0) or 0)
    for r in rows:
        d = dict(r.data or {})
        try:
            ep = int(d.get("project_id") or 0)
            es = int(d.get("supplier_company_id") or 0)
        except (TypeError, ValueError):
            continue
        if ep != int(project_id) or es != int(supplier_company_id):
            continue
        if role_key == "supplier_admin" and es != own_company_id:
            raise HTTPException(status_code=403, detail="forbidden")
        st = str(d.get("status") or "pending").strip().lower()
        return {
            "exists": True,
            "invite_id": r.id,
            "status": st,
            "system_received": bool(d.get("system_received")),
            "system_received_at": d.get("system_received_at"),
            "sent_at": d.get("sent_at"),
            "accepted_at": d.get("accepted_at"),
            "rejected_at": d.get("rejected_at"),
        }
    return {"exists": False}


@app.get("/vehicle-project-invites")
def list_vehicle_project_invites(
    status: str | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    role_key = normalize_role(current_user.role)
    rows = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "transfer",
            ModuleData.entity_type == "vehicle_project_invite",
            ModuleData.tenant_id == int(current_user.tenant_id or 0),
        )
        .order_by(ModuleData.updated_at.desc())
        .all()
    )
    own_company_id = int(getattr(current_user, "supplier_company_id", 0) or 0)
    out = []
    for r in rows:
        d = dict(r.data or {})
        st = str(d.get("status") or "pending").strip().lower()
        if status and st != str(status).strip().lower():
            continue
        if role_key == "supplier_admin":
            try:
                scid = int(d.get("supplier_company_id") or 0)
            except (TypeError, ValueError):
                continue
            if scid != own_company_id:
                continue
        out.append(
            {
                "id": r.id,
                "project_id": d.get("project_id"),
                "project_code": d.get("project_code"),
                "project_name": d.get("project_name"),
                "supplier_company_id": d.get("supplier_company_id"),
                "supplier_company_name": d.get("supplier_company_name"),
                "status": st,
                "sent_at": d.get("sent_at"),
                "system_received": bool(d.get("system_received")),
                "system_received_at": d.get("system_received_at"),
                "accepted_at": d.get("accepted_at"),
                "rejected_at": d.get("rejected_at"),
            }
        )
    return {"items": out}


@app.put("/vehicle-project-invites/{invite_id}")
def decide_vehicle_project_invite(
    invite_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    role_key = normalize_role(current_user.role)
    action = str(payload.get("action") or "").strip().lower()
    if action not in {"accept", "reject"}:
        raise HTTPException(status_code=400, detail="action must be accept or reject")
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.id == int(invite_id),
            ModuleData.module_name == "transfer",
            ModuleData.entity_type == "vehicle_project_invite",
            ModuleData.tenant_id == int(current_user.tenant_id or 0),
        )
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Invite not found")
    d = dict(row.data or {})
    if role_key == "supplier_admin":
        own_company_id = int(getattr(current_user, "supplier_company_id", 0) or 0)
        if int(d.get("supplier_company_id") or 0) != own_company_id:
            raise HTTPException(status_code=403, detail="forbidden")
    d["status"] = "accepted" if action == "accept" else "rejected"
    d["updated_at"] = datetime.utcnow().isoformat()
    d["decision_by_user_id"] = int(current_user.id)
    if action == "accept":
        d["accepted_at"] = datetime.utcnow().isoformat()
    else:
        d["rejected_at"] = datetime.utcnow().isoformat()
    row.data = d
    row.updated_by_user_id = current_user.id
    db.commit()
    return {"ok": True, "id": row.id, "status": d["status"]}


@app.post("/supplier-transfers/external")
def create_supplier_external_transfer(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    supplier_company_id = _vehicle_supplier_company_id(db, current_user)
    if supplier_company_id is None:
        raise HTTPException(status_code=403, detail="Only vehicle supplier admin can create external transfer")
    name = str(payload.get("passenger_name") or "").strip()
    from_loc = str(payload.get("from") or payload.get("pickup_location") or "").strip()
    to_loc = str(payload.get("to") or payload.get("dropoff_location") or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="passenger_name is required")
    row = Transfer(
        tenant_id=int(current_user.tenant_id or 0),
        project_id=None,
        passenger_name=name,
        pickup_location=from_loc or None,
        dropoff_location=to_loc or None,
        participant_phone=str(payload.get("participant_phone") or "").strip() or None,
        pickup_time=str(payload.get("pickup_time") or "").strip() or None,
        transfer_point=str(payload.get("transfer_point") or "").strip() or None,
        vehicle_code=str(payload.get("vehicle_code") or "").strip().upper() or None,
        status="unassigned",
        supplier_company_id=int(supplier_company_id),
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    _sync_transfer_to_kayit_card(db, row, actor_user_id=int(current_user.id))
    if row.vehicle_code and not row.reservation_code:
        row.reservation_code = _build_reservation_code(
            row.vehicle_code,
            row.flight_date,
            _project_trace_code(db, row.project_id),
            row.id,
        )
        row.sub_reservation_no = _build_transfer_sub_reservation_no(db, row.reservation_code, row.project_id)
        db.commit()
        db.refresh(row)
    else:
        db.commit()
        db.refresh(row)
    return {"ok": True, "id": row.id, "reservation_code": row.reservation_code, "sub_reservation_no": row.sub_reservation_no}


@app.put("/supplier-transfers/{transfer_id}/revision-decision")
def supplier_transfer_revision_decision(
    transfer_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    supplier_company_id = _vehicle_supplier_company_id(db, current_user)
    if supplier_company_id is None:
        raise HTTPException(status_code=403, detail="Only vehicle supplier admin can decide revision")
    decision = str(payload.get("decision") or "").strip().lower()
    note = str(payload.get("note") or "").strip()
    if decision not in {"accept", "reject"}:
        raise HTTPException(status_code=400, detail="decision must be accept or reject")
    row = db.query(Transfer).filter(Transfer.id == int(transfer_id), Transfer.tenant_id == int(current_user.tenant_id or 0)).first()
    if not row:
        raise HTTPException(status_code=404, detail="Transfer not found")
    accepted_projects = _vehicle_accepted_project_ids(db, int(current_user.tenant_id or 0), int(supplier_company_id))
    if int(row.supplier_company_id or 0) != int(supplier_company_id) and int(row.project_id or 0) not in accepted_projects:
        raise HTTPException(status_code=403, detail="Transfer is outside supplier scope")
    if decision == "accept":
        row.vehicle_revision_status = "accepted"
    else:
        row.vehicle_revision_status = "rejected"
    row.vehicle_revision_decision_at = datetime.now(timezone.utc)
    row.vehicle_revision_decision_by_user_id = int(current_user.id)
    row.vehicle_revision_decision_note = note or None
    if decision == "reject":
        db.add(
            ModuleReport(
                tenant_id=int(current_user.tenant_id or 0),
                user_id=int(current_user.id),
                module_name="transfer",
                report_type="warning",
                title="Vehicle revision rejected",
                message=f"Transfer #{row.id} revize talebi araç firması tarafından RED edildi. Not: {note or '-'}",
                source="supplier_transfers",
                payload={"transfer_id": row.id, "decision": "reject", "note": note or "", "supplier_company_id": supplier_company_id},
                resolved=False,
            )
        )
    db.commit()
    return {"ok": True, "id": row.id, "vehicle_revision_status": row.vehicle_revision_status}
    cols = default_cols
    if row and isinstance(row.data, dict):
        db_cols = list(row.data.get("columns") or [])
        if db_cols:
            cols = [str(x or "").strip() or f"Sütun {i+1}" for i, x in enumerate(db_cols)]
    wb = Workbook()
    ws = wb.active
    ws.title = "Programlama"
    ws.append(cols)
    ws.append(["" for _ in cols])
    _autosize_excel_columns(ws, min_px=EXCEL_MIN_COL_PX)
    mem = io.BytesIO()
    wb.save(mem)
    content = mem.getvalue()
    return Response(
        content=content,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="programlama_template.xlsx"'},
    )


@app.post("/toplanti/programlama-grid/import")
def import_programming_grid(
    file: UploadFile = File(...),
    project_id: int | None = Form(default=None),
    mode: str = Form(default="replace"),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, project_id)
    content = file.file.read()
    imp_cols, imp_rows = _parse_programming_grid_file(file.filename or "programlama_template.xlsx", content)
    if not imp_cols:
        raise HTTPException(status_code=400, detail="Dosyada başlık satırı bulunamadı")

    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "programming_grid",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )

    final_cols = list(imp_cols)
    final_rows = list(imp_rows)
    if str(mode or "").strip().lower() == "append" and row and isinstance(row.data, dict):
        old_cols = [str(x or "").strip() or f"Sütun {i+1}" for i, x in enumerate(list(row.data.get("columns") or []))]
        old_rows = list(row.data.get("rows") or [])
        if old_cols:
            merged_cols = list(old_cols)
            for c in imp_cols:
                if c not in merged_cols:
                    merged_cols.append(c)

            def map_rows(cols: list[str], rows: list[list[str]]) -> list[dict]:
                out: list[dict] = []
                for rr in rows:
                    r = list(rr) if isinstance(rr, list) else []
                    obj = {}
                    for i, c in enumerate(cols):
                        obj[c] = str(r[i] if i < len(r) else "")
                    out.append(obj)
                return out

            combined = map_rows(old_cols, old_rows) + map_rows(imp_cols, imp_rows)
            final_cols = merged_cols
            final_rows = [[str(item.get(c, "")) for c in final_cols] for item in combined]

    prev_quick_lists = {"halls": [], "sessions": [], "subtopics": [], "breaks": []}
    if row and isinstance(row.data, dict) and isinstance(row.data.get("quick_lists"), dict):
        q = row.data.get("quick_lists") or {}
        prev_quick_lists = {
            "halls": list((q or {}).get("halls") or []),
            "sessions": list((q or {}).get("sessions") or []),
            "subtopics": list((q or {}).get("subtopics") or []),
            "breaks": list((q or {}).get("breaks") or []),
        }
    clean = {
        "template": "programming_grid",
        "version": 1,
        "columns": final_cols,
        "rows": final_rows,
        "quick_lists": prev_quick_lists,
    }
    if not row:
        row = ModuleData(
            tenant_id=tenant_id,
            project_id=scoped_project_id,
            module_name="toplanti",
            entity_type="programming_grid",
            data=clean,
            created_by_user_id=current_user.id,
            updated_by_user_id=current_user.id,
        )
        db.add(row)
    else:
        row.data = clean
        row.updated_by_user_id = current_user.id
    db.commit()
    db.refresh(row)
    return {
        "ok": True,
        "id": row.id,
        "project_id": row.project_id,
        "columns": clean["columns"],
        "rows": clean["rows"],
        "quick_lists": clean.get("quick_lists") or {"halls": [], "sessions": [], "subtopics": [], "breaks": []},
        "column_count": len(clean["columns"]),
        "row_count": len(clean["rows"]),
    }


