@app.get("/toplanti/salons")
def get_toplanti_salons(
    project_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, project_id)
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "salon_list",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    if not row:
        return {"id": None, "project_id": scoped_project_id, "tenant_id": tenant_id, "salons": []}
    d = dict(row.data or {})
    raw_rows = d.get("salon_rows")
    rows_out: list[dict] = []
    seen: set[str] = set()

    if isinstance(raw_rows, list):
        for item in raw_rows:
            if not isinstance(item, dict):
                continue
            name = re.sub(r"\s+", " ", str(item.get("name") or item.get("salon") or "").strip())
            if not name:
                continue
            key = name.lower()
            if key in seen:
                continue
            seen.add(key)
            rows_out.append(
                {
                    "name": name,
                    "manager_user_ids": [int(x) for x in list(item.get("manager_user_ids") or []) if _safe_int(x)],
                    "supervisor_user_ids": [int(x) for x in list(item.get("supervisor_user_ids") or []) if _safe_int(x)],
                }
            )
            if not rows_out[-1]["manager_user_ids"]:
                one_m = _safe_int(item.get("manager_user_id"))
                if one_m:
                    rows_out[-1]["manager_user_ids"] = [int(one_m)]
            if not rows_out[-1]["supervisor_user_ids"]:
                one_s = _safe_int(item.get("supervisor_user_id"))
                if one_s:
                    rows_out[-1]["supervisor_user_ids"] = [int(one_s)]
    else:
        salons = [str(x or "").strip() for x in list(d.get("salons") or [])]
        salons = [x for x in salons if x]
        for name in salons:
            key = name.lower()
            if key in seen:
                continue
            seen.add(key)
            rows_out.append({"name": name, "manager_user_ids": [], "supervisor_user_ids": []})

    rows_out = sorted(rows_out, key=lambda x: str(x.get("name") or "").lower())
    salon_names = [str(x.get("name") or "").strip() for x in rows_out if str(x.get("name") or "").strip()]
    for row_item in rows_out:
        mids = [int(x) for x in list(row_item.get("manager_user_ids") or []) if _safe_int(x)]
        sids = [int(x) for x in list(row_item.get("supervisor_user_ids") or []) if _safe_int(x)]
        row_item["manager_user_ids"] = mids
        row_item["supervisor_user_ids"] = sids
        row_item["manager_user_id"] = mids[0] if mids else None
        row_item["supervisor_user_id"] = sids[0] if sids else None
    return {
        "id": row.id,
        "project_id": row.project_id,
        "tenant_id": row.tenant_id,
        "salons": salon_names,       # backward compatible
        "salon_rows": rows_out,      # new detailed rows
    }


@app.post("/toplanti/salons/save")
def save_toplanti_salons(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, payload.get("project_id"))
    salons_in = payload.get("salons")
    if not isinstance(salons_in, list):
        raise HTTPException(status_code=400, detail="salons must be an array")
    clean_rows: list[dict] = []
    clean_names: list[str] = []
    seen: set[str] = set()

    def _validate_user_assignment(user_id: int | None) -> int | None:
        if user_id is None:
            return None
        u = db.query(User).filter(User.id == int(user_id)).first()
        if not u:
            raise HTTPException(status_code=400, detail=f"User not found: {user_id}")
        if int(u.tenant_id or 0) != int(tenant_id):
            raise HTTPException(status_code=400, detail=f"User tenant mismatch: {user_id}")
        if not bool(u.is_active):
            raise HTTPException(status_code=400, detail=f"User inactive: {user_id}")
        if not _is_salon_assignable_role(u.role):
            raise HTTPException(status_code=400, detail=f"User role not allowed for salon assignment: {user_id}")
        return int(u.id)
    def _normalize_user_ids(value: object) -> list[int]:
        out: list[int] = []
        seen_local: set[int] = set()
        if isinstance(value, list):
            raw_items = value
        elif isinstance(value, str):
            raw_items = [x.strip() for x in value.split(",") if str(x or "").strip()]
        elif value is None:
            raw_items = []
        else:
            raw_items = [value]
        for raw in raw_items:
            uid = _safe_int(raw)
            if uid is None:
                continue
            uid = int(uid)
            if uid in seen_local:
                continue
            seen_local.add(uid)
            out.append(uid)
        return out

    for item in salons_in:
        manager_user_ids: list[int] = []
        supervisor_user_ids: list[int] = []
        if isinstance(item, dict):
            name = re.sub(r"\s+", " ", str(item.get("name") or item.get("salon") or "").strip())
            manager_user_ids = _normalize_user_ids(item.get("manager_user_ids"))
            supervisor_user_ids = _normalize_user_ids(item.get("supervisor_user_ids"))
            if not manager_user_ids:
                one_m = _safe_int(item.get("manager_user_id"))
                if one_m:
                    manager_user_ids = [int(one_m)]
            if not supervisor_user_ids:
                one_s = _safe_int(item.get("supervisor_user_id"))
                if one_s:
                    supervisor_user_ids = [int(one_s)]
        else:
            name = re.sub(r"\s+", " ", str(item or "").strip())
        if not name:
            continue
        if len(name) < 1 or len(name) > 32 or re.search(r"[\r\n\t]", name):
            continue
        key = name.lower()
        if key in seen:
            continue
        seen.add(key)
        manager_user_ids = [int(y) for y in (_validate_user_assignment(x) for x in manager_user_ids) if y is not None]
        supervisor_user_ids = [int(y) for y in (_validate_user_assignment(x) for x in supervisor_user_ids) if y is not None]
        clean_rows.append(
            {
                "name": name,
                "manager_user_ids": manager_user_ids,
                "supervisor_user_ids": supervisor_user_ids,
                "manager_user_id": manager_user_ids[0] if manager_user_ids else None,
                "supervisor_user_id": supervisor_user_ids[0] if supervisor_user_ids else None,
            }
        )
        clean_names.append(name)
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "salon_list",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    data_obj = {"salons": clean_names, "salon_rows": clean_rows}
    if not row:
        row = ModuleData(
            tenant_id=tenant_id,
            project_id=scoped_project_id,
            module_name="toplanti",
            entity_type="salon_list",
            data=data_obj,
            created_by_user_id=current_user.id,
            updated_by_user_id=current_user.id,
        )
        db.add(row)
    else:
        row.data = data_obj
        row.updated_by_user_id = current_user.id
    db.commit()
    db.refresh(row)
    return {
        "ok": True,
        "id": row.id,
        "project_id": row.project_id,
        "salons": clean_names,
        "salon_rows": clean_rows,
        "count": len(clean_rows),
    }


