@app.post("/toplanti/program/import")
def import_scientific_program(
    file: UploadFile = File(...),
    project_id: int | None = Form(default=None),
    merge_mode: str = Form(default="append"),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "toplanti")
    scoped_project_id, tenant_id = _program_scope(db, current_user, project_id)
    content = file.file.read()
    parsed_rows = _extract_program_rows(file.filename or "program.xls", content)
    imported_sessions, normalize_notes = _normalize_program_sessions_from_rows(parsed_rows)
    row = (
        db.query(ModuleData)
        .filter(
            ModuleData.module_name == "toplanti",
            ModuleData.entity_type == "scientific_program_demo",
            ModuleData.tenant_id == tenant_id,
            ModuleData.project_id == scoped_project_id,
        )
        .order_by(ModuleData.id.desc())
        .first()
    )
    existing_sessions = []
    if row and isinstance(row.data, dict):
        existing_sessions = list(row.data.get("sessions") or [])
    merged = list(existing_sessions) if str(merge_mode or "").strip().lower() == "append" else []
    dedupe = {f"{x.get('day')}|{x.get('hall')}|{x.get('start')}|{x.get('title')}" for x in merged}
    added = 0
    for s in imported_sessions:
        k = f"{s.get('day')}|{s.get('hall')}|{s.get('start')}|{s.get('title')}"
        if k in dedupe:
            normalize_notes.append(f"Aynı kayıt atlandı: {k}")
            continue
        dedupe.add(k)
        merged.append(s)
        added += 1
    payload = {
        "template": "scientific_program",
        "version": 5,
        "name": "Bilimsel Program",
        "sessions": merged,
        "import_meta": {
            "file_name": file.filename,
            "merge_mode": merge_mode,
            "imported_rows": len(imported_sessions),
            "added_rows": added,
        },
    }
    saved_row, sync = _save_program_payload(db, current_user, scoped_project_id, tenant_id, payload)
    db.commit()
    db.refresh(saved_row)
    return {
        "ok": True,
        "id": saved_row.id,
        "project_id": scoped_project_id,
        "imported_rows": len(imported_sessions),
        "added_rows": added,
        "normalize_notes": normalize_notes[:80],
        "linked_person_schedule_count": int(sync.get("linked_records") or 0),
    }


@app.get("/module-data")
def list_module_data(
    module_name: str = Query(...),
    entity_type: str | None = Query(default=None),
    project_id: int | None = Query(default=None),
    tenant_id: int | None = Query(default=None),
    limit: int = Query(default=200, ge=1, le=2000),
    offset: int = Query(default=0, ge=0),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    mod = _normalize_module_name(module_name)
    _require_module_access(db, current_user, mod)
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)

    query = db.query(ModuleData).filter(ModuleData.module_name == mod)
    if not is_superadmin(current_user):
        query = query.filter(ModuleData.tenant_id == current_user.tenant_id)
    elif tenant_id is not None:
        query = query.filter(ModuleData.tenant_id == int(tenant_id))

    if not management_scope:
        query = query.filter(ModuleData.project_id == scoped_project_id)
    elif scoped_project_id is not None:
        query = query.filter(ModuleData.project_id == scoped_project_id)

    if entity_type:
        query = query.filter(ModuleData.entity_type == str(entity_type).strip().lower())

    rows = (
        query.order_by(ModuleData.created_at.desc())
        .offset(offset)
        .limit(limit)
        .all()
    )
    changed = False
    for r in rows:
        if _ensure_kayit_identity_codes(db, r):
            changed = True
        if _ensure_kayit_company_code(db, r):
            changed = True
    if changed:
        db.commit()
    return [
        {
            "id": r.id,
            "tenant_id": r.tenant_id,
            "project_id": r.project_id,
            "module_name": r.module_name,
            "entity_type": r.entity_type,
            "data": _normalize_text_payload(r.data),
            "created_by_user_id": r.created_by_user_id,
            "updated_by_user_id": r.updated_by_user_id,
            "created_at": r.created_at,
            "updated_at": r.updated_at,
        }
        for r in rows
    ]


