@app.post("/kayit/people/import-xlsx")
async def import_kayit_people_xlsx(
    file: UploadFile = File(...),
    project_id: int | None = Form(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "kayit")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    tenant_scope = _resolve_tenant_for_module_data(db, current_user, scoped_project_id, None)
    content = await file.read()
    try:
        wb = load_workbook(io.BytesIO(content))
        ws = wb.active
    except Exception:
        raise HTTPException(status_code=400, detail="XLSX dosyası okunamadı.")
    headers = [_clean_xlsx_text(ws.cell(row=1, column=idx).value) for idx in range(1, ws.max_column + 1)]
    header_map = {label: idx for idx, label in enumerate(headers)}
    created = 0
    updated = 0
    existing_rows = _resolve_kayit_rows_for_export(
        db, current_user, "people", project_id=scoped_project_id, row_ids=[]
    )[1]
    existing_by_org_id: dict[str, ModuleData] = {}
    for existing in existing_rows:
        existing_data = _kayit_people_data_for_row(db, existing)
        org_id = str(existing_data.get("organization_id") or "").strip().upper()
        if org_id:
            existing_by_org_id[org_id] = existing
    for row_idx in range(2, ws.max_row + 1):
        values = {label: _clean_xlsx_text(ws.cell(row=row_idx, column=idx + 1).value) for idx, label in enumerate(headers) if label}
        if not any(values.values()):
            continue
        if _matches_template_sample(values, KAYIT_PEOPLE_EXPORT_COLUMNS, KAYIT_PEOPLE_TEMPLATE_SAMPLE):
            continue
        import_importance = _normalize_importance_level_value(values.get("Önem", ""))
        if str(values.get("Önem", "")).strip() and not import_importance:
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: Önem yalnızca A1-E9 aralığında olabilir")
        import_gender = _normalize_gender_value(values.get("Cinsiyet", ""))
        if str(values.get("Cinsiyet", "")).strip() and not import_gender:
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: Cinsiyet yalnızca Kadın, Erkek veya Belirtmek İstemiyor olabilir")
        raw_birth = str(values.get("Doğum Tarihi", "")).strip()
        parsed_birth = _parse_tr_date_for_storage(raw_birth)
        if raw_birth and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", parsed_birth):
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: Doğum Tarihi gg.aa.yyyy formatında olmalıdır")
        import_org_id = str(values.get("ID") or "").strip().upper()
        if import_org_id and not re.fullmatch(r"[A-Z0-9]{6}-[A-Z0-9]{6}", import_org_id):
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: ID DFL003-U67AA9 formatında olmalıdır")
        row_obj = existing_by_org_id.get(import_org_id) if import_org_id else None
        if import_org_id and row_obj is None:
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: ID sistemde bulunamadı")
        data_obj = dict(row_obj.data or {}) if row_obj and isinstance(row_obj.data, dict) else {}
        field_map = {
            "Önem": "importance_level",
            "Sebep": "importance_reason",
            "Görev": "unvan",
            "Akademik Ünvan": "akademik_unvan",
            "İsim": "isim",
            "Soyisim": "soyisim",
            "Kimlik No": "kimlik_no",
            "Doğum Tarihi": "dogum_tarihi",
            "Cinsiyet": "cinsiyet",
            "Telefon": "telefon",
            "Mail": "mail",
            "Kurum": "kurum",
            "Adres": "adres",
            "Asistan": "asistan",
            "Asistan Telefon": "asistan_telefon",
            "Transfer Detay": "transfer_detay",
            "Konaklama Detay": "konaklama_detay",
            "Genel Not": "general_note",
        }
        for label, target_key in field_map.items():
            if label in values:
                next_value = values.get(label, "")
                if target_key == "importance_level":
                    next_value = import_importance
                elif target_key == "cinsiyet":
                    next_value = import_gender
                elif target_key == "dogum_tarihi":
                    next_value = _parse_tr_date_for_storage(next_value)
                elif target_key in {"telefon", "asistan_telefon"}:
                    next_value = _normalize_kayit_phone_value(next_value)
                data_obj[target_key] = next_value
        if row_obj:
            row_obj.data = _normalize_text_payload(data_obj)
            row_obj.updated_by_user_id = current_user.id
            _ensure_kayit_identity_codes(db, row_obj)
            updated += 1
        else:
            row_obj = ModuleData(
                tenant_id=tenant_scope,
                project_id=scoped_project_id,
                module_name="kayit",
                entity_type=None,
                data=_normalize_text_payload(data_obj),
                created_by_user_id=current_user.id,
                updated_by_user_id=current_user.id,
            )
            db.add(row_obj)
            db.flush()
            _ensure_kayit_identity_codes(db, row_obj)
            existing_data = _kayit_people_data_for_row(db, row_obj)
            created_org_id = str(existing_data.get("organization_id") or "").strip().upper()
            if created_org_id:
                existing_by_org_id[created_org_id] = row_obj
            created += 1
    db.commit()
    return {"ok": True, "created": created, "updated": updated}


@app.post("/kayit/companies/import-xlsx")
async def import_kayit_companies_xlsx(
    file: UploadFile = File(...),
    project_id: int | None = Form(default=None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    _require_module_access(db, current_user, "kayit")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, project_id)
    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")
    tenant_scope = _resolve_tenant_for_module_data(db, current_user, scoped_project_id, None)
    content = await file.read()
    try:
        wb = load_workbook(io.BytesIO(content))
        ws = wb.active
    except Exception:
        raise HTTPException(status_code=400, detail="XLSX dosyası okunamadı.")
    headers = [_clean_xlsx_text(ws.cell(row=1, column=idx).value) for idx in range(1, ws.max_column + 1)]
    created = 0
    updated = 0
    existing_rows = _resolve_kayit_rows_for_export(
        db, current_user, "companies", project_id=scoped_project_id, row_ids=[]
    )[1]
    existing_by_company_code: dict[str, ModuleData] = {}
    for existing in existing_rows:
        existing_data = _kayit_company_data_for_row(db, existing)
        company_code = str(existing_data.get("company_code") or "").strip().upper()
        if company_code:
            existing_by_company_code[company_code] = existing
    for row_idx in range(2, ws.max_row + 1):
        values = {label: _clean_xlsx_text(ws.cell(row=row_idx, column=idx + 1).value) for idx, label in enumerate(headers) if label}
        if not any(values.values()):
            continue
        if _matches_template_sample(values, KAYIT_COMPANY_EXPORT_COLUMNS, KAYIT_COMPANY_TEMPLATE_SAMPLE):
            continue
        import_company_code = str(values.get("Firma Kodu") or "").strip().upper()
        if import_company_code and not re.fullmatch(r"[A-Z0-9]{6}-F\d{3}", import_company_code):
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: Firma Kodu DFL003-F001 formatında olmalıdır")
        row_obj = existing_by_company_code.get(import_company_code) if import_company_code else None
        if import_company_code and row_obj is None:
            raise HTTPException(status_code=400, detail=f"Satır {row_idx}: Firma Kodu sistemde bulunamadı")
        data_obj = dict(row_obj.data or {}) if row_obj and isinstance(row_obj.data, dict) else {}
        field_map = {
            "Firma Adı": "display_name",
            "Firma Ünvanı": "legal_name",
            "Firma Temsilcisi": "representative_name",
            "Temsilci Telefon": "representative_phone",
            "Temsilci Mail": "representative_email",
            "İl": "city",
            "İlçe": "district",
            "Açık Adres": "address",
            "Firma Telefonu": "company_phone",
            "Vergi Dairesi": "tax_office",
            "Vergi No": "tax_number",
            "Not": "note",
        }
        for label, target_key in field_map.items():
            if label in values:
                next_value = values.get(label, "")
                if target_key in {"representative_phone", "company_phone"}:
                    next_value = _normalize_kayit_phone_value(next_value)
                data_obj[target_key] = next_value
        if row_obj:
            row_obj.data = _normalize_text_payload(data_obj)
            row_obj.updated_by_user_id = current_user.id
            _ensure_kayit_company_code(db, row_obj)
            updated += 1
        else:
            row_obj = ModuleData(
                tenant_id=tenant_scope,
                project_id=scoped_project_id,
                module_name="kayit",
                entity_type="sponsor_firma",
                data=_normalize_text_payload(data_obj),
                created_by_user_id=current_user.id,
                updated_by_user_id=current_user.id,
            )
            db.add(row_obj)
            db.flush()
            _ensure_kayit_company_code(db, row_obj)
            existing_data = _kayit_company_data_for_row(db, row_obj)
            created_company_code = str(existing_data.get("company_code") or "").strip().upper()
            if created_company_code:
                existing_by_company_code[created_company_code] = row_obj
            created += 1
    db.commit()
    return {"ok": True, "created": created, "updated": updated}


@app.get("/module-data/{row_id}/organization-qr")
def get_module_data_organization_qr(
    row_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    row = db.query(ModuleData).filter(ModuleData.id == row_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="Record not found")
    _require_module_access(db, current_user, str(row.module_name or ""))
    if not is_superadmin(current_user) and int(row.tenant_id or 0) != int(current_user.tenant_id or 0):
        raise HTTPException(status_code=403, detail="forbidden")
    scoped_project_id, management_scope = _resolve_project_scope_for_user(db, current_user, row.project_id)
    if not management_scope and row.project_id != scoped_project_id:
        raise HTTPException(status_code=403, detail="forbidden")
    data_obj = _normalize_text_payload(row.data or {})
    entity_type = str(row.entity_type or "").strip().lower()
    if entity_type in {"sponsor_firma", "company", "firma"}:
        org_id = _format_firm_code(db, row)
        payload = org_id
    else:
        if _ensure_kayit_identity_codes(db, row):
            db.commit()
            db.refresh(row)
            data_obj = _normalize_text_payload(row.data or {})
        org_id = str(
            data_obj.get("organizasyon_kimligi")
            or data_obj.get("organizasyon_kimligi")
            or data_obj.get("organization_id")
            or data_obj.get("organization_qr_payload")
            or data_obj.get("project_person_code")
            or ""
        ).strip()
        if not org_id:
            org_id = _format_person_code(int(row.id or 0))
        project = db.query(Project).filter(Project.id == row.project_id).first() if row.project_id else None
        project_code = _compact_project_code(str((project.system_code if project and project.system_code else project.operation_code if project else "") or ""))
        payload = str(data_obj.get("organization_qr_payload") or org_id or f"{project_code}-{_format_person_code(int(row.id or 0))}").strip()
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=10,
        border=4,
    )
    qr.add_data(payload)
    qr.make(fit=True)
    img = qr.make_image(fill_color=(18, 32, 74), back_color=(255, 255, 255)).convert("RGB")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    headers = {
        "X-QR-Payload": payload,
        "X-Organization-Id": org_id,
        "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
        "Pragma": "no-cache",
        "Expires": "0",
    }
    return StreamingResponse(buf, media_type="image/png", headers=headers)


@app.get("/module-data/{row_id}/organization-qr-popup", response_class=HTMLResponse)
def get_module_data_organization_qr_popup(
    row_id: int,
    access_token: str | None = Query(default=None),
):
    token_value = str(access_token or "").strip()
    token_js = json.dumps(token_value)
    html = f"""<!doctype html>
<html lang="tr">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>QR</title>
  <style>
    html, body {{ width:100%; height:100%; margin:0; }}
    body {{
      font-family: Arial, sans-serif;
      padding: 0;
      text-align: center;
      background: #f8fbff;
      color: #1c2635;
    }}
    .shell {{
      min-height: 100vh;
      display:flex;
      align-items:center;
      justify-content:center;
      padding: 12px;
    }}
    .card {{
      width: min(92vw, 860px);
      min-height: min(92vh, 860px);
      background:#fff;
      border:1px solid #dde4ef;
      border-radius:18px;
      padding:18px;
      display:flex;
      flex-direction:column;
      align-items:center;
      justify-content:center;
      gap:12px;
      box-shadow: 0 18px 48px rgba(10,16,36,0.12);
    }}
    img {{
      width: min(76vw, 760px);
      height: min(76vw, 760px);
      max-width: calc(100vh - 120px);
      max-height: calc(100vh - 120px);
      object-fit: contain;
      background:#fff;
    }}
    .muted {{
      color:#182240;
      font-size:26px;
      font-weight:700;
      word-break:break-all;
      letter-spacing:0.5px;
      margin-top:8px;
      line-height:1.08;
    }}
    .err {{ color:#b42318; font-size:15px; margin-top:8px; }}
  </style>
</head>
<body>
  <div class="shell">
    <div class="card">
      <div id="loading">Yükleniyor...</div>
      <img id="qrImage" alt="Organizasyon Karekodu" style="display:none;" />
      <div id="qrPayload" class="muted"></div>
    </div>
  </div>
  <script>
    (function() {{
      var token = {token_js}
        || localStorage.getItem("access_token")
        || sessionStorage.getItem("access_token")
        || localStorage.getItem("token")
        || sessionStorage.getItem("token")
        || "";
      var loadingEl = document.getElementById("loading");
      var imgEl = document.getElementById("qrImage");
      var payloadEl = document.getElementById("qrPayload");
      if (!token) {{
        loadingEl.className = "err";
        loadingEl.textContent = "Oturum doğrulanamadı.";
        return;
      }}
      fetch("/module-data/{row_id}/organization-qr?_ts=" + Date.now(), {{
        headers: {{ Authorization: "Bearer " + token }},
        credentials: "include"
      }})
        .then(function(res) {{
          if (!res.ok) throw new Error("Organizasyon karekodu yüklenemedi.");
          var payload = res.headers.get("X-QR-Payload") || "";
          return res.blob().then(function(blob) {{ return {{ blob: blob, payload: payload }}; }});
        }})
        .then(function(result) {{
          var imgUrl = URL.createObjectURL(result.blob);
          imgEl.onload = function() {{ URL.revokeObjectURL(imgUrl); }};
          imgEl.src = imgUrl;
          imgEl.style.display = "inline-block";
          payloadEl.textContent = result.payload;
          loadingEl.style.display = "none";
        }})
        .catch(function(err) {{
          loadingEl.className = "err";
          loadingEl.textContent = (err && err.message) ? err.message : "Organizasyon karekodu yüklenemedi.";
        }});
    }})();
  </script>
</body>
</html>"""
    return HTMLResponse(html)


@app.post("/module-data")
def create_module_data(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    mod = _normalize_module_name(payload.get("module_name"))
    _require_module_access(db, current_user, mod)
    scoped_project_id, management_scope = _resolve_project_scope_for_user(
        db, current_user, payload.get("project_id")
    )
    raw_tenant = payload.get("tenant_id")
    payload_tenant_id: int | None = None
    if raw_tenant is not None and str(raw_tenant).strip() != "":
        try:
            payload_tenant_id = int(raw_tenant)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="tenant_id must be integer")
    tenant_scope = _resolve_tenant_for_module_data(
        db,
        current_user,
        scoped_project_id,
        payload_tenant_id,
    )

    if not management_scope and scoped_project_id is None:
        raise HTTPException(status_code=400, detail="Active project required")

    entity_type = str(payload.get("entity_type") or "").strip().lower() or None
    data_obj = payload.get("data")
    if not isinstance(data_obj, dict):
        raise HTTPException(status_code=400, detail="data must be an object")
    data_obj = _normalize_text_payload(data_obj)
    if mod in MODULES_REQUIRING_KAYIT:
        kayit_id = _extract_kayit_id_from_payload(payload)
        kayit_id = _ensure_kayit_exists_for_scope(db, tenant_scope, scoped_project_id, kayit_id)
        data_obj["kayit_id"] = kayit_id

    row = ModuleData(
        tenant_id=tenant_scope,
        project_id=scoped_project_id,
        module_name=mod,
        entity_type=entity_type,
        data=data_obj,
        created_by_user_id=current_user.id,
        updated_by_user_id=current_user.id,
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    if _ensure_kayit_identity_codes(db, row):
        db.commit()
        db.refresh(row)
    if _ensure_kayit_company_code(db, row):
        db.commit()
        db.refresh(row)
    return {
        "id": row.id,
        "tenant_id": row.tenant_id,
        "project_id": row.project_id,
        "module_name": row.module_name,
        "entity_type": row.entity_type,
        "data": row.data,
        "created_by_user_id": row.created_by_user_id,
        "updated_by_user_id": row.updated_by_user_id,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


@app.put("/module-data/{row_id}")
def update_module_data(
    row_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_auth),
):
    row = db.query(ModuleData).filter(ModuleData.id == row_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="Record not found")
    _require_module_access(db, current_user, str(row.module_name or ""))

    scoped_project_id, management_scope = _resolve_project_scope_for_user(
        db, current_user, payload.get("project_id")
    )
    if not is_superadmin(current_user) and row.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=403, detail="forbidden")
    if not management_scope:
        if row.project_id != scoped_project_id:
            raise HTTPException(status_code=403, detail="forbidden")
    elif scoped_project_id is not None and row.project_id != scoped_project_id:
        raise HTTPException(status_code=403, detail="forbidden")

    if "module_name" in payload:
        new_module_name = _normalize_module_name(payload.get("module_name"))
        _require_module_access(db, current_user, new_module_name)
        row.module_name = new_module_name
    if "entity_type" in payload:
        row.entity_type = str(payload.get("entity_type") or "").strip().lower() or None
    if "data" in payload:
        data_obj = payload.get("data")
        if not isinstance(data_obj, dict):
            raise HTTPException(status_code=400, detail="data must be an object")
        data_obj = _normalize_text_payload(data_obj)
        if row.module_name in MODULES_REQUIRING_KAYIT:
            kayit_id = _extract_kayit_id_from_payload({"data": data_obj, "kayit_id": payload.get("kayit_id")})
            kayit_id = _ensure_kayit_exists_for_scope(db, int(row.tenant_id or 0), row.project_id, kayit_id)
            data_obj["kayit_id"] = kayit_id
        row.data = data_obj
    elif row.module_name in MODULES_REQUIRING_KAYIT and "kayit_id" in payload:
        data_obj = dict(row.data or {})
        kayit_id = _extract_kayit_id_from_payload(payload)
        kayit_id = _ensure_kayit_exists_for_scope(db, int(row.tenant_id or 0), row.project_id, kayit_id)
        data_obj["kayit_id"] = kayit_id
        row.data = data_obj
    row.updated_by_user_id = current_user.id
    _ensure_kayit_identity_codes(db, row)
    _ensure_kayit_company_code(db, row)
    db.commit()
    db.refresh(row)
    return {
        "id": row.id,
        "tenant_id": row.tenant_id,
        "project_id": row.project_id,
        "module_name": row.module_name,
        "entity_type": row.entity_type,
        "data": row.data,
        "created_by_user_id": row.created_by_user_id,
        "updated_by_user_id": row.updated_by_user_id,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


